-- ════════════════════════════════════════════════════════
-- 240 — Huitième recensement : quinze maisons des catalogues
--       (lots d'écriture 04, 05 et 07)
-- ────────────────────────────────────────────────────────
-- D'OÙ ELLES VIENNENT. Comme la 239 : des noms que le marché vend et
-- que l'atlas n'avait pas, passés par le tri, le contradicteur, le
-- rédacteur, la relecture et la traduction.
--   Rép. dominicaine  Arnold André (usine propre, Santiago), D'Crossier
--                     (ABAM, Villa Mella), Bugatti (PDR, Kelner Boutique
--                     Factory, Victor Sinclair), Caoba (usine propre,
--                     Saint-Domingue), Castillo de Reyes (atelier de
--                     Felix Reyes, Tamboril)
--   Honduras          Wolfertz (Raíces Cubanas, Danlí) ; Dios del Sol,
--                     Flor del Sol, Kinix, Rodrigo de Jerez
--   Nicaragua         American Caribbean Cigars (usine propre, Estelí),
--                     Daniel Marshall (Plasencia) ; Dos Amigos, T. Sonthi
--   Panama            Darier & Cleef (usine propre)
--
-- ── LES MAISONS À PLUSIEURS MARQUES ─────────────────────
-- Quand le propriétaire d'une marque possède aussi la fabrique qui la
-- roule, la marque est une ligne de sa maison. Quatre maisons absentes
-- de l'atlas reçoivent donc une fiche qui range dans leur gamme des noms
-- du recensement :
--   Arnold André                Parcero, Buena Vista, Beast, Montosa,
--                               Carlos André
--   American Caribbean Cigars   The Bouncer, El Viejo Continente,
--                               Maradona Tribute, The Traveler, El Copey
--   D'Crossier                  Flor de D'Crossier
--   Darier & Cleef              Colón, Cruzero de Panamá
-- Arnold André fait aussi des cigares de machine à Bünde ; sa fiche ne
-- porte que les longfillers roulés à la main à Santiago. American
-- Caribbean roule pour Toraño, Leccia Tobacco et le Vintage Rock-A-Feller
-- Cigar Group, qui vont en `mentions` (238).
--
-- ── LE SILENCE ÉCRIT ────────────────────────────────────
-- Dios del Sol, Flor del Sol, Kinix, Rodrigo de Jerez, Dos Amigos et
-- T. Sonthi : le propriétaire est identifié et le pays de roulage
-- attesté, la fabrique n'est nommée nulle part. La fiche le dit
-- (décision du 23 septembre, précédent Curivari).
--
-- ── CE QUE LA RELECTURE A TRANCHÉ ───────────────────────
-- Bugatti est récrite : c'est la marque du Bugatti Group (Yigal Harel)
-- depuis 2015. Perdomo l'a roulée en premier ; elle se roule aujourd'hui
-- chez PDR, à la Kelner Boutique Factory et chez Victor Sinclair.
-- Wolfertz est passée au groupe belge VCF au 1er janvier 2023. Barrio
-- Viejo, que la maison vendait, aura sa propre fiche et n'est pas une
-- mention. Les états se datent (septembre 2026). Les éloges de
-- détaillant sortent. Aucune revue à notes n'est nommée et « fondée
-- en » ne date que la maison : les leçons de la 239 sont appliquées
-- avant la traduction.
--
-- ── DIVERGENCES ÉCRITES ─────────────────────────────────
-- Darier & Cleef : 1881 selon des détaillants allemands, alors que la
-- presse panaméenne tient Joyas de Panamá (1986) pour la première
-- fabrique permanente du pays. Flor del Sol : en vente dès 2014, sans
-- date de fondation connue.
--
-- Rejouable : INSERT … ON DUPLICATE KEY UPDATE ; le `brands` des pays
-- touchés est relu en base et réécrit en littéral ; sceaux `machine`.
-- ════════════════════════════════════════════════════════

-- ── Arnold André ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Arnold André',
        'dominican',
        '1817 — famille André, Osnabrück ; Santiago 2011',
        'Usine propre — Arnold André Dominicana S.R.L., zone franche de Santiago de los Caballeros (République dominicaine)',
        'arnold-andre.info « Long Filler Cigars — Brands » (consulté 2026-09 : recense Parcero, Buena Vista, Montosa et Carlos André comme marques longfiller roulées à la main en République dominicaine) ; cigarjournal.com « A Visit to the Company Arnold André » (2017-07-31 : fondation en 1817 à Osnabrück, implantation à Bünde en 1851, usine dominicaine ouverte en 2011 à Santiago de los Caballeros, transfert complet du roulage longfiller en 2015, lancements Carlos André 2009, Buena Vista 2013, Beast 2016) ; cigar-coop.com « Procigar 2025: Arnold André Tour » (2025-02 : confirme l''usine Arnold André Dominicana à Santiago, roulage main depuis 2015) ; cigarworld.de « Parcero », « Buena Vista », « Beast » et « Montosa » (fiches marques : cape, mélange, conditionnement et nombre de références de chaque ligne) ; carlos-andre.com (fiches produit Carlos André : cape Connecticut Shade Desflorado équatorienne) ; cigarslover.com « Parcero Brasil Robusto » (revue : cape Mata Fina, tabacs brésiliens et dominicains, cigare peu corsé) ; thecigarauthority.com « Montosa Maduro Toro Cigar Review » (revue : cape San Andrés mexicaine pour la version Maduro)',
        NULL,
        'Arnold André est une maison familiale allemande fondée en 1817 par Johann Friedrich Christian André à Osnabrück, pour le tabac à fumer ; la famille André s''installe à Bünde (Rhénanie-du-Nord-Westphalie) en 1851, où l''entreprise reste basée sept générations plus tard. Pour ses cigares roulés à la main, elle ouvre en 2011 une manufacture propre, Arnold André Dominicana S.R.L., dans la zone franche industrielle de Santiago de los Caballeros ; le transfert complet du roulage des longfillers vers cette usine s''achève en 2015. À Bünde, la maison fabrique par ailleurs des cigares et cigarillos à la machine.

Le catalogue propre bâti à Santiago rassemble cinq marques longfiller. Carlos André, lancée en 2009 en l''honneur du fils cadet du propriétaire Axel-Georg André, est roulée sous cape Connecticut Shade Desflorado équatorienne. Buena Vista (2013) marie, dit la maison, des tabacs dominicains, brésiliens, péruviens et nicaraguayens, dont un rare Araperique brésilien selon la méthode Perique. Beast (2016), projet personnel d''Axel-Georg André, associe cape mexicaine San Andrés, sous-cape Sumatra et tripe brésilienne et nicaraguayenne. Montosa, arrivée aux États-Unis en 2022, se décline en Natural (Connecticut Shade équatorienne) et Maduro (San Andrés mexicaine). Parcero, enfin, débute au printemps 2021 en version Dominicano à cape mexicaine, complétée en 2022 par une version Brasil à cape Mata Fina.',
        '[{"name":"Parcero","color":"#A0522D","force":"Mild","wrapper":"Non divulguée","vitolas":[],"story":"Deux versions selon Cigarworld et Cigar''s Lover Magazine : Dominicano, cape mexicaine, lancée au printemps 2021, et Brasil, cape Mata Fina, ajoutée en 2022 ; peu corsé selon cigarslover.com."},{"name":"Buena Vista","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Lancée en 2013 ; le mélange marie, dit la maison, des tabacs dominicains, brésiliens, péruviens et nicaraguayens, avec un rare Araperique brésilien selon la méthode Perique. Vingt-trois références au catalogue de Cigarworld.de."},{"name":"Beast","color":"#6B4226","force":null,"wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Projet personnel du propriétaire Axel-Georg André, lancé en 2016 ; sous-cape Sumatra, tripe brésilienne et nicaraguayenne, conditionné en « Fresh Pack » selon Cigarworld.de."},{"name":"Montosa","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Deux versions selon les détaillants : Natural, à cape Connecticut Shade équatorienne plus douce, et Maduro, à cape San Andrés mexicaine plus épicée ; arrivée aux États-Unis en 2022."},{"name":"Carlos André","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade (Équateur)","vitolas":[],"story":"Lancée en 2009 et nommée pour le fils cadet du propriétaire Axel-Georg André ; cape Connecticut Shade Desflorado équatorienne selon carlos-andre.com."}]',
        'Arnold André is a German family company founded in 1817 by Johann Friedrich Christian André in Osnabrück to produce smoking tobacco; the André family moved to Bünde (North Rhine-Westphalia) in 1851, where the company is still based seven generations later. For its hand-rolled cigars, it opened its own factory in 2011, Arnold André Dominicana S.R.L., in the industrial free-trade zone of Santiago de los Caballeros; the complete transfer of long-filler rolling to this factory was finished in 2015. In Bünde, the company also makes machine-made cigars and cigarillos.

The house range built up in Santiago comprises five long-filler brands. Carlos André, launched in 2009 and named for owner Axel-Georg André''s younger son, is rolled under an Ecuadorian Connecticut Shade Desflorado wrapper. Buena Vista (2013) blends, the company says, Dominican, Brazilian, Peruvian and Nicaraguan tobaccos, including a rare Brazilian Araperique made by the Perique method. Beast (2016), Axel-Georg André''s personal project, combines a Mexican San Andrés wrapper, a Sumatra binder and Brazilian and Nicaraguan filler. Montosa, which reached the United States in 2022, comes in Natural (Ecuadorian Connecticut Shade) and Maduro (Mexican San Andrés). Parcero, lastly, began in spring 2021 in a Dominicano version with a Mexican wrapper, joined in 2022 by a Brasil version with a Mata Fina wrapper.',
        '[{"name":"Parcero","color":"#A0522D","force":"Mild","wrapper":"Undisclosed","vitolas":[],"story":"Two versions according to Cigarworld and Cigar''s Lover Magazine: Dominicano, with a Mexican wrapper, launched in spring 2021, and Brasil, with a Mata Fina wrapper, added in 2022; mild-bodied according to cigarslover.com."},{"name":"Buena Vista","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Launched in 2013; the blend combines, the company says, Dominican, Brazilian, Peruvian and Nicaraguan tobaccos, with a rare Brazilian Araperique made by the Perique method. Twenty-three items listed on Cigarworld.de."},{"name":"Beast","color":"#6B4226","force":null,"wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Owner Axel-Georg André''s personal project, launched in 2016; Sumatra binder, Brazilian and Nicaraguan filler, packaged as a Fresh Pack according to Cigarworld.de."},{"name":"Montosa","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Two versions according to retailers: Natural, with a milder Ecuadorian Connecticut Shade wrapper, and Maduro, with a spicier Mexican San Andrés wrapper; it reached the United States in 2022."},{"name":"Carlos André","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Launched in 2009 and named for owner Axel-Georg André''s younger son; Ecuadorian Connecticut Shade Desflorado wrapper, according to carlos-andre.com."}]',
        'Arnold André es una casa familiar alemana fundada en 1817 por Johann Friedrich Christian André en Osnabrück, para tabaco de fumar; la familia André se instala en Bünde (Renania del Norte-Westfalia) en 1851, donde la empresa sigue teniendo su sede siete generaciones después. Para sus puros hechos a mano, abre en 2011 una fábrica propia, Arnold André Dominicana S.R.L., en la zona franca industrial de Santiago de los Caballeros; el traslado completo del torcido de los longfiller a esta fábrica se completa en 2015. En Bünde, la casa fabrica además puros y puritos a máquina.

El catálogo propio creado en Santiago reúne cinco marcas longfiller. Carlos André, lanzada en 2009 y bautizada en honor al hijo menor del propietario Axel-Georg André, se elabora bajo capa ecuatoriana Connecticut Shade Desflorado. Buena Vista (2013) combina, según la casa, tabacos dominicanos, brasileños, peruanos y nicaragüenses, entre ellos un raro Araperique brasileño elaborado según el método Perique. Beast (2016), proyecto personal de Axel-Georg André, une capa mexicana San Andrés, capote de Sumatra y tripa brasileña y nicaragüense. Montosa, que llega a Estados Unidos en 2022, se presenta en Natural (Connecticut Shade ecuatoriana) y Maduro (San Andrés mexicana). Parcero, por último, comienza en la primavera de 2021 en versión Dominicano con capa mexicana, a la que se suma en 2022 una versión Brasil con capa Mata Fina.',
        '[{"name":"Parcero","color":"#A0522D","force":"Mild","wrapper":"No divulgada","vitolas":[],"story":"Dos versiones según Cigarworld y Cigar''s Lover Magazine: Dominicano, con capa mexicana, lanzada en primavera de 2021, y Brasil, con capa Mata Fina, añadida en 2022; suave según cigarslover.com."},{"name":"Buena Vista","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Lanzada en 2013; la mezcla combina, según la casa, tabacos dominicanos, brasileños, peruanos y nicaragüenses, con un raro Araperique brasileño elaborado según el método Perique. Veintitrés referencias en el catálogo de Cigarworld.de."},{"name":"Beast","color":"#6B4226","force":null,"wrapper":"San Andrés (México)","vitolas":[],"story":"Proyecto personal del propietario Axel-Georg André, lanzado en 2016; capote de Sumatra, tripa brasileña y nicaragüense, presentado en formato Fresh Pack según Cigarworld.de."},{"name":"Montosa","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Dos versiones según los detallistas: Natural, con capa Connecticut Shade ecuatoriana más suave, y Maduro, con capa San Andrés mexicana más especiada; llegó a Estados Unidos en 2022."},{"name":"Carlos André","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Lanzada en 2009 y bautizada en honor al hijo menor del propietario Axel-Georg André; capa Connecticut Shade Desflorado ecuatoriana según carlos-andre.com."}]',
        'Arnold André ist ein deutsches Familienunternehmen, das 1817 von Johann Friedrich Christian André in Osnabrück für Rauchtabak gegründet wurde; 1851 zieht die Familie André nach Bünde (Nordrhein-Westfalen), wo das Unternehmen sieben Generationen später noch immer seinen Sitz hat. Für seine handgerollten Zigarren eröffnet es 2011 eine eigene Fabrik, die Arnold André Dominicana S.R.L., in der Industriefreizone von Santiago de los Caballeros; die vollständige Verlagerung des Long-Filler-Rollens in diese Fabrik ist 2015 abgeschlossen. In Bünde stellt das Haus außerdem maschinell gefertigte Zigarren und Zigarillos her.

Das in Santiago aufgebaute eigene Sortiment umfasst fünf Long-Filler-Marken. Carlos André, 2009 zu Ehren des jüngeren Sohns von Inhaber Axel-Georg André lanciert, wird unter einem ecuadorianischen Connecticut-Shade-Desflorado-Deckblatt gerollt. Buena Vista (2013) vereint, so das Haus, dominikanische, brasilianische, peruanische und nicaraguanische Tabake, darunter ein seltenes brasilianisches Araperique nach der Perique-Methode. Beast (2016), ein persönliches Projekt von Axel-Georg André, verbindet ein mexikanisches San-Andrés-Deckblatt, ein Sumatra-Umblatt und brasilianische sowie nicaraguanische Einlage. Montosa, seit 2022 in den Vereinigten Staaten erhältlich, gibt es als Natural (ecuadorianisches Connecticut Shade) und Maduro (mexikanisches San Andrés). Parcero schließlich startet im Frühjahr 2021 mit einer Version Dominicano mit mexikanischem Deckblatt, ergänzt 2022 um eine Version Brasil mit Mata-Fina-Deckblatt.',
        '[{"name":"Parcero","color":"#A0522D","force":"Mild","wrapper":"Nicht angegeben","vitolas":[],"story":"Zwei Versionen laut Cigarworld und Cigar''s Lover Magazine: Dominicano, mit mexikanischem Deckblatt, im Frühjahr 2021 lanciert, und Brasil, mit Mata-Fina-Deckblatt, 2022 hinzugefügt; laut cigarslover.com mild."},{"name":"Buena Vista","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"2013 lanciert; die Mischung vereint, so das Haus, dominikanische, brasilianische, peruanische und nicaraguanische Tabake, mit einem seltenen brasilianischen Araperique nach der Perique-Methode. Dreiundzwanzig Positionen im Katalog von Cigarworld.de."},{"name":"Beast","color":"#6B4226","force":null,"wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Persönliches Projekt von Inhaber Axel-Georg André, 2016 lanciert; Sumatra-Umblatt, brasilianische und nicaraguanische Einlage, laut Cigarworld.de im Fresh-Pack-Format verpackt."},{"name":"Montosa","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Zwei Versionen laut Händlern: Natural, mit milderem ecuadorianischem Connecticut-Shade-Deckblatt, und Maduro, mit würzigerem mexikanischem San-Andrés-Deckblatt; seit 2022 in den Vereinigten Staaten erhältlich."},{"name":"Carlos André","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"2009 lanciert und benannt nach dem jüngeren Sohn von Inhaber Axel-Georg André; ecuadorianisches Connecticut-Shade-Desflorado-Deckblatt laut carlos-andre.com."}]',
        'Arnold André是一家德国家族企业，1817年由Johann Friedrich Christian André在Osnabrück创立，最初生产的是烟丝；1851年，André家族迁往北莱茵-威斯特法伦州的Bünde，七代之后企业总部仍设于当地。为生产手工雪茄，公司于2011年在Santiago de los Caballeros工业自由区开设了自有工厂Arnold André Dominicana S.R.L.；长茄芯雪茄的卷制工序全部转移至该厂，于2015年完成。在Bünde，公司还以机器生产雪茄和小雪茄。

在Santiago建立起的自有产品线共有五个长茄芯品牌。Carlos André于2009年推出，以纪念庄主Axel-Georg André的幼子，采用厄瓜多尔Connecticut Shade Desflorado茄衣卷制。Buena Vista（2013年）据该品牌称，调配了多米尼加、巴西、秘鲁和尼加拉瓜烟叶，其中包括一种按Perique法处理的稀有巴西Araperique烟叶。Beast（2016年）是Axel-Georg André的个人项目，采用墨西哥San Andrés茄衣、Sumatra茄套，以及巴西和尼加拉瓜茄芯。Montosa于2022年进入美国市场，分为Natural（厄瓜多尔Connecticut Shade）和Maduro（墨西哥San Andrés）两款。Parcero则于2021年春季以Dominicano版本（墨西哥茄衣）问世，2022年又增加了Brasil版本（Mata Fina茄衣）。',
        '[{"name":"Parcero","color":"#A0522D","force":"Mild","wrapper":"未公开","vitolas":[],"story":"据Cigarworld和Cigar''s Lover Magazine称，共有两个版本：Dominicano，墨西哥茄衣，2021年春季推出；Brasil，Mata Fina茄衣，2022年新增；据cigarslover.com称口感清淡。"},{"name":"Buena Vista","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"2013年推出；该品牌表示，调配采用多米尼加、巴西、秘鲁和尼加拉瓜烟叶，并加入按Perique法处理的稀有巴西Araperique烟叶。据Cigarworld.de目录，共有二十三款产品。"},{"name":"Beast","color":"#6B4226","force":null,"wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"庄主Axel-Georg André的个人项目，2016年推出；Sumatra茄套，巴西与尼加拉瓜茄芯，据Cigarworld.de称采用Fresh Pack包装。"},{"name":"Montosa","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"据经销商称，共有两个版本：Natural，采用较为温和的厄瓜多尔Connecticut Shade茄衣；Maduro，采用更具辛香气息的墨西哥San Andrés茄衣；2022年进入美国市场。"},{"name":"Carlos André","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade（厄瓜多尔）","vitolas":[],"story":"2009年推出，以庄主Axel-Georg André的幼子命名；据carlos-andre.com称，采用厄瓜多尔Connecticut Shade Desflorado茄衣。"}]',
        'شركة Arnold André شركة عائلية ألمانية أسّسها Johann Friedrich Christian André عام 1817 في مدينة Osnabrück لإنتاج تبغ التدخين؛ وانتقلت عائلة André إلى مدينة Bünde (شمال الراين-وستفاليا) عام 1851، حيث لا يزال مقر الشركة قائمًا هناك بعد سبعة أجيال. ومن أجل سيجارها الملفوف يدويًا، افتتحت الشركة عام 2011 مصنعًا خاصًا بها هو Arnold André Dominicana S.R.L.، في المنطقة الحرة الصناعية بمدينة Santiago de los Caballeros؛ واكتمل عام 2015 النقل الكامل لعملية لف السيجار طويل الحشوة إلى هذا المصنع. وفي Bünde، تنتج الشركة أيضًا سيجارًا وسيجاريللو بالآلة.

تضم التشكيلة الخاصة التي بُنيت في Santiago خمس علامات من السيجار طويل الحشوة. أُطلقت Carlos André عام 2009 تكريمًا للابن الأصغر لصاحب الشركة Axel-Georg André، وتُلف بغلاف Connecticut Shade Desflorado إكوادوري. وتجمع Buena Vista (2013)، بحسب الشركة، بين تبغ دومينيكاني وبرازيلي وبيروفي ونيكاراغوي، من بينه تبغ Araperique برازيلي نادر مُعالَج بطريقة Perique. أما Beast (2016)، وهو مشروع شخصي لـ Axel-Georg André، فيجمع بين غلاف San Andrés مكسيكي ورباط من Sumatra وحشوة برازيلية ونيكاراغوية. ووصلت Montosa إلى الولايات المتحدة عام 2022، وتُقدَّم بنسختين: Natural (بغلاف Connecticut Shade إكوادوري) وMaduro (بغلاف San Andrés مكسيكي). أما Parcero، فبدأت في ربيع 2021 بنسخة Dominicano بغلاف مكسيكي، وانضمت إليها عام 2022 نسخة Brasil بغلاف Mata Fina.',
        '[{"name":"Parcero","color":"#A0522D","force":"Mild","wrapper":"غير معلن","vitolas":[],"story":"نسختان بحسب Cigarworld وCigar''s Lover Magazine: Dominicano بغلاف مكسيكي، أُطلقت في ربيع 2021، وBrasil بغلاف Mata Fina، أُضيفت عام 2022؛ وهي خفيفة بحسب cigarslover.com."},{"name":"Buena Vista","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"أُطلقت عام 2013؛ ويجمع المزيج، بحسب الشركة، بين تبغ دومينيكاني وبرازيلي وبيروفي ونيكاراغوي، إضافة إلى تبغ Araperique برازيلي نادر مُعالَج بطريقة Perique. وتضم قائمة Cigarworld.de ثلاثة وعشرين صنفًا."},{"name":"Beast","color":"#6B4226","force":null,"wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"مشروع شخصي لصاحب الشركة Axel-Georg André، أُطلق عام 2016؛ برباط من Sumatra وحشوة برازيلية ونيكاراغوية، ويُعبَّأ بتنسيق Fresh Pack بحسب Cigarworld.de."},{"name":"Montosa","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"نسختان بحسب تجار التجزئة: Natural بغلاف Connecticut Shade إكوادوري أخف، وMaduro بغلاف San Andrés مكسيكي أشد توابلًا؛ ووصلت إلى الولايات المتحدة عام 2022."},{"name":"Carlos André","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade (الإكوادور)","vitolas":[],"story":"أُطلقت عام 2009 وسُمّيت باسم الابن الأصغر لصاحب الشركة Axel-Georg André؛ بغلاف Connecticut Shade Desflorado إكوادوري بحسب carlos-andre.com."}]')
