-- ── D'Crossier ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('D''Crossier',
        'dominican',
        '2006 — Isaias Santana Diaz, Miami',
        'Chez ABAM Cigars S.R.L. (Matías Maragoto), Villa Mella, Santo Domingo Norte (République dominicaine), depuis 2017 ; au Costa Rica jusqu''en 2016',
        'mikescigars.com « D''Crossier » et « Flor de D''Crossier » (pages de marque : Isaias Santana Diaz, Pure Aroma Cigars Inc. de Miami ; nom hérité du grand-père du président, en hommage à l''arrière-grand-père Francisco Crossier, selon la maison ; société fondée en 2006, ligne Golden Blend lancée en 2007 sous la Diplomacy Series, cape équatorienne, liant dominicain, tripe costaricienne et dominicaine ; production dominicaine chez ABAM Cigars S.R.L. depuis 2017) ; halfwheel.com « D''Crossier Golden Blend 10 Years Robusto », « D''Crossier Adding Golden Blend Reserva » et « D''Crossier Expands Golden Blend Series with Refinados » (actualités et revues : Golden Blend Reserva dédiée au père du président, Isaias Santana Crossier, 1945-2020 ; Refinados à cape habano colorado équatorienne triple fermentée) ; cigar-coop.com « Agile Cigar Review: D''Crossier L''Forte Robusto » (2016 : L''Forte lancée à l''IPCPR 2014, cape costaricienne, tripe dominicaine et nicaraguayenne, production de 2 000 boîtes par an) ; cigaraficionado.com « ABAM: A Dominican Factory Off the Beaten Path » (fabrique ABAM fondée en 1996 par José Matias Maragoto et son oncle Adalberto Ruizcalderon, zone franche au nord de Saint-Domingue) ; mikescigars.com « D''Crossier Pennsylvania Avenue », « D''Crossier Premium Blend » et « D''Crossier Imperium Class Vintage » (extension 2009 de la Presidential Collection roulée chez Pure Aroma Cigars S.A. au Costa Rica ; cape Connecticut fine pour Premium Blend ; cape Habano Criollo Especial costaricienne sun grown pour Imperium Class Vintage)',
        NULL,
        'D''Crossier est fondée en 2006 à Miami par Isaias Santana Diaz, qui dirige la société d''importation Pure Aroma Cigars Inc. ; le nom vient, dit la maison, du patronyme de son grand-père, en hommage à son arrière-grand-père Francisco Crossier, un Français venu à Cuba pour y développer des vignes avant de se tourner vers le tabac. La première ligne, Golden Blend, sort en 2007 sous la Diplomacy Series ; une extension ultérieure, Golden Blend Reserva, est dédiée au père du président, Isaias Santana Crossier (1945-2020).

Les premiers cigares D''Crossier sont roulés au Costa Rica, chez Pure Aroma Cigars S.A. ; c''est là qu''est faite, en 2009, Pennsylvania Avenue, extension de la Presidential Collection de la Diplomacy Series, affinée dix-neuf mois dans l''entrepôt de la maison à Hialeah Gardens (Floride) avant expédition. La production costaricienne se poursuit jusqu''en 2016 ; depuis 2017, D''Crossier roule en République dominicaine, chez ABAM Cigars S.R.L., à Villa Mella (Santo Domingo Norte) — une fabrique fondée en 1996 par José Matias Maragoto et son oncle Adalberto Ruizcalderon. Flor de D''Crossier, avec sa Selección 512 à cape Habano équatorienne, inaugure cette période dominicaine.

Le catalogue compte aussi Imperium Class Vintage (cape costaricienne Habano Criollo Especial), L''Forte (2014, cape costaricienne, tripe dominicaine et nicaraguayenne, corsée selon les détaillants) et Premium Blend, plus doux, sous cape Connecticut équatorienne fine et claire.',
        '[{"name":"Golden Blend","color":"#A0522D","force":null,"wrapper":"Équateur","vitolas":[],"story":"Première ligne de la maison, sous la Diplomacy Series en 2007 ; liant dominicain, tripe costaricienne et dominicaine ; force diversement décrite, douce selon un site, medium à corsée selon un autre suivant la vitola. Sa variante Reserva est dédiée au père du président, Isaias Santana Crossier (1945-2020)."},{"name":"Flor de D''Crossier","color":"#A0522D","force":"Medium","wrapper":"Habano (Équateur)","vitolas":[],"story":"Sa Selección 512 inaugure en 2017 le roulage chez ABAM, en République dominicaine ; un corps medium qui monte vers le corsé dans les grands formats, selon les revues spécialisées."},{"name":"Imperium Class Vintage","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Criollo Especial","vitolas":[],"story":"Cape costaricienne cultivée en plein soleil, tripe équatorienne, dominicaine et costaricienne ; sept formats selon les détaillants."},{"name":"Presidential Collection","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Ligne de la Diplomacy Series ; son extension Pennsylvania Avenue (2009), à cape costaricienne Habano Criollo Especial et tripe brésilienne et dominicaine, était roulée chez Pure Aroma Cigars S.A. au Costa Rica puis affinée dix-neuf mois dans l''entrepôt de la maison à Hialeah Gardens (Floride)."},{"name":"L''Forte","color":"#6B4226","force":"Full","wrapper":"Costa Rica","vitolas":[],"story":"Lancée à l''IPCPR 2014, tripe dominicaine et nicaraguayenne ; corsée selon les détaillants, produite à 2 000 boîtes par an selon Cigar Coop (2016)."},{"name":"Premium Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Équateur)","vitolas":[],"story":"Cape fine, claire et soyeuse, pour un profil plus doux que L''Forte selon les détaillants."}]',
        'D''Crossier was founded in 2006 in Miami by Isaias Santana Diaz, who runs the import company Pure Aroma Cigars Inc.; the name comes, the company says, from his grandfather''s surname, in tribute to his great-grandfather Francisco Crossier, a Frenchman who came to Cuba to grow vines before turning to tobacco. The first line, Golden Blend, came out in 2007 under the Diplomacy Series; a later extension, Golden Blend Reserva, is dedicated to the president''s father, Isaias Santana Crossier (1945-2020).

The first D''Crossier cigars were rolled in Costa Rica, at Pure Aroma Cigars S.A.; that is where Pennsylvania Avenue was made in 2009, an extension of the Presidential Collection within the Diplomacy Series, aged for nineteen months in the company''s warehouse in Hialeah Gardens (Florida) before shipping. Costa Rican production continued until 2016; since 2017, D''Crossier has rolled in the Dominican Republic, at ABAM Cigars S.R.L., in Villa Mella (Santo Domingo Norte) — a factory founded in 1996 by José Matias Maragoto and his uncle Adalberto Ruizcalderon. Flor de D''Crossier, with its Selección 512 in an Ecuadorian Habano wrapper, opened this Dominican period.

The range also includes Imperium Class Vintage (Costa Rican Habano Criollo Especial wrapper), L''Forte (2014, Costa Rican wrapper, Dominican and Nicaraguan filler, full-bodied according to retailers) and Premium Blend, milder, under a fine, light Ecuadorian Connecticut wrapper.',
        '[{"name":"Golden Blend","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"The company''s first line, under the Diplomacy Series in 2007; Dominican binder, Costa Rican and Dominican filler; its strength is described differently from source to source, mild according to one site, medium to full-bodied according to another depending on the vitola. Its Reserva variant is dedicated to the president''s father, Isaias Santana Crossier (1945-2020)."},{"name":"Flor de D''Crossier","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Its Selección 512 opened rolling at ABAM, in the Dominican Republic, in 2017; a medium body that rises towards full-bodied in the larger formats, according to the specialist press."},{"name":"Imperium Class Vintage","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Criollo Especial","vitolas":[],"story":"Costa Rican wrapper, sun-grown, Ecuadorian, Dominican and Costa Rican filler; seven formats according to retailers."},{"name":"Presidential Collection","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A line within the Diplomacy Series; its extension Pennsylvania Avenue (2009), with a Costa Rican Habano Criollo Especial wrapper and Brazilian and Dominican filler, was rolled at Pure Aroma Cigars S.A. in Costa Rica, then aged for nineteen months in the company''s warehouse in Hialeah Gardens (Florida)."},{"name":"L''Forte","color":"#6B4226","force":"Full","wrapper":"Costa Rica","vitolas":[],"story":"Launched at the IPCPR 2014, Dominican and Nicaraguan filler; full-bodied according to retailers, produced at 2,000 boxes a year according to Cigar Coop (2016)."},{"name":"Premium Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"A fine, light, silky wrapper, for a milder profile than L''Forte according to retailers."}]',
        'D''Crossier se funda en 2006 en Miami, de la mano de Isaias Santana Diaz, al frente de la importadora Pure Aroma Cigars Inc.; el nombre procede, según la casa, del apellido de su abuelo, en homenaje a su bisabuelo Francisco Crossier, un francés llegado a Cuba para cultivar viñas antes de dedicarse al tabaco. La primera línea, Golden Blend, sale en 2007 dentro de la Diplomacy Series; una extensión posterior, Golden Blend Reserva, está dedicada al padre del presidente, Isaias Santana Crossier (1945-2020).

Los primeros puros D''Crossier se elaboran en Costa Rica, en Pure Aroma Cigars S.A.; allí se hace, en 2009, Pennsylvania Avenue, extensión de la Presidential Collection dentro de la Diplomacy Series, añejada diecinueve meses en el almacén de la casa en Hialeah Gardens (Florida) antes de su envío. La producción costarricense continúa hasta 2016; desde 2017, D''Crossier elabora en República Dominicana, en ABAM Cigars S.R.L., en Villa Mella (Santo Domingo Norte) —una fábrica fundada en 1996 por José Matias Maragoto y su tío Adalberto Ruizcalderon. Flor de D''Crossier, con su Selección 512 de capa Habano ecuatoriana, inaugura esta etapa dominicana.

El catálogo incluye además Imperium Class Vintage (capa costarricense Habano Criollo Especial), L''Forte (2014, capa costarricense, tripa dominicana y nicaragüense, de cuerpo intenso según los detallistas) y Premium Blend, más suave, con capa Connecticut ecuatoriana fina y clara.',
        '[{"name":"Golden Blend","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Primera línea de la casa, dentro de la Diplomacy Series en 2007; capote dominicano, tripa costarricense y dominicana; su fuerza se describe de forma distinta según la fuente, suave para un sitio, de media a intensa para otro según la vitola. Su variante Reserva está dedicada al padre del presidente, Isaias Santana Crossier (1945-2020)."},{"name":"Flor de D''Crossier","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Su Selección 512 inaugura en 2017 el torcido en ABAM, en República Dominicana; un cuerpo medio que sube hacia lo intenso en los formatos grandes, según la prensa especializada."},{"name":"Imperium Class Vintage","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Criollo Especial","vitolas":[],"story":"Capa costarricense cultivada a pleno sol, tripa ecuatoriana, dominicana y costarricense; siete formatos según los detallistas."},{"name":"Presidential Collection","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Línea de la Diplomacy Series; su extensión Pennsylvania Avenue (2009), con capa costarricense Habano Criollo Especial y tripa brasileña y dominicana, se torcía en Pure Aroma Cigars S.A., en Costa Rica, y después se añejaba diecinueve meses en el almacén de la casa en Hialeah Gardens (Florida)."},{"name":"L''Forte","color":"#6B4226","force":"Full","wrapper":"Costa Rica","vitolas":[],"story":"Lanzada en el IPCPR 2014, tripa dominicana y nicaragüense; de cuerpo intenso según los detallistas, con una producción de dos mil cajas al año según Cigar Coop (2016)."},{"name":"Premium Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Capa fina, clara y sedosa, para un perfil más suave que L''Forte según los detallistas."}]',
        'D''Crossier wird 2006 in Miami von Isaias Santana Diaz gegründet, der die Importfirma Pure Aroma Cigars Inc. leitet; der Name stammt, so das Haus, vom Nachnamen seines Großvaters, zu Ehren seines Urgroßvaters Francisco Crossier, eines Franzosen, der nach Kuba kam, um dort Weinreben anzubauen, bevor er sich dem Tabak zuwandte. Die erste Linie, Golden Blend, erscheint 2007 unter der Diplomacy Series; eine spätere Erweiterung, Golden Blend Reserva, ist dem Vater des Präsidenten, Isaias Santana Crossier (1945-2020), gewidmet.

Die ersten D''Crossier-Zigarren werden in Costa Rica bei Pure Aroma Cigars S.A. gerollt; dort entsteht 2009 auch Pennsylvania Avenue, eine Erweiterung der Presidential Collection innerhalb der Diplomacy Series, die neunzehn Monate lang im Lager des Hauses in Hialeah Gardens (Florida) reift, bevor sie versandt wird. Die costa-ricanische Produktion läuft bis 2016 weiter; seit 2017 rollt D''Crossier in der Dominikanischen Republik, bei ABAM Cigars S.R.L. in Villa Mella (Santo Domingo Norte) — einer Fabrik, die 1996 von José Matias Maragoto und seinem Onkel Adalberto Ruizcalderon gegründet wurde. Flor de D''Crossier, mit ihrer Selección 512 unter ecuadorianischem Habano-Deckblatt, eröffnet diese dominikanische Ära.

Das Sortiment umfasst außerdem Imperium Class Vintage (costa-ricanisches Habano-Criollo-Especial-Deckblatt), L''Forte (2014, costa-ricanisches Deckblatt, dominikanische und nicaraguanische Einlage, laut Händlern kräftig) und Premium Blend, milder, unter feinem, hellem ecuadorianischem Connecticut-Deckblatt.',
        '[{"name":"Golden Blend","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Erste Linie des Hauses, 2007 unter der Diplomacy Series; dominikanisches Umblatt, costa-ricanische und dominikanische Einlage; die Stärke wird je nach Quelle unterschiedlich beschrieben, laut einer Website mild, laut einer anderen je nach Vitola mittel bis kräftig. Die Variante Reserva ist dem Vater des Präsidenten, Isaias Santana Crossier (1945-2020), gewidmet."},{"name":"Flor de D''Crossier","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Seine Selección 512 eröffnet 2017 das Rollen bei ABAM in der Dominikanischen Republik; ein mittlerer Körper, der sich bei den größeren Formaten in Richtung kräftig entwickelt, laut Fachpresse."},{"name":"Imperium Class Vintage","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Criollo Especial","vitolas":[],"story":"Costa-ricanisches Deckblatt, in voller Sonne angebaut, ecuadorianische, dominikanische und costa-ricanische Einlage; laut Händlern sieben Formate."},{"name":"Presidential Collection","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Linie der Diplomacy Series; ihre Erweiterung Pennsylvania Avenue (2009), mit costa-ricanischem Habano-Criollo-Especial-Deckblatt und brasilianischer und dominikanischer Einlage, wurde bei Pure Aroma Cigars S.A. in Costa Rica gerollt und anschließend neunzehn Monate im Lager des Hauses in Hialeah Gardens (Florida) gereift."},{"name":"L''Forte","color":"#6B4226","force":"Full","wrapper":"Costa Rica","vitolas":[],"story":"2014 auf der IPCPR lanciert, dominikanische und nicaraguanische Einlage; laut Händlern kräftig, mit einer Produktion von zweitausend Kisten pro Jahr laut Cigar Coop (2016)."},{"name":"Premium Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Feines, helles, seidiges Deckblatt für ein laut Händlern milderes Profil als L''Forte."}]',
        'D''Crossier由Isaias Santana Diaz于2006年在迈阿密创立，他执掌进口公司Pure Aroma Cigars Inc.；据该品牌称，品牌名取自其祖父的姓氏，以此纪念他的曾祖父Francisco Crossier——一位曾赴古巴种植葡萄、后来转向烟草业的法国人。首个系列Golden Blend于2007年在Diplomacy Series旗下推出；后来推出的扩展系列Golden Blend Reserva，则献给该品牌总裁之父Isaias Santana Crossier（1945-2020）。

D''Crossier最初的雪茄在哥斯达黎加的Pure Aroma Cigars S.A.卷制；2009年，Diplomacy Series旗下Presidential Collection的扩展系列Pennsylvania Avenue正是在那里制成，先在公司位于Hialeah Gardens（佛罗里达州）的仓库中陈化十九个月，而后再发运。哥斯达黎加的生产一直延续到2016年；自2017年起，D''Crossier转在多米尼加共和国卷制，地点是位于Villa Mella（Santo Domingo Norte）的ABAM Cigars S.R.L.——该厂由José Matias Maragoto及其叔叔Adalberto Ruizcalderon于1996年创立。Flor de D''Crossier及其厄瓜多尔Habano茄衣的Selección 512系列，开启了这一多米尼加时期。

产品目录中还包括Imperium Class Vintage（哥斯达黎加Habano Criollo Especial茄衣）、L''Forte（2014年推出，哥斯达黎加茄衣，多米尼加与尼加拉瓜茄芯，据经销商称口感浓郁）以及口感更为温和的Premium Blend，采用细腻浅色的厄瓜多尔Connecticut茄衣。',
        '[{"name":"Golden Blend","color":"#A0522D","force":null,"wrapper":"厄瓜多尔","vitolas":[],"story":"品牌首个系列，2007年于Diplomacy Series旗下推出；多米尼加茄套，哥斯达黎加与多米尼加茄芯；各方对其浓度描述不一，一家网站称其柔和，另一家则称视雪茄规格而定，浓度从中等到浓郁不等。其Reserva版本献给该品牌总裁之父Isaias Santana Crossier（1945-2020）。"},{"name":"Flor de D''Crossier","color":"#A0522D","force":"Medium","wrapper":"Habano（厄瓜多尔）","vitolas":[],"story":"其Selección 512系列于2017年开启了在多米尼加共和国ABAM厂的卷制；据专业媒体称，其浓度为中等，在较大规格中趋向浓郁。"},{"name":"Imperium Class Vintage","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Criollo Especial","vitolas":[],"story":"哥斯达黎加茄衣，阳光种植；茄芯为厄瓜多尔、多米尼加与哥斯达黎加烟叶混合；据经销商称共有七种规格。"},{"name":"Presidential Collection","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"Diplomacy Series旗下系列；其扩展系列Pennsylvania Avenue（2009年）采用哥斯达黎加Habano Criollo Especial茄衣及巴西与多米尼加茄芯，曾在哥斯达黎加的Pure Aroma Cigars S.A.卷制，随后在公司位于Hialeah Gardens（佛罗里达州）的仓库中陈化十九个月。"},{"name":"L''Forte","color":"#6B4226","force":"Full","wrapper":"哥斯达黎加","vitolas":[],"story":"于2014年IPCPR展会推出，多米尼加与尼加拉瓜茄芯；据经销商称口感浓郁，据Cigar Coop（2016年）称年产量为两千箱。"},{"name":"Premium Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut（厄瓜多尔）","vitolas":[],"story":"茄衣细腻、色浅且丝滑，据经销商称其口感比L''Forte更为温和。"}]',
        'تأسست D''Crossier عام 2006 في Miami على يد Isaias Santana Diaz، الذي يدير شركة الاستيراد Pure Aroma Cigars Inc.؛ ويأتي الاسم، بحسب الشركة، من لقب جده، تكريمًا لجده الأكبر Francisco Crossier، وهو فرنسي قدِم إلى Cuba لزراعة الكروم قبل أن يتجه إلى التبغ. وصدرت السلسلة الأولى، Golden Blend، عام 2007 ضمن Diplomacy Series؛ وخُصصت سلسلة لاحقة، Golden Blend Reserva، لوالد رئيس الشركة، Isaias Santana Crossier (1945-2020).

لُفت أولى سيجارات D''Crossier في Costa Rica، لدى Pure Aroma Cigars S.A.؛ وهناك صُنعت عام 2009 سلسلة Pennsylvania Avenue، وهي امتداد لـ Presidential Collection ضمن Diplomacy Series، وعُتِّقت تسعة عشر شهرًا في مستودع الشركة بـ Hialeah Gardens (فلوريدا) قبل شحنها. واستمر الإنتاج في Costa Rica حتى عام 2016؛ ومنذ عام 2017، تلفّ D''Crossier سيجارها في جمهورية الدومينيكان، لدى ABAM Cigars S.R.L. في Villa Mella (Santo Domingo Norte) — وهو مصنع أسّسه عام 1996 José Matias Maragoto وعمّه Adalberto Ruizcalderon. وافتتحت Flor de D''Crossier، بسلسلتها Selección 512 ذات الغلاف الإكوادوري من نوع Habano، هذه المرحلة الدومينيكانية.

وتضم التشكيلة أيضًا Imperium Class Vintage (بغلاف Habano Criollo Especial من Costa Rica)، وL''Forte (أُطلقت عام 2014، بغلاف من Costa Rica وحشوة دومينيكانية ونيكاراغوية، وهي قوية بحسب تجار التجزئة)، وPremium Blend الأخف، بغلاف Connecticut إكوادوري رقيق وفاتح اللون.',
        '[{"name":"Golden Blend","color":"#A0522D","force":null,"wrapper":"الإكوادور","vitolas":[],"story":"أولى سلاسل الشركة، ضمن Diplomacy Series عام 2007؛ برباط دومينيكاني وحشوة من Costa Rica وجمهورية الدومينيكان؛ وتختلف الأوصاف الخاصة بقوتها من مصدر لآخر، فهي خفيفة بحسب موقع، ومتوسطة إلى قوية بحسب موقع آخر تبعًا لمقاس السيجار. وخُصصت نسختها Reserva لوالد رئيس الشركة، Isaias Santana Crossier (1945-2020)."},{"name":"Flor de D''Crossier","color":"#A0522D","force":"Medium","wrapper":"Habano (الإكوادور)","vitolas":[],"story":"افتتحت سلسلتها Selección 512 عام 2017 عملية اللف لدى ABAM في جمهورية الدومينيكان؛ وقوتها متوسطة تميل إلى القوة في المقاسات الكبيرة، بحسب الصحافة المتخصصة."},{"name":"Imperium Class Vintage","color":"#6B4226","force":"Medium-Full","wrapper":"Habano Criollo Especial","vitolas":[],"story":"غلاف من Costa Rica مزروع تحت الشمس الكاملة، وحشوة إكوادورية ودومينيكانية وكوستاريكية؛ سبعة مقاسات بحسب تجار التجزئة."},{"name":"Presidential Collection","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"سلسلة ضمن Diplomacy Series؛ وامتدادها Pennsylvania Avenue (2009)، بغلاف Habano Criollo Especial من Costa Rica وحشوة برازيلية ودومينيكانية، كان يُلف لدى Pure Aroma Cigars S.A. في Costa Rica ثم يُعتَّق تسعة عشر شهرًا في مستودع الشركة بـ Hialeah Gardens (فلوريدا)."},{"name":"L''Forte","color":"#6B4226","force":"Full","wrapper":"كوستاريكا","vitolas":[],"story":"أُطلقت في معرض IPCPR عام 2014، بحشوة دومينيكانية ونيكاراغوية؛ وهي قوية بحسب تجار التجزئة، ويبلغ إنتاجها ألفي صندوق سنويًا بحسب Cigar Coop (2016)."},{"name":"Premium Blend","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (الإكوادور)","vitolas":[],"story":"غلاف رقيق وفاتح اللون وحريري الملمس، لملمح أخف من L''Forte بحسب تجار التجزئة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Bugatti ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Bugatti',
        'dominican',
        '2015 — Bugatti Group (Yigal Harel)',
        'Chez PDR Cigars (Ambassador, Signature), la Kelner Boutique Factory (BOSS, Monte Carlo) et Tabacalera Victor Sinclair, en République dominicaine',
        'halfwheel.com « Bugatti Group Launching at IPCPR 2015 » (2015 : Ambassador et Signature roulées par Tabacalera PDR Cigars d''Abe Flores, après une Perdomo Bugatti faite avec Perdomo ; BOSS Classic à la Kelner Boutique Factory ; capes et tripes) ; halfwheel.com « Bugatti Group Adds Monte Carlo Gold and Platinum » (2019 : deux mélanges roulés par la Kelner Boutique Factory, présentés à l''IPCPR 2019) ; cigarworld.de « Bugatti » (page de marque, consultée en septembre 2026 : trois fabriques — PDR Cigars d''Abe Flores, Kelner Boutique Factory, Tabacalera Victor Sinclair de José Dominguez ; Yigal Harel venu des accessoires ; Quattro Claro et Maduro sous cape mexicaine San Andrés) ; cigarinspector.com « Bugatti Ambassador Robusto » (cape habano équatorienne, force medium) ; cigarmonthclub.com « Bugatti Quattro Maduro Robusto » (cape San Andrés Maduro, sous-cape dominicaine Olor, tripe dominicaine et nicaraguayenne) ; justsmokecigars.com « Victor Sinclair Cigars: Dominican craftsmanship since 1995 » (Tabacalera Victor Sinclair, fondée en 1995 par José Dominguez)',
        NULL,
        'Bugatti est une licence de la marque automobile éponyme, portée par Integral Logistics, la société de Yigal Harel, venu des briquets et accessoires pour fumeurs (Cigarworld.de). Integral s''associe d''abord à Perdomo pour une Perdomo Bugatti ; en 2015, son Bugatti Group présente à l''IPCPR ses propres lignes (halfwheel). La marque n''a pas de fabrique unique : Cigarworld.de en nomme trois, toutes en République dominicaine.

Ambassador et Signature sont roulées chez PDR Cigars, la fabrique d''Abe Flores : l''Ambassador sous cape équatorienne, sur une tripe du Brésil, de République dominicaine, du Nicaragua et de Pennsylvanie ; la Signature sous cape équatorienne, avec du piloto cubano dominicain âgé de dix ans dans la tripe (halfwheel). Le BOSS Classic, à cape brésilienne, et les Monte Carlo Gold et Platinum, présentées à l''IPCPR 2019, sortent de la Kelner Boutique Factory d''Hendrik Kelner Jr. La troisième fabrique, la Tabacalera Victor Sinclair de José Dominguez, date de 1995 ; aucune source consultée ne dit quelles lignes elle roule. Le catalogue compte aussi Quattro, en Claro et en Maduro, toutes deux sous cape mexicaine San Andrés, et Cigarworld.de tient toujours la marque en 2026.',
        '[{"name":"Ambassador","color":"#A0522D","force":"Medium","wrapper":"Habano (Équateur)","vitolas":[],"story":"Ligne de 2015, roulée chez PDR Cigars : cape équatorienne sur tripe du Brésil, de République dominicaine, du Nicaragua et de Pennsylvanie (halfwheel) ; habano et medium selon Cigar Inspector."},{"name":"Signature","color":"#A0522D","force":null,"wrapper":"Équateur","vitolas":[],"story":"Ligne de 2015, roulée chez PDR Cigars : cape équatorienne, piloto cubano dominicain de dix ans dans la tripe (halfwheel)."},{"name":"BOSS","color":"#6B4226","force":null,"wrapper":"Brésil","vitolas":[],"story":"Version Classic à tripe dominicaine, nicaraguayenne et péruvienne, roulée à la Kelner Boutique Factory d''Hendrik Kelner Jr. (halfwheel)."},{"name":"Monte Carlo","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Deux mélanges présentés à l''IPCPR 2019 et roulés à la Kelner Boutique Factory (halfwheel) : Gold, cape brésilienne cubra sur sous-cape dominicaine criollo 98 de Cotuí ; Platinum, cape dominicaine sur sous-cape nicaraguayenne de Jalapa."},{"name":"Quattro","color":"#6B4226","force":null,"wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Deux versions sous cape mexicaine San Andrés (Cigarworld.de) : Claro, et Maduro, corsée, sur sous-cape dominicaine Olor et tripe dominicaine et nicaraguayenne ; la fabrique qui la roule n''est pas dite."}]',
        'Bugatti is a licensed use of the eponymous car brand, run by Integral Logistics, the company of Yigal Harel, who came from lighters and smokers'' accessories (Cigarworld.de). Integral first partnered with Perdomo for a Perdomo Bugatti; in 2015, its Bugatti Group presented its own lines at the IPCPR (halfwheel). The brand has no single factory: Cigarworld.de names three, all in the Dominican Republic.

Ambassador and Signature are rolled at PDR Cigars, Abe Flores''s factory: the Ambassador under an Ecuadorian wrapper, on a filler of Brazil, the Dominican Republic, Nicaragua and Pennsylvania; the Signature under an Ecuadorian wrapper, with ten-year-old Dominican piloto cubano in the filler (halfwheel). The BOSS Classic, with a Brazilian wrapper, and the Monte Carlo Gold and Platinum, presented at the IPCPR 2019, come from Hendrik Kelner Jr.''s Kelner Boutique Factory. The third factory, José Dominguez''s Tabacalera Victor Sinclair, dates from 1995; no source consulted says which lines it rolls. The range also includes Quattro, in Claro and Maduro, both under a Mexican San Andrés wrapper, and Cigarworld.de still carries the brand in 2026.',
        '[{"name":"Ambassador","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"A 2015 line, rolled at PDR Cigars: Ecuadorian wrapper over a filler of Brazil, the Dominican Republic, Nicaragua and Pennsylvania (halfwheel); a habano wrapper and medium body, according to Cigar Inspector."},{"name":"Signature","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"A 2015 line, rolled at PDR Cigars: Ecuadorian wrapper, ten-year-old Dominican piloto cubano in the filler (halfwheel)."},{"name":"BOSS","color":"#6B4226","force":null,"wrapper":"Brazil","vitolas":[],"story":"The Classic version, with Dominican, Nicaraguan and Peruvian filler, rolled at Hendrik Kelner Jr.''s Kelner Boutique Factory (halfwheel)."},{"name":"Monte Carlo","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Two blends presented at the IPCPR 2019 and rolled at the Kelner Boutique Factory (halfwheel): Gold, with a Brazilian Cubra wrapper over a Dominican criollo 98 binder from Cotuí; Platinum, with a Dominican wrapper over a Nicaraguan binder from Jalapa."},{"name":"Quattro","color":"#6B4226","force":null,"wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Two versions under a Mexican San Andrés wrapper (Cigarworld.de): Claro, and Maduro, full-bodied, over a Dominican Olor binder and Dominican and Nicaraguan filler; the factory that rolls it is not stated."}]',
        'Bugatti es una licencia de la marca automovilística homónima, gestionada por Integral Logistics, la empresa de Yigal Harel, procedente del sector de los encendedores y los accesorios para fumadores (Cigarworld.de). Integral se asocia primero con Perdomo para un Perdomo Bugatti; en 2015, su Bugatti Group presenta sus propias líneas en el IPCPR (halfwheel). La marca no tiene una única fábrica: Cigarworld.de cita tres, todas en República Dominicana.

Ambassador y Signature se elaboran en PDR Cigars, la fábrica de Abe Flores: el Ambassador con capa ecuatoriana, sobre una tripa de Brasil, República Dominicana, Nicaragua y Pensilvania; el Signature con capa ecuatoriana, con piloto cubano dominicano de diez años en la tripa (halfwheel). El BOSS Classic, de capa brasileña, y los Monte Carlo Gold y Platinum, presentados en el IPCPR 2019, salen de la Kelner Boutique Factory de Hendrik Kelner Jr. La tercera fábrica, la Tabacalera Victor Sinclair de José Dominguez, data de 1995; ninguna fuente consultada indica qué líneas elabora. El catálogo incluye también Quattro, en Claro y en Maduro, ambas con capa mexicana San Andrés, y Cigarworld.de sigue teniendo la marca en su catálogo en 2026.',
        '[{"name":"Ambassador","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Línea de 2015, elaborada en PDR Cigars: capa ecuatoriana sobre tripa de Brasil, República Dominicana, Nicaragua y Pensilvania (halfwheel); capa habano y cuerpo medio, según Cigar Inspector."},{"name":"Signature","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Línea de 2015, elaborada en PDR Cigars: capa ecuatoriana, piloto cubano dominicano de diez años en la tripa (halfwheel)."},{"name":"BOSS","color":"#6B4226","force":null,"wrapper":"Brasil","vitolas":[],"story":"Versión Classic, con tripa dominicana, nicaragüense y peruana, elaborada en la Kelner Boutique Factory de Hendrik Kelner Jr. (halfwheel)."},{"name":"Monte Carlo","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Dos mezclas presentadas en el IPCPR 2019 y elaboradas en la Kelner Boutique Factory (halfwheel): Gold, con capa brasileña Cubra sobre capote dominicano criollo 98 de Cotuí; Platinum, con capa dominicana sobre capote nicaragüense de Jalapa."},{"name":"Quattro","color":"#6B4226","force":null,"wrapper":"San Andrés (México)","vitolas":[],"story":"Dos versiones con capa mexicana San Andrés (Cigarworld.de): Claro, y Maduro, de cuerpo intenso, sobre capote dominicano Olor y tripa dominicana y nicaragüense; no se indica la fábrica que la elabora."}]',
        'Bugatti ist eine lizenzierte Nutzung der gleichnamigen Automarke, geführt von Integral Logistics, dem Unternehmen von Yigal Harel, der aus dem Bereich Feuerzeuge und Raucherzubehör kommt (Cigarworld.de). Integral arbeitet zunächst mit Perdomo für eine Perdomo Bugatti zusammen; 2015 stellt die Bugatti Group ihre eigenen Linien auf der IPCPR vor (halfwheel). Die Marke hat keine einzige Fabrik: Cigarworld.de nennt drei, alle in der Dominikanischen Republik.

Ambassador und Signature werden bei PDR Cigars, der Fabrik von Abe Flores, gerollt: der Ambassador unter ecuadorianischem Deckblatt, auf einer Einlage aus Brasilien, der Dominikanischen Republik, Nicaragua und Pennsylvania; die Signature unter ecuadorianischem Deckblatt, mit zehn Jahre altem dominikanischem Piloto Cubano in der Einlage (halfwheel). Der BOSS Classic, mit brasilianischem Deckblatt, sowie die Monte Carlo Gold und Platinum, die auf der IPCPR 2019 vorgestellt wurden, stammen aus der Kelner Boutique Factory von Hendrik Kelner Jr. Die dritte Fabrik, die Tabacalera Victor Sinclair von José Dominguez, besteht seit 1995; keine der konsultierten Quellen nennt, welche Linien dort gerollt werden. Das Sortiment umfasst außerdem Quattro, in Claro und Maduro, beide unter mexikanischem San-Andrés-Deckblatt, und Cigarworld.de führt die Marke auch 2026 noch.',
        '[{"name":"Ambassador","color":"#A0522D","force":"Medium","wrapper":"Habano (Ecuador)","vitolas":[],"story":"Linie aus dem Jahr 2015, gerollt bei PDR Cigars: ecuadorianisches Deckblatt über einer Einlage aus Brasilien, der Dominikanischen Republik, Nicaragua und Pennsylvania (halfwheel); laut Cigar Inspector Deckblatt Habano und mittlere Stärke."},{"name":"Signature","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Linie aus dem Jahr 2015, gerollt bei PDR Cigars: ecuadorianisches Deckblatt, zehn Jahre alter dominikanischer Piloto Cubano in der Einlage (halfwheel)."},{"name":"BOSS","color":"#6B4226","force":null,"wrapper":"Brasilien","vitolas":[],"story":"Version Classic mit dominikanischer, nicaraguanischer und peruanischer Einlage, gerollt in der Kelner Boutique Factory von Hendrik Kelner Jr. (halfwheel)."},{"name":"Monte Carlo","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Zwei Mischungen, die 2019 auf der IPCPR vorgestellt und in der Kelner Boutique Factory gerollt wurden (halfwheel): Gold, mit brasilianischem Cubra-Deckblatt über dominikanischem Criollo-98-Umblatt aus Cotuí; Platinum, mit dominikanischem Deckblatt über nicaraguanischem Umblatt aus Jalapa."},{"name":"Quattro","color":"#6B4226","force":null,"wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Zwei Versionen unter mexikanischem San-Andrés-Deckblatt (Cigarworld.de): Claro, und Maduro, kräftig, über dominikanischem Olor-Umblatt und dominikanischer und nicaraguanischer Einlage; die Fabrik, die sie rollt, wird nicht genannt."}]',
        'Bugatti是同名汽车品牌的授权使用，由Integral Logistics运营，该公司属于Yigal Harel，他出身于打火机及吸烟配件行业（据Cigarworld.de）。Integral最初与Perdomo合作推出Perdomo Bugatti；2015年，其Bugatti Group在IPCPR展会上推出了自有系列（据halfwheel）。该品牌并无单一工厂：据Cigarworld.de称，共有三家工厂，均位于多米尼加共和国。

Ambassador与Signature在Abe Flores的工厂PDR Cigars卷制：Ambassador采用厄瓜多尔茄衣，茄芯混合了巴西、多米尼加共和国、尼加拉瓜与宾夕法尼亚烟叶；Signature同样采用厄瓜多尔茄衣，茄芯中加入了陈化十年的多米尼加piloto cubano烟叶（据halfwheel）。采用巴西茄衣的BOSS Classic，以及于2019年IPCPR展会推出的Monte Carlo Gold和Platinum，均产自Hendrik Kelner Jr.的Kelner Boutique Factory。第三家工厂，José Dominguez的Tabacalera Victor Sinclair，创立于1995年；所查阅的资料均未说明该厂卷制哪些系列。产品目录中还包括Quattro，分Claro和Maduro两款，均采用墨西哥San Andrés茄衣，截至2026年，该品牌仍在Cigarworld.de的目录中。',
        '[{"name":"Ambassador","color":"#A0522D","force":"Medium","wrapper":"Habano（厄瓜多尔）","vitolas":[],"story":"2015年推出的系列，产自PDR Cigars：厄瓜多尔茄衣，茄芯混合巴西、多米尼加共和国、尼加拉瓜与宾夕法尼亚烟叶（据halfwheel）；据Cigar Inspector称，茄衣类型为habano，浓度中等。"},{"name":"Signature","color":"#A0522D","force":null,"wrapper":"厄瓜多尔","vitolas":[],"story":"2015年推出的系列，产自PDR Cigars：厄瓜多尔茄衣，茄芯中含有陈化十年的多米尼加piloto cubano烟叶（据halfwheel）。"},{"name":"BOSS","color":"#6B4226","force":null,"wrapper":"巴西","vitolas":[],"story":"Classic版本，茄芯混合多米尼加、尼加拉瓜与秘鲁烟叶，产自Hendrik Kelner Jr.的Kelner Boutique Factory（据halfwheel）。"},{"name":"Monte Carlo","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"两款调配于2019年IPCPR展会推出，产自Kelner Boutique Factory（据halfwheel）：Gold采用巴西Cubra茄衣，搭配产自Cotuí的多米尼加criollo 98茄套；Platinum采用多米尼加茄衣，搭配产自Jalapa的尼加拉瓜茄套。"},{"name":"Quattro","color":"#6B4226","force":null,"wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"两个版本均采用墨西哥San Andrés茄衣（据Cigarworld.de）：Claro，以及口感浓郁的Maduro，搭配多米尼加Olor茄套及多米尼加与尼加拉瓜茄芯；卷制工厂未有说明。"}]',
        'Bugatti هو استخدام مرخَّص لعلامة السيارات التي تحمل الاسم نفسه، تديره Integral Logistics، شركة Yigal Harel القادم من قطاع الولاعات ومستلزمات التدخين (بحسب Cigarworld.de). وتشاركت Integral أولًا مع Perdomo لإنتاج Perdomo Bugatti؛ وفي عام 2015، قدّمت مجموعتها Bugatti Group سلاسلها الخاصة في معرض IPCPR (بحسب halfwheel). وليس للعلامة مصنع واحد: إذ تذكر Cigarworld.de ثلاثة مصانع، جميعها في جمهورية الدومينيكان.

تُلف Ambassador وSignature لدى PDR Cigars، مصنع Abe Flores: فسيجار Ambassador بغلاف إكوادوري وحشوة من البرازيل وجمهورية الدومينيكان ونيكاراغوا وبنسلفانيا؛ وسيجار Signature بغلاف إكوادوري أيضًا، مع تبغ piloto cubano دومينيكاني عمره عشر سنوات ضمن الحشوة (بحسب halfwheel). أما BOSS Classic، بغلافه البرازيلي، وMonte Carlo Gold وPlatinum اللذان قُدِّما في معرض IPCPR عام 2019، فتُصنع في Kelner Boutique Factory التابعة لـ Hendrik Kelner Jr. والمصنع الثالث، Tabacalera Victor Sinclair العائد لـ José Dominguez، يعود تاريخه إلى عام 1995؛ ولم تذكر أي من المصادر المُطالَعة السلاسل التي يلفّها. وتضم التشكيلة أيضًا Quattro، بنسختي Claro وMaduro، وكلتاهما بغلاف San Andrés مكسيكي، ولا تزال Cigarworld.de تدرج العلامة في قائمتها حتى عام 2026.',
        '[{"name":"Ambassador","color":"#A0522D","force":"Medium","wrapper":"Habano (الإكوادور)","vitolas":[],"story":"سلسلة من عام 2015، تُلف لدى PDR Cigars: بغلاف إكوادوري فوق حشوة من البرازيل وجمهورية الدومينيكان ونيكاراغوا وبنسلفانيا (بحسب halfwheel)؛ وهي بغلاف هابانو (Habano) وقوة متوسطة بحسب Cigar Inspector."},{"name":"Signature","color":"#A0522D","force":null,"wrapper":"الإكوادور","vitolas":[],"story":"سلسلة من عام 2015، تُلف لدى PDR Cigars: بغلاف إكوادوري، وتبغ piloto cubano دومينيكاني عمره عشر سنوات ضمن الحشوة (بحسب halfwheel)."},{"name":"BOSS","color":"#6B4226","force":null,"wrapper":"البرازيل","vitolas":[],"story":"نسخة Classic بحشوة دومينيكانية ونيكاراغوية وبيروفية، تُلف في Kelner Boutique Factory التابعة لـ Hendrik Kelner Jr. (بحسب halfwheel)."},{"name":"Monte Carlo","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"مزيجان قُدِّما في معرض IPCPR عام 2019 ويُلفّان في Kelner Boutique Factory (بحسب halfwheel): Gold بغلاف برازيلي من نوع Cubra فوق رباط دومينيكاني من نوع criollo 98 من Cotuí؛ وPlatinum بغلاف دومينيكاني فوق رباط نيكاراغوي من Jalapa."},{"name":"Quattro","color":"#6B4226","force":null,"wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"نسختان بغلاف San Andrés مكسيكي (بحسب Cigarworld.de): Claro، وMaduro القوية، فوق رباط دومينيكاني من نوع Olor وحشوة دومينيكانية ونيكاراغوية؛ ولم يُذكر المصنع الذي يلفّها."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Caoba ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Caoba',
        'dominican',
        '1992 — Don Julio Pérez González, Saint-Domingue',
        'Usine propre — Tabacalera Caoba, zone coloniale de Saint-Domingue (installée d''abord à Villa Faro en 1992)',
        'halfwheel.com « IPCPR 2019: Caoba » (2019 : marque dominicaine établie depuis 1992, présentée à l''IPCPR) ; humoytabaco.com « Caoba » (2024-11-14, en espagnol : fondée en 1992 à Saint-Domingue par Don Julio Pérez González, Espagnol marié à une Dominicaine et ancien sculpteur sur acajou — d''où le nom —, manufacture d''origine à Villa Faro déplacée depuis à Ciudad Colonial, une dizaine de lignes au catalogue) ; stogiepress.com « Cigar Review: Caoba Cigars Diamante Torpedo » (revue : cape San Andrés mexicaine sur liant et tripe entièrement dominicains, fabrique intégrée verticalement, champs à Tamboril) ; leafenthusiast.com « Cigar Review: Caoba Oro » (revue : cape Connecticut Shade équatorienne, liant et tripe dominicains, profil doux)',
        NULL,
        'Caoba naît en 1992 à Saint-Domingue, fondée par Don Julio Pérez González, un Espagnol marié à une Dominicaine qui tenait jusque-là un atelier de sculpture sur acajou — caoba en espagnol, et arbre national du pays : la maison dit y avoir puisé son nom. La manufacture d''origine s''installe à Villa Faro, dans l''est de la capitale ; la génération suivante la déplace depuis vers la zone coloniale de Saint-Domingue (Ciudad Colonial), où elle se trouve aujourd''hui (humoytabaco.com, en espagnol). Stogiepress décrit une fabrique intégrée verticalement, avec des champs propres à Tamboril, dans la vallée du Cibao.

Le catalogue compte une dizaine de lignes selon Humo y Tabaco ; deux sont décrites par la presse spécialisée. Diamante, corsée selon Stogiepress, associe une cape mexicaine San Andrés à un liant et une tripe entièrement dominicains. Oro, à l''inverse, porte une cape Connecticut Shade équatorienne sur liant et tripe dominicains, pour un profil plus doux (Leaf Enthusiast). La marque a été présentée à l''IPCPR 2019 (halfwheel) et reste en vente courante.',
        '[{"name":"Diamante","color":"#6B4226","force":"Full","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Cape mexicaine sur liant et tripe entièrement dominicains ; corsée selon Stogiepress."},{"name":"Oro","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Équateur)","vitolas":[],"story":"Cape équatorienne sur liant et tripe dominicains ; profil doux selon Leaf Enthusiast."}]',
        'Caoba was born in 1992 in Santo Domingo, founded by Don Julio Pérez González, a Spaniard married to a Dominican woman who had until then run a mahogany-carving workshop — caoba in Spanish, and the country''s national tree: the company says that is where it drew its name. The original factory was set up in Villa Faro, in the east of the capital; the following generation has since moved it to the colonial quarter of Santo Domingo (Ciudad Colonial), where it stands today (humoytabaco.com, in Spanish). Stogiepress describes a vertically integrated factory, with its own fields in Tamboril, in the Cibao valley.

The range comprises around ten lines according to Humo y Tabaco; two are described by the specialist press. Diamante, full-bodied according to Stogiepress, combines a Mexican San Andrés wrapper with an entirely Dominican binder and filler. Oro, conversely, carries an Ecuadorian Connecticut Shade wrapper over Dominican binder and filler, for a milder profile (Leaf Enthusiast). The brand was presented at the IPCPR 2019 (halfwheel) and remains on general sale.',
        '[{"name":"Diamante","color":"#6B4226","force":"Full","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Mexican wrapper over an entirely Dominican binder and filler; full-bodied according to Stogiepress."},{"name":"Oro","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Ecuadorian wrapper over Dominican binder and filler; mild profile according to Leaf Enthusiast."}]',
        'Caoba nace en 1992 en Santo Domingo, fundada por Don Julio Pérez González, un español casado con una dominicana que hasta entonces había llevado un taller de talla en madera de caoba, el árbol nacional del país: de ahí, dice la casa, tomó su nombre. La manufactura original se instala en Villa Faro, en el este de la capital; la generación siguiente la traslada desde entonces a la zona colonial de Santo Domingo (Ciudad Colonial), donde se encuentra hoy (humoytabaco.com). Stogiepress describe una fábrica integrada verticalmente, con campos propios en Tamboril, en el valle del Cibao.

El catálogo cuenta con una decena de líneas según Humo y Tabaco; dos de ellas descritas por la prensa especializada. Diamante, de cuerpo intenso según Stogiepress, combina una capa mexicana San Andrés con capote y tripa enteramente dominicanos. Oro, en cambio, lleva capa Connecticut Shade ecuatoriana sobre capote y tripa dominicanos, para un perfil más suave (Leaf Enthusiast). La marca se presentó en el IPCPR 2019 (halfwheel) y sigue a la venta.',
        '[{"name":"Diamante","color":"#6B4226","force":"Full","wrapper":"San Andrés (México)","vitolas":[],"story":"Capa mexicana sobre capote y tripa enteramente dominicanos; de cuerpo intenso según Stogiepress."},{"name":"Oro","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Capa ecuatoriana sobre capote y tripa dominicanos; perfil suave según Leaf Enthusiast."}]',
        'Caoba entsteht 1992 in Santo Domingo, gegründet von Don Julio Pérez González, einem Spanier, der mit einer Dominikanerin verheiratet war und bis dahin eine Werkstatt für Mahagoni-Schnitzerei geführt hatte — caoba auf Spanisch, zugleich der Nationalbaum des Landes: von dort, so das Haus, stamme der Name. Die ursprüngliche Fabrik entsteht in Villa Faro, im Osten der Hauptstadt; die nachfolgende Generation verlegt sie seither in die Kolonialzone von Santo Domingo (Ciudad Colonial), wo sie sich heute befindet (humoytabaco.com, auf Spanisch). Stogiepress beschreibt eine vertikal integrierte Fabrik mit eigenen Feldern in Tamboril, im Cibao-Tal.

Das Sortiment umfasst laut Humo y Tabaco rund zehn Linien; zwei davon werden von der Fachpresse beschrieben. Diamante, laut Stogiepress kräftig, verbindet ein mexikanisches San-Andrés-Deckblatt mit vollständig dominikanischem Umblatt und dominikanischer Einlage. Oro trägt dagegen ein ecuadorianisches Connecticut-Shade-Deckblatt über dominikanischem Umblatt und dominikanischer Einlage, für ein milderes Profil (Leaf Enthusiast). Die Marke wurde 2019 auf der IPCPR vorgestellt (halfwheel) und ist weiterhin im regulären Verkauf.',
        '[{"name":"Diamante","color":"#6B4226","force":"Full","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Mexikanisches Deckblatt über vollständig dominikanischem Umblatt und dominikanischer Einlage; laut Stogiepress kräftig."},{"name":"Oro","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Ecuadorianisches Deckblatt über dominikanischem Umblatt und dominikanischer Einlage; laut Leaf Enthusiast mildes Profil."}]',
        'Caoba于1992年诞生于Santo Domingo，由Don Julio Pérez González创立，他是一名西班牙人，娶了一位多米尼加女子，此前经营一间桃花心木雕刻工坊——caoba在西班牙语中意为桃花心木，也是该国的国树：据该品牌称，品牌名即由此而来。最初的工厂设于首都东部的Villa Faro；下一代经营者其后将其迁至Santo Domingo的殖民区（Ciudad Colonial），即如今所在地（据humoytabaco.com，西班牙语资料）。Stogiepress称该厂为垂直整合型工厂，在Cibao河谷的Tamboril拥有自己的烟田。

据Humo y Tabaco称，产品目录中共有约十个系列；其中两个系列见诸专业媒体报道。据Stogiepress称，Diamante口感浓郁，采用墨西哥San Andrés茄衣，搭配全部为多米尼加烟叶的茄套与茄芯。相反，Oro采用厄瓜多尔Connecticut Shade茄衣，搭配多米尼加茄套与茄芯，口感更为温和（据Leaf Enthusiast）。该品牌曾于2019年IPCPR展会亮相（据halfwheel），目前仍在正常销售中。',
        '[{"name":"Diamante","color":"#6B4226","force":"Full","wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"墨西哥茄衣，搭配全部为多米尼加烟叶的茄套与茄芯；据Stogiepress称口感浓郁。"},{"name":"Oro","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade（厄瓜多尔）","vitolas":[],"story":"厄瓜多尔茄衣，搭配多米尼加茄套与茄芯；据Leaf Enthusiast称口感温和。"}]',
        'وُلدت Caoba عام 1992 في Santo Domingo على يد Don Julio Pérez González، وهو إسباني تزوج من دومينيكانية وكان قد أدار حتى ذلك الحين ورشة لنحت خشب الماهوغني — caoba بالإسبانية، وهو أيضًا الشجرة الوطنية للبلاد: ومن هناك، بحسب الشركة، استُمد اسم العلامة. أُقيم المصنع الأصلي في Villa Faro، شرق العاصمة؛ ثم نقله الجيل التالي إلى المنطقة الاستعمارية من Santo Domingo (Ciudad Colonial)، حيث يقع اليوم (بحسب humoytabaco.com، بالإسبانية). وتصف Stogiepress المصنع بأنه متكامل رأسيًا، وله حقوله الخاصة في Tamboril، في وادي Cibao.

تضم التشكيلة نحو عشر سلاسل بحسب Humo y Tabaco؛ اثنتان منها وصفتهما الصحافة المتخصصة. أما Diamante، وهي قوية بحسب Stogiepress، فتجمع بين غلاف San Andrés مكسيكي ورباط وحشوة دومينيكانيين بالكامل. وعلى النقيض، تحمل Oro غلاف Connecticut Shade إكوادوري فوق رباط وحشوة دومينيكانيين، لملمح أخف (بحسب Leaf Enthusiast). وقُدِّمت العلامة في معرض IPCPR عام 2019 (بحسب halfwheel) ولا تزال متوفرة للبيع.',
        '[{"name":"Diamante","color":"#6B4226","force":"Full","wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"غلاف مكسيكي فوق رباط وحشوة دومينيكانيين بالكامل؛ وهي قوية بحسب Stogiepress."},{"name":"Oro","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Shade (الإكوادور)","vitolas":[],"story":"غلاف إكوادوري فوق رباط وحشوة دومينيكانيين؛ وملمحه خفيف بحسب Leaf Enthusiast."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Castillo de Reyes ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Castillo de Reyes',
        'dominican',
        'Non précisée — Felix Reyes, Tamboril',
        'Usine propre — atelier de Felix Reyes, dit « Garage Workshop » par les détaillants, Tamboril (République dominicaine)',
        'cigarworld.de « Castillo de Reyes Cigars » (fiche marque et descriptifs produits : master blender Felix Reyes, manufacture dite « Garage Workshop », torcedores passés par Arturo Fuente, tabacs fermentés sur place, dix torcedores, vitola 3F/Toro Blue aux tabacs de la vallée du Cibao) ; facebook.com « Castillo D Reyes tabacalera » (page de la maison : implantation à Tamboril, République dominicaine)',
        NULL,
        'Castillo de Reyes est une petite marque dominicaine roulée à Tamboril, dans la vallée du Cibao, autour du master blender Felix Reyes. Sa manufacture, que les détaillants appellent « Garage Workshop », emploierait une dizaine de torcedores, dont plusieurs seraient passés par Arturo Fuente ; les tabacs y seraient fermentés sur place. Aucune date de fondation n''est publiée, et ce récit ne repose que sur les textes des détaillants, Cigarworld.de en tête, repris presque à l''identique d''un site à l''autre : la presse spécialisée ne cite pas la marque.

Deux cigares sont documentés, vendus en boîte bleue et en boîte rouge : 3F (Toro Blue), aux tabacs de la vallée du Cibao, et El Mejor Sabor (Toro Red). Cigarworld.de tient toujours la marque au catalogue en septembre 2026.',
        '[{"name":"3F","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Vendue en boîte bleue (Toro Blue) ; tabacs de la vallée du Cibao, notes de chocolat noir et légère amertume, selon le descriptif du distributeur."},{"name":"El Mejor Sabor","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Vendue en boîte rouge (Toro Red) selon Cigarworld.de, qui n''en dit ni la cape ni la force."}]',
        'Castillo de Reyes is a small Dominican brand rolled in Tamboril, in the Cibao valley, built around master blender Felix Reyes. Its factory, which retailers call the Garage Workshop, reportedly employs about ten torcedores, several of whom are said to have come from Arturo Fuente; the tobacco is reportedly fermented on site. No founding date has been published, and this account rests solely on retailers'' texts, led by Cigarworld.de, repeated almost identically from one site to another: the specialist press does not mention the brand.

Two cigars are documented, sold in a blue box and a red box: 3F (Toro Blue), made with tobacco from the Cibao valley, and El Mejor Sabor (Toro Red). Cigarworld.de still lists the brand in its catalogue in September 2026.',
        '[{"name":"3F","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"Sold in a blue box (Toro Blue); tobacco from the Cibao valley, notes of dark chocolate and a slight bitterness, according to the distributor''s description."},{"name":"El Mejor Sabor","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Sold in a red box (Toro Red) according to Cigarworld.de, which states neither its wrapper nor its strength."}]',
        'Castillo de Reyes es una pequeña marca dominicana elaborada en Tamboril, en el valle del Cibao, en torno al master blender Felix Reyes. Su fábrica, a la que los detallistas llaman Garage Workshop, emplearía a una decena de torcedores, varios de los cuales habrían pasado por Arturo Fuente; los tabacos se fermentarían allí mismo. No se ha publicado fecha de fundación, y este relato se apoya únicamente en los textos de los detallistas, encabezados por Cigarworld.de, repetidos de forma casi idéntica de un sitio a otro: la prensa especializada no menciona la marca.

Se documentan dos puros, vendidos en caja azul y en caja roja: 3F (Toro Blue), con tabacos del valle del Cibao, y El Mejor Sabor (Toro Red). Cigarworld.de sigue teniendo la marca en su catálogo en septiembre de 2026.',
        '[{"name":"3F","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Se vende en caja azul (Toro Blue); tabacos del valle del Cibao, notas de chocolate negro y un ligero amargor, según la descripción del distribuidor."},{"name":"El Mejor Sabor","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Se vende en caja roja (Toro Red) según Cigarworld.de, que no indica ni su capa ni su fuerza."}]',
        'Castillo de Reyes ist eine kleine dominikanische Marke, die in Tamboril, im Cibao-Tal, rund um den master blender Felix Reyes gerollt wird. Ihre Fabrik, die Händler Garage Workshop nennen, beschäftigt Berichten zufolge etwa zehn torcedores, von denen mehrere zuvor bei Arturo Fuente gearbeitet haben sollen; die Tabake sollen dort vor Ort fermentiert werden. Es ist kein Gründungsdatum veröffentlicht, und dieser Bericht stützt sich ausschließlich auf Händlertexte, allen voran Cigarworld.de, die fast identisch von einer Website zur anderen übernommen werden: Die Fachpresse erwähnt die Marke nicht.

Zwei Zigarren sind dokumentiert, verkauft in blauer und in roter Kiste: 3F (Toro Blue), mit Tabaken aus dem Cibao-Tal, und El Mejor Sabor (Toro Red). Cigarworld.de führt die Marke im September 2026 weiterhin im Katalog.',
        '[{"name":"3F","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Verkauft in blauer Kiste (Toro Blue); Tabake aus dem Cibao-Tal, Noten von dunkler Schokolade und eine leichte Bitterkeit, laut Beschreibung des Vertriebs."},{"name":"El Mejor Sabor","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Verkauft in roter Kiste (Toro Red) laut Cigarworld.de, das weder Deckblatt noch Stärke angibt."}]',
        'Castillo de Reyes是一个多米尼加小众品牌，在Cibao河谷的Tamboril卷制，围绕master blender Felix Reyes而建立。据称，其工厂——经销商称之为Garage Workshop——雇有约十名torcedores，据说其中数人曾在Arturo Fuente工作过；烟叶据称就地发酵。目前尚无公开的创立年份，这一说法仅见于经销商的文字资料，以Cigarworld.de为首，各网站间的表述几乎完全一致：专业媒体并未提及该品牌。

有据可查的雪茄共两款，分别以蓝盒与红盒出售：3F（Toro Blue），采用Cibao河谷烟叶；以及El Mejor Sabor（Toro Red）。截至2026年9月，Cigarworld.de的目录中仍列有该品牌。',
        '[{"name":"3F","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"以蓝盒（Toro Blue）出售；采用Cibao河谷烟叶，据经销商描述带有黑巧克力气息及轻微苦感。"},{"name":"El Mejor Sabor","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"据Cigarworld.de称以红盒（Toro Red）出售，该网站未说明其茄衣或浓度。"}]',
        'Castillo de Reyes علامة دومينيكانية صغيرة تُلف في Tamboril، في وادي Cibao، حول master blender يُدعى Felix Reyes. ويُقال إن مصنعها، الذي يسميه تجار التجزئة Garage Workshop، يوظف نحو عشرة من الـtorcedores، يُقال إن عددًا منهم سبق أن عملوا لدى Arturo Fuente؛ ويُقال إن التبغ يُخمَّر في الموقع نفسه. ولم يُنشر أي تاريخ للتأسيس، ولا يستند هذا السرد إلا إلى نصوص تجار التجزئة، وفي مقدمتهم Cigarworld.de، وتتكرر بصيغة شبه متطابقة من موقع إلى آخر: ولا تذكر الصحافة المتخصصة هذه العلامة.

هناك سيجاران موثَّقان، يُباعان في علبة زرقاء وعلبة حمراء: 3F (Toro Blue)، من تبغ وادي Cibao، وEl Mejor Sabor (Toro Red). وحتى سبتمبر 2026، لا تزال Cigarworld.de تُدرج العلامة في قائمتها.',
        '[{"name":"3F","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"تُباع في علبة زرقاء (Toro Blue)؛ من تبغ وادي Cibao، بنكهات الشوكولاتة الداكنة ومرارة خفيفة، بحسب وصف الموزّع."},{"name":"El Mejor Sabor","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"تُباع في علبة حمراء (Toro Red) بحسب Cigarworld.de، التي لم تذكر غلافها ولا قوتها."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Dios del Sol ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Dios del Sol',
        'honduras',
        '2025 — Oliver Kopp (Kopp Tobaccos)',
        'Honduras — fabrique non divulguée, dit halfwheel',
        'halfwheel.com « Kopp Tobaccos Launches First Cigar Line, Dios del Sol » (sans date, en anglais : lancement de la marque par Oliver Kopp ; cape Connecticut du Honduras, sous-cape broadleaf hondurienne, tripe Jamastrán/Jalapa ; fabrique explicitement non divulguée par l''entreprise) ; halfwheel.com « Kopp Tobaccos'' Dios del Sol Comes to the U.S. via Arango Cigar Co. » (2026, en anglais : Arango Cigar Co. nommé distributeur exclusif aux États-Unis ; cigare toujours dit handmade in Honduras, fabrique toujours non nommée) ; cigarjournal.com « Kopp Tobaccos Presents Its First In-House Cigar, Dios del Sol » (15 octobre 2025 : premier cigare en propre de Kopp Tobaccos, dirigé par Oliver Kopp ; six vitoles, cape Connecticut du Honduras, sous-cape broadleaf hondurienne, tripe Jamastrán (Honduras) et Jalapa (Nicaragua) ; fabrique dite non divulguée) ; halfwheel.com « Kopp Tobaccos Moves to New Facility Outside Hamburg, Germany » (sans date, en anglais : Kopp Tobaccos, entreprise familiale, remonte à une affaire lancée par Martin Wess le 15 avril 1919 ; Oliver et Thilo Kopp, ses arrière-petits-fils, en sont les seuls propriétaires depuis 2023) ; halfwheel.com « Perdomo Shifts German Distribution to Kopp Tobaccos » (sans date, en anglais : Kopp Tobaccos distribue en Allemagne notamment My Father et, depuis 2026, Perdomo). ; cigarworld.de « Dios del Sol El Principio » (consulté le 24 septembre 2026 : ligne El Principio, Honduras, corps moyen) ; kopp-tobaccos.com « Dios del Sol » (page de la série)',
        NULL,
        'Kopp Tobaccos est un distributeur allemand familial, installé près de Hambourg, qui remonte à une affaire lancée par Martin Wess le 15 avril 1919 ; Oliver et Thilo Kopp, ses arrière-petits-fils, en sont les seuls propriétaires depuis 2023, dit halfwheel. La maison distribue en Allemagne des marques comme My Father et, depuis 2026, Perdomo, et vend aussi du tabac à pipe sous son propre nom.

Dios del Sol, annoncée le 15 octobre 2025, est son premier cigare en propre, mis au point par Oliver Kopp. Le cigare, roulé au Honduras, associe une cape Connecticut hondurienne, une sous-cape broadleaf également hondurienne et une tripe qui mêle des tabacs de Jamastrán (Honduras) et de Jalapa (Nicaragua) ; il se décline en six vitoles, de la Half Corona au Churchill, sous le nom de gamme El Principio, « le commencement ».

La fabrique qui le roule n''est pas divulguée, rapporte halfwheel : Kopp Tobaccos la décrit comme une famille ancienne et reconnue de l''industrie du cigare, sans la nommer. Aucun média n''en dit davantage, y compris à l''arrivée du cigare aux États-Unis via le distributeur Arango Cigar Co., en 2026.',
        '[{"name":"El Principio","color":"#C9A96E","force":"Medium","wrapper":"Connecticut (Honduras)","vitolas":[],"story":"« Le commencement » : cape Connecticut hondurienne, sous-cape broadleaf hondurienne, tripe Jamastrán (Honduras) et Jalapa (Nicaragua), roulé à la main au Honduras ; de corps moyen selon Cigarworld.de."}]',
        'Kopp Tobaccos is a family-run German distributor based near Hamburg, tracing back to a business started by Martin Wess on 15 April 1919; Oliver and Thilo Kopp, his great-grandsons, have been its sole owners since 2023, says halfwheel. The house distributes brands such as My Father in Germany and, since 2026, Perdomo, and also sells pipe tobacco under its own name.

Dios del Sol, announced on 15 October 2025, is its first cigar of its own, developed by Oliver Kopp. The cigar, rolled in Honduras, combines a Honduran Connecticut wrapper, a Honduran broadleaf binder and a filler blending tobaccos from Jamastrán (Honduras) and Jalapa (Nicaragua); it comes in six vitolas, from Half Corona to Churchill, under the range name El Principio, ‘the beginning’.

The factory that rolls it is not disclosed, reports halfwheel: Kopp Tobaccos describes it as an old, well-known family of the cigar industry, without naming it. No media outlet says any more, including when the cigar reached the United States via the distributor Arango Cigar Co. in 2026.',
        '[{"name":"El Principio","color":"#C9A96E","force":"Medium","wrapper":"Connecticut (Honduras)","vitolas":[],"story":"‘The beginning’: Honduran Connecticut wrapper, Honduran broadleaf binder, Jamastrán (Honduras) and Jalapa (Nicaragua) filler, hand-rolled in Honduras; medium-bodied according to Cigarworld.de."}]',
        'Kopp Tobaccos es un distribuidor alemán familiar, instalado cerca de Hamburgo, que se remonta a un negocio iniciado por Martin Wess el 15 de abril de 1919; Oliver y Thilo Kopp, sus bisnietos, son sus únicos propietarios desde 2023, según halfwheel. La casa distribuye en Alemania marcas como My Father y, desde 2026, Perdomo, y también vende tabaco de pipa bajo su propio nombre.

Dios del Sol, anunciado el 15 de octubre de 2025, es su primer cigarro propio, desarrollado por Oliver Kopp. El cigarro, torcido en Honduras, combina una capa Connecticut hondureña, un capote también hondureño de broadleaf y una tripa que mezcla tabacos de Jamastrán (Honduras) y de Jalapa (Nicaragua); se presenta en seis vitolas, de la Half Corona a la Churchill, bajo el nombre de gama El Principio, literalmente «el comienzo».

La fábrica que lo tuerce no se divulga, informa halfwheel: Kopp Tobaccos la describe como una familia antigua y reconocida de la industria del cigarro, sin nombrarla. Ningún medio dice más al respecto, ni siquiera cuando el cigarro llegó a Estados Unidos a través del distribuidor Arango Cigar Co., en 2026.',
        '[{"name":"El Principio","color":"#C9A96E","force":"Medium","wrapper":"Connecticut (Honduras)","vitolas":[],"story":"«El comienzo»: capa Connecticut hondureña, capote de broadleaf hondureño, tripa de Jamastrán (Honduras) y Jalapa (Nicaragua), torcido a mano en Honduras; de cuerpo medio según Cigarworld.de."}]',
        'Kopp Tobaccos ist ein familiengeführter deutscher Distributor mit Sitz bei Hamburg, der auf ein von Martin Wess am 15. April 1919 gegründetes Geschäft zurückgeht; Oliver und Thilo Kopp, seine Urenkel, sind seit 2023 die alleinigen Eigentümer, so halfwheel. Das Haus vertreibt in Deutschland Marken wie My Father und seit 2026 Perdomo und verkauft unter eigenem Namen auch Pfeifentabak.

Dios del Sol, am 15. Oktober 2025 angekündigt, ist die erste eigene Zigarre des Hauses, entwickelt von Oliver Kopp. Die in Honduras gerollte Zigarre vereint ein honduranisches Connecticut-Deckblatt, ein ebenfalls honduranisches Broadleaf-Umblatt und eine Einlage aus Tabaken von Jamastrán (Honduras) und Jalapa (Nicaragua); sie ist in sechs Formaten erhältlich, von der Half Corona bis zur Churchill, unter dem Linienamen El Principio, „der Anfang“.

Die Manufaktur, die sie rollt, wird nicht genannt, berichtet halfwheel: Kopp Tobaccos beschreibt sie als eine alte, anerkannte Familie der Zigarrenindustrie, ohne sie zu nennen. Kein Medium sagt dazu mehr, auch nicht, als die Zigarre 2026 über den Distributor Arango Cigar Co. in die Vereinigten Staaten kam.',
        '[{"name":"El Principio","color":"#C9A96E","force":"Medium","wrapper":"Connecticut (Honduras)","vitolas":[],"story":"„Der Anfang“: honduranisches Connecticut-Deckblatt, honduranisches Broadleaf-Umblatt, Einlage aus Jamastrán (Honduras) und Jalapa (Nicaragua), in Honduras von Hand gerollt; laut Cigarworld.de mittelkräftig."}]',
        'Kopp Tobaccos是一家家族经营的德国经销商，总部设在汉堡附近，其历史可追溯至Martin Wess于1919年4月15日创办的生意；据halfwheel报道，他的曾孙Oliver与Thilo Kopp自2023年起为其唯一所有者。该公司在德国经销My Father等品牌，自2026年起还经销Perdomo，并以自己的名义销售烟斗丝。

Dios del Sol于2025年10月15日发布，是该公司首款自有雪茄，由Oliver Kopp研发而成。这款雪茄在洪都拉斯卷制，采用洪都拉斯产Connecticut茄衣、同样产自洪都拉斯的broadleaf茄套，以及混合了Jamastrán（洪都拉斯）与Jalapa（尼加拉瓜）烟叶的茄芯；共推出六种规格，从Half Corona到Churchill，系列名为El Principio，意为“开端”。

据halfwheel报道，卷制这款雪茄的工厂未被公开：Kopp Tobaccos将其描述为一个历史悠久、备受认可的雪茄行业家族，但未透露其名称。即便在2026年该雪茄经经销商Arango Cigar Co.进入美国市场时，也没有任何媒体透露更多信息。',
        '[{"name":"El Principio","color":"#C9A96E","force":"Medium","wrapper":"Connecticut（洪都拉斯）","vitolas":[],"story":"“开端”：洪都拉斯产Connecticut茄衣，洪都拉斯产broadleaf茄套，茄芯采用Jamastrán（洪都拉斯）与Jalapa（尼加拉瓜）烟叶，在洪都拉斯手工卷制；据Cigarworld.de介绍，浓郁度中等。"}]',
        'شركة Kopp Tobaccos موزّع ألماني عائلي يقع بالقرب من هامبورغ، ويعود تاريخه إلى نشاط تجاري أسسه Martin Wess في 15 أبريل 1919؛ وبحسب halfwheel، فإن Oliver وThilo Kopp، وهما من أحفاد أحفاده، المالكان الوحيدان لها منذ عام 2023. توزّع الشركة في ألمانيا علامات مثل My Father، ومنذ عام 2026 علامة Perdomo، كما تبيع تبغ الغليون تحت اسمها الخاص.

دخل Dios del Sol الأسواق في 15 أكتوبر 2025، وهو أول سيجار خاص بالشركة، طوّره Oliver Kopp. يجمع هذا السيجار، الملفوف في هندوراس، بين غلاف Connecticut هندوراسي، وغلاف داخلي broadleaf هندوراسي أيضاً، وحشوة تمزج تبغ Jamastrán (هندوراس) وJalapa (نيكاراغوا)؛ ويُطرح في ست مقاسات، من Half Corona إلى Churchill، تحت اسم فئة El Principio، أي «البداية».

لم يُكشف عن المصنع الذي يلفّه، بحسب halfwheel: إذ تصفه Kopp Tobaccos بأنه عائلة عريقة ومعروفة في صناعة السيجار، من دون تسميتها. ولم يذكر أي إعلام تفاصيل إضافية، حتى عند وصول السيجار إلى الولايات المتحدة عبر الموزّع Arango Cigar Co. عام 2026.',
        '[{"name":"El Principio","color":"#C9A96E","force":"Medium","wrapper":"Connecticut (هندوراس)","vitolas":[],"story":"«البداية»: غلاف Connecticut هندوراسي، وغلاف داخلي broadleaf هندوراسي، وحشوة من Jamastrán (هندوراس) وJalapa (نيكاراغوا)، ملفوف يدوياً في هندوراس؛ متوسط القوة بحسب Cigarworld.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Flor del Sol ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Flor del Sol',
        'honduras',
        'Non précisée, en vente dès 2014 — STG',
        'Honduras — la maison ne nomme pas sa fabrique',
        'cigarworld.de « Flor del Sol » (sans date : catalogue Cigarworld ; puro hondurien medium filler du groupe Scandinavian Tobacco Group (STG), medium-bodied, Robusto en vente, apparu au catalogue le 28 mai 2018 ; fabrique non nommée) ; thehappycigar.wordpress.com « Today''s Smoke: Flor del Sol Short Robusto » (14 janvier 2014, en anglais : revue attestant le cigare déjà en vente, roulé entièrement à la main, tabac medium filler ; fabrique non nommée) ; st-group.com « Scandinavian Tobacco Group Acquires Two Cigar Factories in Central America » (2009, en anglais : STG possède depuis 2009 des usines à Danlí, Honduras, et Estelí, Nicaragua, sans lien direct établi avec Flor del Sol).',
        NULL,
        'Flor del Sol, dont le nom veut dire « fleur du soleil », appartient au groupe danois Scandinavian Tobacco Group (STG), qui possède aussi Macanudo et Don Tomas. C''est un puro hondurien medium filler, entièrement roulé à la main, dit Cigarworld ; aucune source trouvée, y compris le site du groupe, ne nomme la fabrique hondurienne qui le roule. Le groupe possède depuis 2009 des usines à Danlí, au Honduras, et à Estelí, au Nicaragua, dit Scandinavian Tobacco Group ; aucune source ne relie Flor del Sol à l''une d''elles.

Le cigare est en vente aux États-Unis dès janvier 2014, quand un blog de dégustation le décrit roulé à la main, en medium filler ; Cigarworld.de l''ajoute à son catalogue le 28 mai 2018. Le catalogue actuel ne compte qu''une vitole, un Robusto de corps moyen, dit Cigarworld.',
        '[{"name":"Flor del Sol","color":"#A0522D","force":"Medium","wrapper":"Honduras","vitolas":[],"story":"Puro 100 % hondurien en medium filler, un Robusto de corps moyen, dit Cigarworld."}]',
        'Flor del Sol, whose name means ‘flower of the sun’, belongs to the Danish group Scandinavian Tobacco Group (STG), which also owns Macanudo and Don Tomas. It is a Honduran medium filler puro, entirely hand-rolled, says Cigarworld; no source found, including the group''s own website, names the Honduran factory that rolls it. The group has owned factories in Danlí, Honduras, and Estelí, Nicaragua, since 2009, says Scandinavian Tobacco Group; no source links Flor del Sol to either of them.

The cigar has been on sale in the United States since January 2014, when a tasting blog described it as hand-rolled, medium filler; Cigarworld.de added it to its catalogue on 28 May 2018. The current catalogue lists only one vitola, a medium-bodied Robusto, says Cigarworld.',
        '[{"name":"Flor del Sol","color":"#A0522D","force":"Medium","wrapper":"Honduras","vitolas":[],"story":"A 100% Honduran medium filler puro, a medium-bodied Robusto, says Cigarworld."}]',
        'Flor del Sol, cuyo nombre significa literalmente «flor del sol», pertenece al grupo danés Scandinavian Tobacco Group (STG), que también posee Macanudo y Don Tomas. Es un puro hondureño medium filler, torcido enteramente a mano, según Cigarworld; ninguna fuente encontrada, incluido el sitio del grupo, nombra la fábrica hondureña que lo tuerce. El grupo posee desde 2009 fábricas en Danlí, Honduras, y en Estelí, Nicaragua, según Scandinavian Tobacco Group; ninguna fuente vincula Flor del Sol a alguna de ellas.

El cigarro está a la venta en Estados Unidos desde enero de 2014, cuando un blog de cata lo describe torcido a mano, en medium filler; Cigarworld.de lo añade a su catálogo el 28 de mayo de 2018. El catálogo actual solo cuenta con una vitola, un Robusto de cuerpo medio, según Cigarworld.',
        '[{"name":"Flor del Sol","color":"#A0522D","force":"Medium","wrapper":"Honduras","vitolas":[],"story":"Puro 100 % hondureño en medium filler, un Robusto de cuerpo medio, según Cigarworld."}]',
        'Flor del Sol, dessen Name „Blume der Sonne“ bedeutet, gehört zum dänischen Konzern Scandinavian Tobacco Group (STG), zu dem auch Macanudo und Don Tomas gehören. Es handelt sich um einen honduranischen Medium-Filler-Puro, vollständig von Hand gerollt, so Cigarworld; keine gefundene Quelle, auch nicht die Website des Konzerns, nennt die honduranische Fabrik, die ihn rollt. Der Konzern besitzt seit 2009 Fabriken in Danlí, Honduras, und in Estelí, Nicaragua, so Scandinavian Tobacco Group; keine Quelle verbindet Flor del Sol mit einer von beiden.

Die Zigarre wird seit Januar 2014 in den Vereinigten Staaten verkauft, als ein Verkostungsblog sie als von Hand gerollt, Medium Filler, beschreibt; Cigarworld.de nimmt sie am 28. Mai 2018 in ihr Sortiment auf. Das aktuelle Sortiment umfasst nur ein Format, eine mittelkräftige Robusto, so Cigarworld.',
        '[{"name":"Flor del Sol","color":"#A0522D","force":"Medium","wrapper":"Honduras","vitolas":[],"story":"100 % honduranischer Medium-Filler-Puro, eine mittelkräftige Robusto, so Cigarworld."}]',
        'Flor del Sol，其名意为“太阳之花”，隶属丹麦集团Scandinavian Tobacco Group（STG），该集团旗下还拥有Macanudo与Don Tomas。据Cigarworld介绍，这是一款洪都拉斯产medium filler纯雪茄（puro），完全手工卷制；包括该集团官网在内，没有任何资料透露卷制它的洪都拉斯工厂名称。据Scandinavian Tobacco Group介绍，该集团自2009年起在洪都拉斯的Danlí和尼加拉瓜的Estelí拥有工厂；但没有任何资料显示Flor del Sol与其中哪一家有关。

这款雪茄自2014年1月起已在美国销售，当时一篇品鉴博客将其描述为手工卷制的medium filler雪茄；Cigarworld.de于2018年5月28日将其列入目录。目前该系列仅有一种规格，一款浓郁度中等的Robusto，据Cigarworld介绍。',
        '[{"name":"Flor del Sol","color":"#A0522D","force":"Medium","wrapper":"洪都拉斯","vitolas":[],"story":"100%洪都拉斯medium filler纯雪茄，中等浓郁度的Robusto，据Cigarworld介绍。"}]',
        'تنتمي Flor del Sol، التي يعني اسمها «زهرة الشمس»، إلى المجموعة الدنماركية Scandinavian Tobacco Group (STG)، التي تملك أيضاً Macanudo وDon Tomas. وهي سيجار (puro) هندوراسي من فئة medium filler، ملفوف بالكامل يدوياً، بحسب Cigarworld؛ ولم يذكر أي مصدر تم العثور عليه، بما في ذلك موقع المجموعة نفسه، اسم المصنع الهندوراسي الذي يلفّه. وتملك المجموعة منذ عام 2009 مصانع في Danlí بهندوراس وEstelí بنيكاراغوا، بحسب Scandinavian Tobacco Group؛ ولا يربط أي مصدر Flor del Sol بأي منهما.

طُرح السيجار للبيع في الولايات المتحدة منذ يناير 2014، حين وصفته مدونة تذوق بأنه ملفوف يدوياً من فئة medium filler؛ وأضافته Cigarworld.de إلى فهرسها في 28 مايو 2018. ولا يضم الفهرس الحالي سوى مقاس واحد، وهو Robusto متوسط القوة، بحسب Cigarworld.',
        '[{"name":"Flor del Sol","color":"#A0522D","force":"Medium","wrapper":"هندوراس","vitolas":[],"story":"سيجار (puro) هندوراسي بنسبة 100% من فئة medium filler، وهو Robusto متوسط القوة، بحسب Cigarworld."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Kinix ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Kinix',
        'honduras',
        '2019 — Jurandi Santos et Philipp Noack',
        'Honduras — la maison ne nomme pas sa fabrique',
        'kinix-cigars.com « Über KINIX » (sans date, en allemand : fondation en 2019 par Jurandi Santos, originaire du Honduras, et Philipp Noack ; nom signifiant roi en maya ; dernière actualité datée sur le site : mars 2021, refonte des bagues et partenariat avec Boveda) ; northdata.de « P. Santos Cigars UG » (sans date : extrait du registre du commerce allemand confirmant Philipp Noack et Jurandi Santos comme gérants) ; noblego.de « KINIX Zigarren – Genuss auf den Spuren der Mayas » (sans date, en allemand : catalogue de quatre lignes — Manik, Caban, EB, Ik —, puros longfiller honduriens créés en 2019) ; lacasadetabaco.de « Kinix » (sans date, en allemand : revendeur confirmant l''origine hondurienne, catalogue actif en septembre 2026).',
        NULL,
        'Kinix naît en Allemagne en 2019 de la rencontre de deux amis : Jurandi Santos, originaire du Honduras et amateur de cigares de longue date, convainc Philipp Noack de lancer avec lui une marque propre ; les deux fondent P. Santos Cigars, et les premiers Kinix arrivent sur le marché environ huit mois plus tard, dit le site de la maison. Le nom signifie roi en langue maya, et veut affirmer une exigence de qualité, selon la même source.

Les cigares sont faits entièrement à la main au Honduras, avec du tabac presque exclusivement hondurien, dit la maison ; aucune source trouvée, site propre compris, ne nomme la fabrique. Le catalogue compte quatre lignes — Manik, Caban, EB et Ik —, chacune un assemblage distinct.

Le site de Kinix ne date plus rien depuis mars 2021 — une refonte des bagues et un partenariat avec l''entreprise américaine Boveda ; en septembre 2026, des revendeurs allemands (La Casa del Tabaco, Noblego) la tiennent toujours au catalogue.',
        '[{"name":"Manik","color":"#A0522D","force":"Mild","wrapper":"Non divulguée","vitolas":[],"story":"Notes de cuir, de menthe et de cèdre, dit Noblego."},{"name":"Caban","color":"#8B5A2B","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Notes d''épices, de café et de poivre ; force qualifiée de forte par Noblego."},{"name":"EB","color":"#A0522D","force":"Mild","wrapper":"Non divulguée","vitolas":[],"story":"Notes terreuses, épicées, de cèdre et de cannelle, dit Noblego."},{"name":"Ik","color":"#A0522D","force":"Mild","wrapper":"Non divulguée","vitolas":[],"story":"Notes terreuses, mentholées, de chocolat et de thé, dit Noblego."}]',
        'Kinix was born in Germany in 2019 out of a meeting between two friends: Jurandi Santos, a native of Honduras and a long-standing cigar enthusiast, persuaded Philipp Noack to launch a house brand with him; the two founded P. Santos Cigars, and the first Kinix cigars reached the market roughly eight months later, says the house''s website. The name means king in the Mayan language, and is meant to assert a demand for quality, according to the same source.

The cigars are made entirely by hand in Honduras, with tobacco that is almost exclusively Honduran, says the house; no source found, including its own website, names the factory. The catalogue comprises four lines — Manik, Caban, EB and Ik — each a distinct blend.

The Kinix website has dated nothing since March 2021 — a redesign of the bands and a partnership with the American company Boveda; as of September 2026, German retailers (La Casa del Tabaco, Noblego) still carry it in their catalogues.',
        '[{"name":"Manik","color":"#A0522D","force":"Mild","wrapper":"Undisclosed","vitolas":[],"story":"Notes of leather, mint and cedar, says Noblego."},{"name":"Caban","color":"#8B5A2B","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"Notes of spice, coffee and pepper; a strength described as full by Noblego."},{"name":"EB","color":"#A0522D","force":"Mild","wrapper":"Undisclosed","vitolas":[],"story":"Earthy, spicy notes of cedar and cinnamon, says Noblego."},{"name":"Ik","color":"#A0522D","force":"Mild","wrapper":"Undisclosed","vitolas":[],"story":"Earthy, mentholated notes of chocolate and tea, says Noblego."}]',
        'Kinix nace en Alemania en 2019 del encuentro de dos amigos: Jurandi Santos, originario de Honduras y aficionado al cigarro desde hace tiempo, convence a Philipp Noack de lanzar con él una marca propia; ambos fundan P. Santos Cigars, y los primeros Kinix llegan al mercado unos ocho meses después, según el sitio de la casa. El nombre significa rey en lengua maya, y pretende afirmar una exigencia de calidad, según la misma fuente.

Los cigarros se elaboran enteramente a mano en Honduras, con tabaco casi exclusivamente hondureño, según la casa; ninguna fuente encontrada, incluido su propio sitio, nombra la fábrica. El catálogo cuenta con cuatro líneas —Manik, Caban, EB e Ik—, cada una con una liga distinta.

El sitio de Kinix no fecha nada desde marzo de 2021 —un rediseño de las anillas y una alianza con la empresa estadounidense Boveda—; en septiembre de 2026, varios distribuidores alemanes (La Casa del Tabaco, Noblego) la siguen teniendo en catálogo.',
        '[{"name":"Manik","color":"#A0522D","force":"Mild","wrapper":"No divulgada","vitolas":[],"story":"Notas de cuero, menta y cedro, según Noblego."},{"name":"Caban","color":"#8B5A2B","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"Notas de especias, café y pimienta; fuerza calificada de fuerte por Noblego."},{"name":"EB","color":"#A0522D","force":"Mild","wrapper":"No divulgada","vitolas":[],"story":"Notas terrosas, especiadas, de cedro y canela, según Noblego."},{"name":"Ik","color":"#A0522D","force":"Mild","wrapper":"No divulgada","vitolas":[],"story":"Notas terrosas, mentoladas, de chocolate y té, según Noblego."}]',
        'Kinix entsteht 2019 in Deutschland aus der Begegnung zweier Freunde: Jurandi Santos, gebürtig aus Honduras und langjähriger Zigarrenliebhaber, überzeugt Philipp Noack, gemeinsam mit ihm eine eigene Marke zu gründen; beide gründen P. Santos Cigars, und die ersten Kinix-Zigarren kommen etwa acht Monate später auf den Markt, so die Website des Hauses. Der Name bedeutet in der Maya-Sprache König und soll laut derselben Quelle einen Qualitätsanspruch zum Ausdruck bringen.

Die Zigarren werden vollständig von Hand in Honduras gefertigt, mit fast ausschließlich honduranischem Tabak, so das Haus; keine gefundene Quelle, auch nicht die eigene Website, nennt die Manufaktur. Das Sortiment umfasst vier Linien — Manik, Caban, EB und Ik —, jede mit einer eigenen Mischung.

Die Kinix-Website datiert seit März 2021 nichts mehr — eine Neugestaltung der Banderolen und eine Partnerschaft mit dem amerikanischen Unternehmen Boveda; im September 2026 führen deutsche Händler (La Casa del Tabaco, Noblego) die Marke weiterhin im Sortiment.',
        '[{"name":"Manik","color":"#A0522D","force":"Mild","wrapper":"Nicht angegeben","vitolas":[],"story":"Noten von Leder, Minze und Zeder, so Noblego."},{"name":"Caban","color":"#8B5A2B","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Noten von Gewürzen, Kaffee und Pfeffer; die Stärke wird von Noblego als kräftig bezeichnet."},{"name":"EB","color":"#A0522D","force":"Mild","wrapper":"Nicht angegeben","vitolas":[],"story":"Erdige, würzige Noten von Zeder und Zimt, so Noblego."},{"name":"Ik","color":"#A0522D","force":"Mild","wrapper":"Nicht angegeben","vitolas":[],"story":"Erdige, mentholige Noten von Schokolade und Tee, so Noblego."}]',
        'Kinix于2019年诞生于德国，源于两位好友的相遇：Jurandi Santos出生于洪都拉斯，是资深雪茄迷，他说服Philipp Noack与自己共同创立一个自有品牌；两人由此创立P. Santos Cigars，据该公司网站介绍，首批Kinix雪茄大约八个月后上市。据同一资料来源，该名称在玛雅语中意为国王，旨在彰显对品质的追求。

据该公司介绍，这些雪茄完全在洪都拉斯手工制作，所用烟叶几乎全部产自洪都拉斯；未找到任何资料，包括其官网在内，透露具体工厂名称。该系列共有四条产品线——Manik、Caban、EB与Ik——每款均为独立配方。

Kinix官网自2021年3月起未再更新任何日期信息——彼时进行了茄标改版，并与美国企业Boveda建立合作关系；截至2026年9月，多家德国经销商（La Casa del Tabaco、Noblego）仍将其列入目录。',
        '[{"name":"Manik","color":"#A0522D","force":"Mild","wrapper":"未公开","vitolas":[],"story":"带有皮革、薄荷与雪松的香气，据Noblego介绍。"},{"name":"Caban","color":"#8B5A2B","force":"Full","wrapper":"未公开","vitolas":[],"story":"带有香料、咖啡与胡椒的香气；据Noblego介绍，力度属于浓郁一类。"},{"name":"EB","color":"#A0522D","force":"Mild","wrapper":"未公开","vitolas":[],"story":"带有泥土气息、辛香、雪松与肉桂的香气，据Noblego介绍。"},{"name":"Ik","color":"#A0522D","force":"Mild","wrapper":"未公开","vitolas":[],"story":"带有泥土气息、薄荷、巧克力与茶香，据Noblego介绍。"}]',
        'وُلدت Kinix في ألمانيا عام 2019 من لقاء صديقين: Jurandi Santos، وهو هندوراسي الأصل وهاوٍ قديم للسيجار، أقنع Philipp Noack بإطلاق علامة خاصة معه؛ أسّس الاثنان شركة P. Santos Cigars، ووصلت أولى سيجارات Kinix إلى السوق بعد نحو ثمانية شهور، بحسب موقع الشركة. ويعني الاسم «الملك» بلغة المايا، ويهدف إلى التأكيد على معيار جودة عالٍ، بحسب المصدر نفسه.

تُصنع السجائر بالكامل يدوياً في هندوراس، من تبغ هندوراسي في معظمه تقريباً، بحسب الشركة؛ ولم يذكر أي مصدر تم العثور عليه، بما في ذلك موقعها الخاص، اسم المصنع. ويضم الفهرس أربع فئات — Manik وCaban وEB وIk — لكل منها خلطة تبغ مختلفة.

لم يعد موقع Kinix يذكر أي تاريخ جديد منذ مارس 2021 — حين جرى تجديد تصميم شريط السيجار وأُبرمت شراكة مع الشركة الأمريكية Boveda؛ وحتى سبتمبر 2026، لا يزال عدد من الموزّعين الألمان (La Casa del Tabaco وNoblego) يعرضونها في فهارسهم.',
        '[{"name":"Manik","color":"#A0522D","force":"Mild","wrapper":"غير معلن","vitolas":[],"story":"نكهات الجلد والنعناع وخشب الأرز، بحسب Noblego."},{"name":"Caban","color":"#8B5A2B","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"نكهات التوابل والقهوة والفلفل؛ قوة توصف بأنها قوية بحسب Noblego."},{"name":"EB","color":"#A0522D","force":"Mild","wrapper":"غير معلن","vitolas":[],"story":"نكهات ترابية وحارة، من خشب الأرز والقرفة، بحسب Noblego."},{"name":"Ik","color":"#A0522D","force":"Mild","wrapper":"غير معلن","vitolas":[],"story":"نكهات ترابية ونعناعية، من الشوكولاتة والشاي، بحسب Noblego."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Rodrigo de Jerez ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Rodrigo de Jerez',
        'honduras',
        'Non précisée — August Schuster, Bünde',
        'Honduras — la maison ne nomme pas sa fabrique',
        'starkezigarren.de « Rodrigo de Jerez Zigarren » (sans date, en allemand : marque composée par August Schuster (Bünde), déclinée en trois origines — Honduras, Nicaragua, République dominicaine —, ligne Honduras en 100 % tabac hondurien) ; cigarworld.de « Rodrigo de Jerez Honduras Grün Robusto » (sans date, en allemand : Herstellungsart TAM, Totalmente a Mano ; importateur August Schuster GmbH & Co. KG ; cape brun foncé et huileuse du Honduras ; fabrique non nommée) ; cigarsmokerclub.com « Rodrigo de Jerez Cigars, Honduras » (sans date, en anglais : ligne Honduras présentée comme un puro épicé, fabrique non nommée) ; noblego.de « Rodrigo de Jerez Dominikanische Republik » (sans date, en allemand : ligne rouge, cape Connecticut Shade, sous-cape et tripe de République dominicaine, force qualifiée de forte) ; cigarworld.de « Rodrigo de Jerez Nicaragua (Blau) » (sans date, en allemand : ligne bleue, cape Connecticut fine et claire d''Équateur, tripe de Panama, du Nicaragua et du Costa Rica, force qualifiée de douce, roulage nicaraguayen) ; fahr-im-kreis.de « Zigarrenfabrik „August Schuster“ – Bünde » (sans date, en allemand : fondation d''une première fabrique par Hermann Schuster en 1897 ; inscription au registre du commerce par August Schuster le 27 septembre 1909) ; starkezigarren.de « Wer ist August Schuster » (sans date, en allemand : la maison se présente elle-même comme fondée en 1909).',
        NULL,
        'August Schuster GmbH & Co. KG, négociant familial de cigares installé à Bünde (Allemagne), remonte à une fabrique fondée par Hermann Schuster en 1897 dans cette ville ; la société actuelle, elle, a été inscrite au registre du commerce par August Schuster le 27 septembre 1909, dit fahr-im-kreis.de — les deux dates circulent selon les sources, et la maison elle-même retient 1909.

La maison a composé Rodrigo de Jerez, cigare dont le nom rappelle un marin de l''équipage de Christophe Colomb crédité d''avoir rapporté le tabac en Europe en 1492, dit Cigarworld. La marque se décline en trois lignes selon l''origine du tabac : une ligne verte, roulée Totalmente a Mano (TAM) et entièrement en tabac hondurien, à la cape brun foncé et huileuse ; une ligne rouge, cape Connecticut Shade sur tripe et sous-cape de République dominicaine, de force dite forte ; une ligne bleue, roulée au Nicaragua, cape Connecticut fine d''Équateur, claire, sur une tripe mêlant tabacs du Panama, du Nicaragua et du Costa Rica, dite douce par Cigarworld.

Aucune fabrique n''est nommée par les sources trouvées, dans aucune des trois origines. En septembre 2026, les trois lignes sont en vente chez plusieurs détaillants allemands (Cigarworld, Noblego, Cigarmaxx).',
        '[{"name":"Honduras (Grün)","color":"#6B4226","force":null,"wrapper":"Honduras, brun foncé","vitolas":[],"story":"Entièrement en tabac hondurien, roulée Totalmente a Mano (TAM), dit Cigarworld."},{"name":"Dominikanische Republik (Rot)","color":"#C9A96E","force":"Full","wrapper":"Connecticut Shade","vitolas":[],"story":"Tripe et sous-cape dominicaines sous cape Connecticut Shade, dit Noblego."},{"name":"Nicaragua (Blau)","color":"#C9A96E","force":"Mild","wrapper":"Connecticut Équateur, claire","vitolas":[],"story":"Roulée au Nicaragua, tripe mêlant tabacs du Panama, du Nicaragua et du Costa Rica, dite douce par Cigarworld."}]',
        'August Schuster GmbH & Co. KG, a family cigar merchant based in Bünde (Germany), traces back to a factory founded by Hermann Schuster in that town in 1897; the current company, meanwhile, was entered in the commercial register by August Schuster on 27 September 1909, says fahr-im-kreis.de — both dates circulate depending on the source, and the house itself favours 1909.

The house composed Rodrigo de Jerez, a cigar whose name recalls a sailor from Christopher Columbus''s crew credited with having brought tobacco back to Europe in 1492, says Cigarworld. The brand comes in three lines according to the origin of the tobacco: a green line, rolled Totalmente a Mano (TAM) and entirely in Honduran tobacco, with a dark brown, oily wrapper; a red line, with a Connecticut Shade wrapper over Dominican filler and binder, with a strength described as full; a blue line, rolled in Nicaragua, with a fine, light Ecuador Connecticut wrapper, over a filler blending tobaccos from Panama, Nicaragua and Costa Rica, described as mild by Cigarworld.

No factory is named by the sources found, for any of the three origins. As of September 2026, all three lines are on sale at several German retailers (Cigarworld, Noblego, Cigarmaxx).',
        '[{"name":"Honduras (Grün)","color":"#6B4226","force":null,"wrapper":"Honduras, dark brown","vitolas":[],"story":"Entirely in Honduran tobacco, rolled Totalmente a Mano (TAM), says Cigarworld."},{"name":"Dominikanische Republik (Rot)","color":"#C9A96E","force":"Full","wrapper":"Connecticut Shade","vitolas":[],"story":"Dominican filler and binder under a Connecticut Shade wrapper, says Noblego."},{"name":"Nicaragua (Blau)","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Ecuador), light","vitolas":[],"story":"Rolled in Nicaragua, with a filler blending tobaccos from Panama, Nicaragua and Costa Rica, described as mild by Cigarworld."}]',
        'August Schuster GmbH & Co. KG, comerciante familiar de cigarros con sede en Bünde (Alemania), se remonta a una fábrica fundada por Hermann Schuster en esa ciudad en 1897; la sociedad actual, por su parte, fue inscrita en el registro mercantil por August Schuster el 27 de septiembre de 1909, según fahr-im-kreis.de —ambas fechas circulan según las fuentes, y la propia casa se queda con 1909.

La casa compuso Rodrigo de Jerez, cigarro cuyo nombre recuerda a un marinero de la tripulación de Cristóbal Colón, al que se atribuye haber traído el tabaco a Europa en 1492, según Cigarworld. La marca se presenta en tres líneas según el origen del tabaco: una línea verde, torcida Totalmente a Mano (TAM) y enteramente en tabaco hondureño, con capa marrón oscura y aceitosa; una línea roja, con capa Connecticut Shade sobre tripa y capote de República Dominicana, de fuerza calificada de fuerte; una línea azul, torcida en Nicaragua, con capa Connecticut (Ecuador) fina y clara, sobre una tripa que mezcla tabacos de Panamá, Nicaragua y Costa Rica, calificada de suave por Cigarworld.

Ninguna fábrica es nombrada por las fuentes encontradas, en ninguno de los tres orígenes. En septiembre de 2026, las tres líneas están a la venta en varios minoristas alemanes (Cigarworld, Noblego, Cigarmaxx).',
        '[{"name":"Honduras (Grün)","color":"#6B4226","force":null,"wrapper":"Honduras, marrón oscuro","vitolas":[],"story":"Enteramente en tabaco hondureño, torcida Totalmente a Mano (TAM), según Cigarworld."},{"name":"Dominikanische Republik (Rot)","color":"#C9A96E","force":"Full","wrapper":"Connecticut Shade","vitolas":[],"story":"Tripa y capote dominicanos bajo capa Connecticut Shade, según Noblego."},{"name":"Nicaragua (Blau)","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Ecuador), clara","vitolas":[],"story":"Torcida en Nicaragua, con tripa que mezcla tabacos de Panamá, Nicaragua y Costa Rica, calificada de suave por Cigarworld."}]',
        'August Schuster GmbH & Co. KG, ein Familienunternehmen für Zigarrenhandel mit Sitz in Bünde (Deutschland), geht zurück auf eine 1897 von Hermann Schuster in dieser Stadt gegründete Fabrik; die heutige Gesellschaft wiederum wurde am 27. September 1909 von August Schuster ins Handelsregister eingetragen, so fahr-im-kreis.de — beide Daten kursieren je nach Quelle, und das Haus selbst nennt 1909.

Das Haus schuf Rodrigo de Jerez, eine Zigarre, deren Name an einen Matrosen aus der Mannschaft von Christoph Kolumbus erinnert, dem zugeschrieben wird, den Tabak 1492 nach Europa gebracht zu haben, so Cigarworld. Die Marke gibt es in drei Linien je nach Tabakherkunft: eine grüne Linie, Totalmente a Mano (TAM) gerollt und vollständig aus honduranischem Tabak, mit dunkelbraunem, öligem Deckblatt; eine rote Linie, mit Connecticut-Shade-Deckblatt über dominikanischer Einlage und Umblatt, deren Stärke als kräftig bezeichnet wird; eine blaue Linie, in Nicaragua gerollt, mit feinem, hellem Connecticut-Deckblatt aus Ecuador, über einer Einlage aus Tabaken aus Panama, Nicaragua und Costa Rica, von Cigarworld als mild bezeichnet.

Keine der gefundenen Quellen nennt eine Fabrik, für keinen der drei Ursprungsländer. Im September 2026 sind alle drei Linien bei mehreren deutschen Händlern erhältlich (Cigarworld, Noblego, Cigarmaxx).',
        '[{"name":"Honduras (Grün)","color":"#6B4226","force":null,"wrapper":"Honduras, dunkelbraun","vitolas":[],"story":"Vollständig aus honduranischem Tabak, Totalmente a Mano (TAM) gerollt, so Cigarworld."},{"name":"Dominikanische Republik (Rot)","color":"#C9A96E","force":"Full","wrapper":"Connecticut Shade","vitolas":[],"story":"Dominikanische Einlage und Umblatt unter Connecticut-Shade-Deckblatt, so Noblego."},{"name":"Nicaragua (Blau)","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Ecuador), hell","vitolas":[],"story":"In Nicaragua gerollt, mit einer Einlage aus Tabaken aus Panama, Nicaragua und Costa Rica, von Cigarworld als mild bezeichnet."}]',
        'August Schuster GmbH & Co. KG是一家总部位于德国Bünde的家族雪茄贸易公司，其历史可追溯至Hermann Schuster于1897年在该市创办的一家工厂；据fahr-im-kreis.de介绍，现今的公司则由August Schuster于1909年9月27日在商业登记处注册——两个年份因资料来源不同而并存，公司本身采用1909年这一说法。

据Cigarworld介绍，公司推出了Rodrigo de Jerez这款雪茄，其名称让人联想到克里斯托弗·哥伦布船队中的一名水手，据信正是他于1492年将烟草带回欧洲。该品牌依烟叶产地分为三个系列：绿色系列，以Totalmente a Mano（TAM）方式卷制，烟叶完全产自洪都拉斯，茄衣呈深棕色且油润；红色系列，茄衣为Connecticut Shade，茄芯与茄套均产自多米尼加共和国，力度被称为浓郁；蓝色系列，在尼加拉瓜卷制，茄衣为细致浅色的Connecticut（厄瓜多尔），茄芯混合巴拿马、尼加拉瓜与哥斯达黎加烟叶，据Cigarworld介绍属于温和一类。

在这三种产地系列中，现有资料均未透露具体工厂名称。截至2026年9月，三个系列均在多家德国零售商（Cigarworld、Noblego、Cigarmaxx）有售。',
        '[{"name":"Honduras (Grün)","color":"#6B4226","force":null,"wrapper":"洪都拉斯，深棕色","vitolas":[],"story":"烟叶完全产自洪都拉斯，以Totalmente a Mano（TAM）方式手工卷制，据Cigarworld介绍。"},{"name":"Dominikanische Republik (Rot)","color":"#C9A96E","force":"Full","wrapper":"Connecticut Shade","vitolas":[],"story":"茄芯与茄套均产自多米尼加共和国，外覆Connecticut Shade茄衣，据Noblego介绍。"},{"name":"Nicaragua (Blau)","color":"#C9A96E","force":"Mild","wrapper":"Connecticut（厄瓜多尔），浅色","vitolas":[],"story":"在尼加拉瓜卷制，茄芯混合巴拿马、尼加拉瓜与哥斯达黎加烟叶，据Cigarworld介绍属于温和一类。"}]',
        'شركة August Schuster GmbH & Co. KG تاجر سيجار عائلي مقره في مدينة Bünde بألمانيا، ويعود تاريخها إلى مصنع أسسه Hermann Schuster في تلك المدينة عام 1897؛ أما الشركة الحالية فقد سُجّلت في السجل التجاري باسم August Schuster في 27 سبتمبر 1909، بحسب fahr-im-kreis.de — والتاريخان يتداولان بحسب المصدر، فيما تعتمد الشركة نفسها سنة 1909.

ابتكرت الشركة Rodrigo de Jerez، وهو سيجار يُذكّر اسمه ببحّار من طاقم كريستوفر كولومبوس يُنسب إليه أنه أعاد التبغ إلى أوروبا عام 1492، بحسب Cigarworld. وتُطرح العلامة في ثلاث فئات بحسب منشأ التبغ: فئة خضراء، ملفوفة بطريقة Totalmente a Mano (TAM) ومن تبغ هندوراسي بالكامل، بغلاف بنّي داكن وزيتي؛ وفئة حمراء، بغلاف Connecticut Shade فوق حشوة وغلاف داخلي من الجمهورية الدومينيكية، بقوة توصف بأنها قوية؛ وفئة زرقاء، ملفوفة في نيكاراغوا، بغلاف Connecticut (الإكوادور) رقيق وفاتح اللون، فوق حشوة تمزج تبغ بنما ونيكاراغوا وكوستاريكا، توصف بأنها خفيفة بحسب Cigarworld.

لا تذكر المصادر التي تم العثور عليها اسم أي مصنع، في أي من المنابت الثلاثة. وحتى سبتمبر 2026، تُباع الفئات الثلاث لدى عدة تجار تجزئة ألمان (Cigarworld وNoblego وCigarmaxx).',
        '[{"name":"Honduras (Grün)","color":"#6B4226","force":null,"wrapper":"هندوراس، بني داكن","vitolas":[],"story":"من تبغ هندوراسي بالكامل، ملفوفة بطريقة Totalmente a Mano (TAM)، بحسب Cigarworld."},{"name":"Dominikanische Republik (Rot)","color":"#C9A96E","force":"Full","wrapper":"Connecticut Shade","vitolas":[],"story":"حشوة وغلاف داخلي من الجمهورية الدومينيكية تحت غلاف Connecticut Shade، بحسب Noblego."},{"name":"Nicaragua (Blau)","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (الإكوادور)، فاتح","vitolas":[],"story":"ملفوفة في نيكاراغوا، بحشوة تمزج تبغ بنما ونيكاراغوا وكوستاريكا، توصف بأنها خفيفة بحسب Cigarworld."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Wolfertz ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Wolfertz',
        'honduras',
        '1999 — Thorsten Wolfertz, Solingen',
        'Chez Raíces Cubanas (Hugo Cesar), Danlí, Honduras',
        'wlw.de « Wolfertz GmbH » (sans date, en allemand : identifie Wolfertz GmbH, Solingen, comme importateur de cigares du Honduras, du Nicaragua et de République dominicaine) ; starkezigarren.de « Thorsten Wolfertz im Interview mit StarkeZigarren » (sans date, en allemand : histoire de la maison — coutellerie fondée en 1919, import de cigares depuis 1999 sous la direction de Thorsten Wolfertz) ; wolfertz-gmbh.com « Wir präsentieren unsere Eigenmarke Aventura Cigars – Das Abenteuer » (26 août 2019, en allemand : lancement de la ligne propre Aventura, mise au point avec Hugo Cesar, propriétaire de la manufacture Raíces Cubanas à Danlí, et Ralph Montero, master blender d''Alec Bradley) ; starkezigarren.de « Wolfertz Aventura Robusto » (sans date, en allemand : cape hondurienne fine de Trojes, sous-capes du Nicaragua et d''Indonésie, tripe du Honduras et du Nicaragua, force dite douce à moyenne) ; cigarworld.de « Wolfertz » (sans date : catalogue Wolfertz limité à la ligne Aventura au moment de la recherche) ; cigarjournal.com « VCF Acquires Wörmann Cigars and Reaches Agreement with Wolfertz » (sans date, en anglais : accord entre VCF et Wolfertz GmbH pour la reprise des activités cigares, accessoires Xikar et spiritueux au 1er janvier 2023 ; Thorsten Wolfertz rejoint la nouvelle structure et reste responsable des activités commerciales) ; smokersplanet.de « Vertriebsgesellschaft VCF Deutschland startet im Januar mit beeindruckendem Marken-Portfolio » (sans date, en allemand : VCF, dirigée par Fred Vandermarliere, regroupe au 1er janvier 2023 Wolfertz GmbH et Wörmann Cigars, après avoir racheté Oliva en 2016) ; cigarworld.de « Buy Barrio Viejo Cigars cigars » (sans date, en anglais : Barrio Viejo, marque lancée par Thorsten Wolfertz, transférée à VCF avec l''ensemble de l''inventaire Wolfertz en 2023, vendue aujourd''hui sans la marque Wolfertz).',
        NULL,
        'Wolfertz GmbH, négociant de cigares basé à Solingen (Allemagne), descend d''une maison de coutellerie établie en 1919 ; elle importe des cigares depuis 1999 sous la direction de Thorsten Wolfertz, dit une interview donnée à StarkeZigarren.

En 2019, la maison lance sa première ligne propre, Aventura, roulée à la manufacture Raíces Cubanas, à Danlí (Honduras), que dirige Hugo Cesar ; l''assemblage a été mis au point avec Ralph Montero, master blender d''Alec Bradley, dit Wolfertz. Elle avait aussi lancé une seconde ligne propre, Barrio Viejo : celle-ci a été vendue, avec l''ensemble de l''activité cigares, accessoires Xikar et spiritueux de Wolfertz, au groupe belge VCF (Vandermarliere Cigar Family), pour sa filiale allemande, au 1er janvier 2023 ; Thorsten Wolfertz rejoignait VCF comme responsable des activités commerciales. Barrio Viejo se vend aujourd''hui sous son seul nom, sans la marque Wolfertz.

VCF, dirigée par Fred Vandermarliere, possédait déjà Oliva (depuis 2016) et venait d''acquérir Wörmann Cigars quand elle a intégré Wolfertz à sa structure allemande de distribution, dit smokersplanet.de. En 2026, Cigarworld.de ne vend plus sous le nom Wolfertz que la ligne Aventura.',
        '[{"name":"Aventura","color":"#A0522D","force":"Mild-Medium","wrapper":"Honduras (Trojes)","vitolas":[],"story":"Cape hondurienne de Trojes, sous-capes du Nicaragua et d''Indonésie, tripe du Honduras et du Nicaragua, douce à moyenne selon StarkeZigarren ; mise au point avec Hugo Cesar, propriétaire de la manufacture, et Ralph Montero, master blender d''Alec Bradley, dit Wolfertz."}]',
        'Wolfertz GmbH, a cigar merchant based in Solingen (Germany), descends from a cutlery house established in 1919; it has imported cigars since 1999 under the direction of Thorsten Wolfertz, says an interview given to StarkeZigarren.

In 2019, the house launched its first house line, Aventura, rolled at the Raíces Cubanas factory in Danlí (Honduras), run by Hugo Cesar; the blend was developed with Ralph Montero, master blender at Alec Bradley, says Wolfertz. It had also launched a second house line, Barrio Viejo: this was sold, together with the whole of Wolfertz''s cigar business, Xikar accessories and spirits, to the Belgian group VCF (Vandermarliere Cigar Family), for its German subsidiary, on 1 January 2023; Thorsten Wolfertz joined VCF as head of commercial activities. Barrio Viejo is sold today under its name alone, without the Wolfertz brand.

VCF, led by Fred Vandermarliere, already owned Oliva (since 2016) and had just acquired Wörmann Cigars when it folded Wolfertz into its German distribution structure, says smokersplanet.de. In 2026, Cigarworld.de sells only the Aventura line under the Wolfertz name.',
        '[{"name":"Aventura","color":"#A0522D","force":"Mild-Medium","wrapper":"Honduras (Trojes)","vitolas":[],"story":"Honduran wrapper from Trojes, Nicaraguan and Indonesian binders, Honduran and Nicaraguan filler, mild to medium according to StarkeZigarren; developed with Hugo Cesar, owner of the factory, and Ralph Montero, master blender at Alec Bradley, says Wolfertz."}]',
        'Wolfertz GmbH, comerciante de cigarros con sede en Solingen (Alemania), desciende de una casa de cuchillería establecida en 1919; importa cigarros desde 1999 bajo la dirección de Thorsten Wolfertz, según una entrevista concedida a StarkeZigarren.

En 2019, la casa lanza su primera línea propia, Aventura, torcida en la manufactura Raíces Cubanas, en Danlí (Honduras), dirigida por Hugo Cesar; la liga se puso a punto con Ralph Montero, master blender de Alec Bradley, según Wolfertz. También había lanzado una segunda línea propia, Barrio Viejo: esta fue vendida, junto con todo el negocio de cigarros, accesorios Xikar y licores de Wolfertz, al grupo belga VCF (Vandermarliere Cigar Family), para su filial alemana, el 1 de enero de 2023; Thorsten Wolfertz se incorporó a VCF como responsable de las actividades comerciales. Barrio Viejo se vende hoy solo bajo su propio nombre, sin la marca Wolfertz.

VCF, dirigida por Fred Vandermarliere, ya poseía Oliva (desde 2016) y acababa de adquirir Wörmann Cigars cuando integró Wolfertz en su estructura alemana de distribución, según smokersplanet.de. En 2026, Cigarworld.de solo vende bajo el nombre Wolfertz la línea Aventura.',
        '[{"name":"Aventura","color":"#A0522D","force":"Mild-Medium","wrapper":"Honduras (Trojes)","vitolas":[],"story":"Capa hondureña de Trojes, capotes de Nicaragua e Indonesia, tripa de Honduras y Nicaragua, suave a media según StarkeZigarren; puesta a punto con Hugo Cesar, propietario de la manufactura, y Ralph Montero, master blender de Alec Bradley, según Wolfertz."}]',
        'Die Wolfertz GmbH, ein Zigarrenhändler mit Sitz in Solingen (Deutschland), geht auf eine seit 1919 bestehende Schneidwarenhandlung zurück; sie importiert seit 1999 unter der Leitung von Thorsten Wolfertz Zigarren, so ein Interview mit StarkeZigarren.

2019 brachte das Haus seine erste eigene Linie auf den Markt, Aventura, gerollt in der Manufaktur Raíces Cubanas in Danlí (Honduras), die von Hugo Cesar geleitet wird; die Mischung wurde gemeinsam mit Ralph Montero, Master Blender von Alec Bradley, entwickelt, so Wolfertz. Zuvor hatte das Haus bereits eine zweite eigene Linie lanciert, Barrio Viejo: Diese wurde, zusammen mit dem gesamten Zigarrengeschäft, den Xikar-Accessoires und den Spirituosen von Wolfertz, am 1. Januar 2023 an die belgische Gruppe VCF (Vandermarliere Cigar Family) für deren deutsche Tochtergesellschaft verkauft; Thorsten Wolfertz wechselte zu VCF als Verantwortlicher für die kaufmännischen Aktivitäten. Barrio Viejo wird heute allein unter eigenem Namen verkauft, ohne die Marke Wolfertz.

VCF, geleitet von Fred Vandermarliere, besaß bereits Oliva (seit 2016) und hatte gerade Wörmann Cigars übernommen, als sie Wolfertz in ihre deutsche Vertriebsstruktur eingliederte, so smokersplanet.de. 2026 verkauft Cigarworld.de unter dem Namen Wolfertz nur noch die Linie Aventura.',
        '[{"name":"Aventura","color":"#A0522D","force":"Mild-Medium","wrapper":"Honduras (Trojes)","vitolas":[],"story":"Honduranisches Deckblatt aus Trojes, Umblätter aus Nicaragua und Indonesien, Einlage aus Honduras und Nicaragua, laut StarkeZigarren mild bis mittelkräftig; entwickelt mit Hugo Cesar, dem Inhaber der Manufaktur, und Ralph Montero, Master Blender von Alec Bradley, so Wolfertz."}]',
        'Wolfertz GmbH是一家总部位于德国Solingen的雪茄贸易公司，其渊源可追溯至一家自1919年起经营的刀具商行；自1999年起，该公司在Thorsten Wolfertz的领导下开始进口雪茄，据其接受StarkeZigarren采访时所说。

2019年，公司推出首条自有产品线Aventura，在洪都拉斯Danlí的Raíces Cubanas工厂卷制，该厂由Hugo Cesar主理；据Wolfertz介绍，该配方是与Alec Bradley的master blender Ralph Montero共同研发而成。公司此前还推出过第二条自有产品线Barrio Viejo：该产品线连同Wolfertz的全部雪茄业务、Xikar配件业务及烈酒业务，于2023年1月1日一并出售给比利时集团VCF（Vandermarliere Cigar Family）旗下的德国子公司；Thorsten Wolfertz随后加入VCF，负责商业事务。如今Barrio Viejo仅以自己的名称单独销售，不再使用Wolfertz品牌。

据smokersplanet.de介绍，VCF由Fred Vandermarliere领导，此前已拥有Oliva（自2016年起），并刚收购了Wörmann Cigars，随后又将Wolfertz并入其德国经销体系。2026年，Cigarworld.de在Wolfertz名下仅销售Aventura这一条产品线。',
        '[{"name":"Aventura","color":"#A0522D","force":"Mild-Medium","wrapper":"洪都拉斯（Trojes）","vitolas":[],"story":"茄衣产自洪都拉斯Trojes，茄套分别产自尼加拉瓜与印度尼西亚，茄芯产自洪都拉斯与尼加拉瓜，据StarkeZigarren介绍力度温和至中等；配方由工厂主理人Hugo Cesar与Alec Bradley的master blender Ralph Montero共同研发，据Wolfertz介绍。"}]',
        'شركة Wolfertz GmbH تاجر سيجار مقرها في مدينة Solingen بألمانيا، وتعود جذورها إلى محل لصناعة السكاكين قائم منذ عام 1919؛ وتستورد السيجار منذ عام 1999 بقيادة Thorsten Wolfertz، بحسب مقابلة أجرتها معه StarkeZigarren.

في عام 2019، أطلقت الشركة أول خط منتجات خاص بها، Aventura، الذي يُلف في مصنع Raíces Cubanas بمدينة Danlí (هندوراس)، ويديره Hugo Cesar؛ وطُوّرت الخلطة بالتعاون مع Ralph Montero، master blender لدى Alec Bradley، بحسب Wolfertz. وكانت الشركة قد أطلقت أيضاً خطاً ثانياً خاصاً بها، Barrio Viejo: بيع هذا الخط، مع كامل نشاط السيجار وإكسسوارات Xikar والمشروبات الروحية الخاصة بـWolfertz، إلى المجموعة البلجيكية VCF (Vandermarliere Cigar Family) لصالح فرعها الألماني، في 1 يناير 2023؛ والتحق Thorsten Wolfertz بـVCF مسؤولاً عن الأنشطة التجارية. ويُباع Barrio Viejo اليوم باسمه وحده، من دون علامة Wolfertz.

بحسب smokersplanet.de، كانت VCF، بقيادة Fred Vandermarliere، تملك بالفعل Oliva (منذ عام 2016) وكانت قد استحوذت للتو على Wörmann Cigars حين أدمجت Wolfertz ضمن هيكل التوزيع الألماني الخاص بها. وفي عام 2026، لا يبيع Cigarworld.de تحت اسم Wolfertz سوى خط Aventura.',
        '[{"name":"Aventura","color":"#A0522D","force":"Mild-Medium","wrapper":"هندوراس (Trojes)","vitolas":[],"story":"غلاف هندوراسي من Trojes، وغلافان داخليان من نيكاراغوا وإندونيسيا، وحشوة من هندوراس ونيكاراغوا، بقوة توصف بأنها خفيفة إلى متوسطة بحسب StarkeZigarren؛ طُوّرت بالتعاون مع Hugo Cesar، مالك المصنع، وRalph Montero، master blender لدى Alec Bradley، بحسب Wolfertz."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── American Caribbean Cigars ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('American Caribbean Cigars',
        'nicaragua',
        'Non précisée — Emiliano Lagos, Estelí',
        'Usine propre — Tabacalera American Caribbean, Estelí (Nicaragua)',
        'cigar-coop.com « Feature Story: Spotlight on American Caribbean Cigars, Vintage Rock-a-Feller Cigar Group, and The Traveler at the 2018 IPCPR » (2018-08 : marques propres La Rosa de Sandiego [2015], The Bouncer, Bella Mundo — cape brésilienne dite Cubra, sous-cape Sumatra, tripe criollo nicaraguayen —, clients sous contrat Gurkha, Toraño, Leccia Tobacco et Vintage Rock-A-Feller Cigar Group ; The Traveler d''Emiliano Lagos, lancée en 2017 en Europe puis aux États-Unis, vitolas nommées d''après des aéroports) ; halfwheel.com « American Caribbean Cigars Adding The Bouncer at IPCPR 2018 » (2018 : lancement de The Bouncer, cape San Andrés du Mexique, fabrique d''Estelí, Nicaragua) ; halfwheel.com « PCA 2021: American Caribbean Cigars » (2021 : stand renouvelé et éditions limitées, dernière trace de salon connue) ; cigarworld.de « The Bouncer » et « El Copey » (consulté 2026-09 : composition des deux lignes, roulage dominicain d''El Copey) ; hacico.de « El Copey » (confirme le roulage dominicain, sans nommer de fabrique) ; neptunecigar.com, via recherche, « Interview with Daniel Guerrero of El Viejo Continente Cigars » (Daniel Guerrero, tabacologue barcelonais, à l''origine de la ligne avec Emiliano Lagos ; sous-lignes Mare Nostrum et The Circus, roulées au Nicaragua) ; cigarjournal.com « The Traveler Cigars Honors Maradona » (Maradona Tribute : collaboration avec Diego Maradona, tripe Nicaragua/Honduras, sous-cape San Andrés, cape équatorienne, 500 boîtes) ; cigarjournal.com « Gurkha Pulls Out of American Caribbean Cigars Akquisition » et tobaccobusiness.com « Gurkha Cigars Gains Its Own Factory With New Acquisition » (2017 : Gurkha annonce en mai vouloir racheter la fabrique puis renonce pour construire la sienne, American Caribbean reste indépendante et continue de rouler pour Gurkha)',
        '["Toraño","Leccia Tobacco","Vintage Rock-A-Feller Cigar Group"]',
        'Emiliano Lagos possède la Tabacalera American Caribbean, à Estelí, qui roulait déjà pour des tiers avant de développer ses propres marques. Gurkha annonce en mai 2017 vouloir l''acquérir, puis y renonce la même année pour construire sa propre usine (Tobacco Business) ; American Caribbean reste indépendante et continue de rouler pour Gurkha. En 2018, selon Cigar Coop, elle roule aussi pour Toraño, Leccia Tobacco et le Vintage Rock-A-Feller Cigar Group.

La maison lance sa première marque propre, La Rosa de Sandiego, en 2015. Suivent The Bouncer et Bella Mundo, présentées à l''IPCPR 2018 : la première en cape San Andrés du Mexique sur tripe nicaraguayenne d''Estelí, Jalapa et Ometepe, la seconde en cape brésilienne dite Cubra, sous-cape Sumatra et tripe criollo du Nicaragua. El Viejo Continente naît d''une rencontre entre Emiliano Lagos et Daniel Guerrero, tabacologue barcelonais dont la famille tenait un bureau de tabac ; la gamme se décline en plusieurs habillages et compte deux lignes sœurs, Mare Nostrum et The Circus.

Lagos roule aussi sa marque personnelle, The Traveler, lancée en 2017 en Europe puis aux États-Unis, aux vitolas nommées d''après des aéroports internationaux, en versions naturelle et maduro. Elle porte l''édition Maradona Tribute, cinq cents boîtes en hommage à Diego Maradona, tripe nicaraguayenne et hondurienne, sous-cape San Andrés et cape équatorienne. Seule ligne roulée hors du Nicaragua, El Copey se fait à la main en République dominicaine, dans une fabrique qu''aucune source consultée ne nomme. La présence de la maison en salon est attestée jusqu''au PCA 2021 (halfwheel) ; The Bouncer et El Copey restent au catalogue de Cigarworld.de en 2026.',
        '[{"name":"The Bouncer","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Cape San Andrés du Mexique et sous-cape Sumatra sur tripe nicaraguayenne d''Estelí, Jalapa et Ometepe, présentée à l''IPCPR 2018, selon cigarworld.de et halfwheel."},{"name":"El Viejo Continente","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Née de la rencontre entre Emiliano Lagos et le tabacologue barcelonais Daniel Guerrero, déclinée en plusieurs habillages (Classic, Maduro, Edición Estelí) sans cape unique clairement établie, et en deux lignes sœurs, Mare Nostrum et The Circus, selon Neptune Cigars."},{"name":"Maradona Tribute","color":"#A0522D","force":null,"wrapper":"Équateur","vitolas":[],"story":"Édition de cinq cents boîtes en hommage à Diego Maradona, tripe nicaraguayenne et hondurienne et sous-cape San Andrés sous la cape équatorienne."},{"name":"The Traveler","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Marque personnelle d''Emiliano Lagos lancée en 2017 en Europe puis aux États-Unis, vitolas nommées d''après des aéroports internationaux, en versions naturelle et maduro, selon Cigar Coop."},{"name":"El Copey","color":"#C9A96E","force":null,"wrapper":"Connecticut (Équateur)","vitolas":[],"story":"Seule ligne roulée hors du Nicaragua : faite à la main en République dominicaine, dans une fabrique qu''aucune source consultée ne nomme (cigarworld.de, hacico.de) ; cape Connecticut d''Équateur sur sous-cape et tripe dominicaines, selon cigarworld.de."},{"name":"Bella Mundo","color":"#6B4226","force":null,"wrapper":"Brésil (Cubra)","vitolas":[],"story":"Cape brésilienne dite Cubra, sous-cape Sumatra et tripe criollo du Nicaragua, présentée à l''IPCPR 2018, selon Cigar Coop."}]',
        'Emiliano Lagos owns the Tabacalera American Caribbean, in Estelí, which was already rolling for third parties before it developed its own brands. Gurkha announced in May 2017 that it wanted to acquire it, then gave up the same year to build its own factory (Tobacco Business); American Caribbean remained independent and continues to roll for Gurkha. In 2018, according to Cigar Coop, it also rolled for Toraño, Leccia Tobacco and the Vintage Rock-A-Feller Cigar Group.

The company launched its first own brand, La Rosa de Sandiego, in 2015. The Bouncer and Bella Mundo followed, presented at the IPCPR 2018: the first under a Mexican San Andrés wrapper on Nicaraguan filler from Estelí, Jalapa and Ometepe, the second under a Brazilian wrapper known as Cubra, a Sumatra binder and Nicaraguan criollo filler. El Viejo Continente was born of a meeting between Emiliano Lagos and Daniel Guerrero, a Barcelona-based tobacco specialist whose family ran a tobacconist''s shop; the range comes in several dress styles and includes two sister lines, Mare Nostrum and The Circus.

Lagos also rolls his personal brand, The Traveler, launched in 2017 in Europe and then in the United States, with vitolas named after international airports, in natural and maduro versions. It carries the Maradona Tribute edition, five hundred boxes in tribute to Diego Maradona, with Nicaraguan and Honduran filler, a San Andrés binder and an Ecuadorian wrapper. The only line rolled outside Nicaragua, El Copey is hand-made in the Dominican Republic, at a factory no source consulted names. The company''s presence at trade shows is documented up to the PCA 2021 (halfwheel); The Bouncer and El Copey remain in Cigarworld.de''s catalogue in 2026.',
        '[{"name":"The Bouncer","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Mexican San Andrés wrapper and Sumatra binder over Nicaraguan filler from Estelí, Jalapa and Ometepe, presented at the IPCPR 2018, according to cigarworld.de and halfwheel."},{"name":"El Viejo Continente","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Born of the meeting between Emiliano Lagos and Barcelona-based tobacco specialist Daniel Guerrero, it comes in several dress styles (Classic, Maduro, Edición Estelí) without one clearly established wrapper, and in two sister lines, Mare Nostrum and The Circus, according to Neptune Cigars."},{"name":"Maradona Tribute","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"A five-hundred-box edition in tribute to Diego Maradona, with Nicaraguan and Honduran filler and a San Andrés binder under the Ecuadorian wrapper."},{"name":"The Traveler","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Emiliano Lagos''s personal brand, launched in 2017 in Europe and then in the United States, with vitolas named after international airports, in natural and maduro versions, according to Cigar Coop."},{"name":"El Copey","color":"#C9A96E","force":null,"wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"The only line rolled outside Nicaragua: hand-made in the Dominican Republic, at a factory no source consulted names (cigarworld.de, hacico.de); an Ecuadorian Connecticut wrapper over Dominican binder and filler, according to cigarworld.de."},{"name":"Bella Mundo","color":"#6B4226","force":null,"wrapper":"Brazil (Cubra)","vitolas":[],"story":"Brazilian wrapper known as Cubra, Sumatra binder and Nicaraguan criollo filler, presented at the IPCPR 2018, according to Cigar Coop."}]',
        'Emiliano Lagos posee la Tabacalera American Caribbean, en Estelí, que ya elaboraba para terceros antes de desarrollar sus propias marcas. Gurkha anuncia en mayo de 2017 su intención de adquirirla, y renuncia ese mismo año para construir su propia fábrica (Tobacco Business); American Caribbean sigue siendo independiente y continúa elaborando para Gurkha. En 2018, según Cigar Coop, también elabora para Toraño, Leccia Tobacco y el Vintage Rock-A-Feller Cigar Group.

La casa lanza su primera marca propia, La Rosa de Sandiego, en 2015. Le siguen The Bouncer y Bella Mundo, presentadas en el IPCPR 2018: la primera con capa San Andrés de México sobre tripa nicaragüense de Estelí, Jalapa y Ometepe, la segunda con capa brasileña llamada Cubra, capote de Sumatra y tripa criollo de Nicaragua. El Viejo Continente nace de un encuentro entre Emiliano Lagos y Daniel Guerrero, tabacólogo barcelonés cuya familia tenía un estanco; la gama se presenta en varios vitolados y cuenta con dos líneas hermanas, Mare Nostrum y The Circus.

Lagos elabora también su marca personal, The Traveler, lanzada en 2017 en Europa y después en Estados Unidos, con vitolas bautizadas con nombres de aeropuertos internacionales, en versiones natural y maduro. Incluye la edición Maradona Tribute, quinientas cajas en homenaje a Diego Maradona, con tripa nicaragüense y hondureña, capote San Andrés y capa ecuatoriana. Única línea elaborada fuera de Nicaragua, El Copey se hace a mano en República Dominicana, en una fábrica que ninguna fuente consultada nombra. La presencia de la casa en ferias está documentada hasta el PCA 2021 (halfwheel); The Bouncer y El Copey siguen en el catálogo de Cigarworld.de en 2026.',
        '[{"name":"The Bouncer","color":"#4A3728","force":null,"wrapper":"San Andrés (México)","vitolas":[],"story":"Capa San Andrés de México y capote de Sumatra sobre tripa nicaragüense de Estelí, Jalapa y Ometepe, presentada en el IPCPR 2018, según cigarworld.de y halfwheel."},{"name":"El Viejo Continente","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Nacida del encuentro entre Emiliano Lagos y el tabacólogo barcelonés Daniel Guerrero, se presenta en varios vitolados (Classic, Maduro, Edición Estelí) sin una capa única claramente establecida, y en dos líneas hermanas, Mare Nostrum y The Circus, según Neptune Cigars."},{"name":"Maradona Tribute","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Edición de quinientas cajas en homenaje a Diego Maradona, con tripa nicaragüense y hondureña y capote San Andrés bajo la capa ecuatoriana."},{"name":"The Traveler","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Marca personal de Emiliano Lagos lanzada en 2017 en Europa y después en Estados Unidos, con vitolas bautizadas con nombres de aeropuertos internacionales, en versiones natural y maduro, según Cigar Coop."},{"name":"El Copey","color":"#C9A96E","force":null,"wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Única línea elaborada fuera de Nicaragua: hecha a mano en República Dominicana, en una fábrica que ninguna fuente consultada nombra (cigarworld.de, hacico.de); capa Connecticut de Ecuador sobre capote y tripa dominicanos, según cigarworld.de."},{"name":"Bella Mundo","color":"#6B4226","force":null,"wrapper":"Brasil (Cubra)","vitolas":[],"story":"Capa brasileña llamada Cubra, capote de Sumatra y tripa criollo de Nicaragua, presentada en el IPCPR 2018, según Cigar Coop."}]',
        'Emiliano Lagos besitzt die Tabacalera American Caribbean in Estelí, die bereits für Dritte rollte, bevor sie eigene Marken entwickelte. Gurkha kündigt im Mai 2017 an, sie übernehmen zu wollen, verzichtet dann aber im selben Jahr darauf, um eine eigene Fabrik zu bauen (Tobacco Business); American Caribbean bleibt unabhängig und rollt weiterhin für Gurkha. 2018 rollt sie laut Cigar Coop auch für Toraño, Leccia Tobacco und die Vintage Rock-A-Feller Cigar Group.

Das Haus lanciert 2015 seine erste eigene Marke, La Rosa de Sandiego. Es folgen The Bouncer und Bella Mundo, die 2018 auf der IPCPR vorgestellt werden: die erste unter mexikanischem San-Andrés-Deckblatt auf nicaraguanischer Einlage aus Estelí, Jalapa und Ometepe, die zweite unter brasilianischem, als Cubra bezeichnetem Deckblatt, mit Sumatra-Umblatt und nicaraguanischer Criollo-Einlage. El Viejo Continente entsteht aus einer Begegnung zwischen Emiliano Lagos und Daniel Guerrero, einem Tabakexperten aus Barcelona, dessen Familie einen Tabakladen führte; die Reihe gibt es in mehreren Aufmachungen und umfasst zwei Schwesterlinien, Mare Nostrum und The Circus.

Lagos rollt außerdem seine persönliche Marke, The Traveler, die 2017 in Europa und anschließend in den Vereinigten Staaten lanciert wird, mit Vitolen, die nach internationalen Flughäfen benannt sind, in natürlicher und Maduro-Version. Dazu gehört die Edition Maradona Tribute, fünfhundert Kisten zu Ehren von Diego Maradona, mit nicaraguanischer und honduranischer Einlage, San-Andrés-Umblatt und ecuadorianischem Deckblatt. El Copey, die einzige außerhalb Nicaraguas gerollte Linie, wird von Hand in der Dominikanischen Republik gefertigt, in einer Fabrik, die keine der konsultierten Quellen nennt. Die Präsenz des Hauses auf Messen ist bis zur PCA 2021 belegt (halfwheel); The Bouncer und El Copey befinden sich 2026 weiterhin im Katalog von Cigarworld.de.',
        '[{"name":"The Bouncer","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Mexikanisches San-Andrés-Deckblatt und Sumatra-Umblatt über nicaraguanischer Einlage aus Estelí, Jalapa und Ometepe, 2018 auf der IPCPR vorgestellt, laut cigarworld.de und halfwheel."},{"name":"El Viejo Continente","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Entstanden aus der Begegnung zwischen Emiliano Lagos und dem Barceloner Tabakexperten Daniel Guerrero, gibt es sie in mehreren Aufmachungen (Classic, Maduro, Edición Estelí) ohne ein klar festgelegtes einheitliches Deckblatt, sowie in zwei Schwesterlinien, Mare Nostrum und The Circus, laut Neptune Cigars."},{"name":"Maradona Tribute","color":"#A0522D","force":null,"wrapper":"Ecuador","vitolas":[],"story":"Eine Edition von fünfhundert Kisten zu Ehren von Diego Maradona, mit nicaraguanischer und honduranischer Einlage und San-Andrés-Umblatt unter dem ecuadorianischen Deckblatt."},{"name":"The Traveler","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Persönliche Marke von Emiliano Lagos, 2017 in Europa und anschließend in den Vereinigten Staaten lanciert, mit Vitolen, die nach internationalen Flughäfen benannt sind, in natürlicher und Maduro-Version, laut Cigar Coop."},{"name":"El Copey","color":"#C9A96E","force":null,"wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Einzige Linie, die außerhalb Nicaraguas gerollt wird: handgefertigt in der Dominikanischen Republik, in einer Fabrik, die keine der konsultierten Quellen nennt (cigarworld.de, hacico.de); ecuadorianisches Connecticut-Deckblatt über dominikanischem Umblatt und dominikanischer Einlage, laut cigarworld.de."},{"name":"Bella Mundo","color":"#6B4226","force":null,"wrapper":"Brasilien (Cubra)","vitolas":[],"story":"Brasilianisches, als Cubra bezeichnetes Deckblatt, Sumatra-Umblatt und nicaraguanische Criollo-Einlage, 2018 auf der IPCPR vorgestellt, laut Cigar Coop."}]',
        'Emiliano Lagos拥有位于Estelí的Tabacalera American Caribbean工厂，该厂在打造自有品牌之前已在为第三方代工。Gurkha于2017年5月宣布有意收购该厂，但同年放弃，转而自建工厂（据Tobacco Business）；American Caribbean得以保持独立，并继续为Gurkha代工。据Cigar Coop称，2018年该厂还为Toraño、Leccia Tobacco以及Vintage Rock-A-Feller Cigar Group代工。

该品牌于2015年推出首个自有品牌La Rosa de Sandiego。随后推出的The Bouncer与Bella Mundo于2018年IPCPR展会亮相：前者采用墨西哥San Andrés茄衣，茄芯为产自Estelí、Jalapa与Ometepe的尼加拉瓜烟叶；后者采用被称为Cubra的巴西茄衣、Sumatra茄套及尼加拉瓜criollo茄芯。El Viejo Continente诞生于Emiliano Lagos与Daniel Guerrero的相识——后者是一位巴塞罗那烟草专家，家族曾经营一家烟草店；该系列推出多种外观版本，并包含两条姊妹系列Mare Nostrum与The Circus。

Lagos还卷制他个人的品牌The Traveler，于2017年先在欧洲、后在美国推出，雪茄规格以国际机场命名，分天然与maduro两个版本。该系列包含Maradona Tribute版本，共五百箱，以纪念Diego Maradona，茄芯为尼加拉瓜与洪都拉斯烟叶，茄套为San Andrés，茄衣为厄瓜多尔烟叶。唯一一条在尼加拉瓜境外卷制的系列El Copey，在多米尼加共和国手工制作，所查阅的资料均未指明工厂名称。该品牌参展的记录一直延续至2021年PCA展会（据halfwheel）；截至2026年，The Bouncer与El Copey仍列于Cigarworld.de的目录中。',
        '[{"name":"The Bouncer","color":"#4A3728","force":null,"wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"墨西哥San Andrés茄衣与Sumatra茄套，搭配产自Estelí、Jalapa与Ometepe的尼加拉瓜茄芯，于2018年IPCPR展会推出，据cigarworld.de与halfwheel称。"},{"name":"El Viejo Continente","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"该系列诞生于Emiliano Lagos与巴塞罗那烟草专家Daniel Guerrero的相识，推出多种外观版本（Classic、Maduro、Edición Estelí），并无明确统一的茄衣，另有两条姊妹系列Mare Nostrum与The Circus，据Neptune Cigars称。"},{"name":"Maradona Tribute","color":"#A0522D","force":null,"wrapper":"厄瓜多尔","vitolas":[],"story":"限量五百箱，以纪念Diego Maradona，茄芯为尼加拉瓜与洪都拉斯烟叶，厄瓜多尔茄衣之下衬有San Andrés茄套。"},{"name":"The Traveler","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"Emiliano Lagos的个人品牌，2017年先在欧洲、后在美国推出，雪茄规格以国际机场命名，分天然与maduro两个版本，据Cigar Coop称。"},{"name":"El Copey","color":"#C9A96E","force":null,"wrapper":"Connecticut（厄瓜多尔）","vitolas":[],"story":"唯一一条在尼加拉瓜境外卷制的系列：在多米尼加共和国手工制作，所查阅的资料均未指明工厂名称（cigarworld.de、hacico.de）；据cigarworld.de称，采用厄瓜多尔Connecticut茄衣，搭配多米尼加茄套与茄芯。"},{"name":"Bella Mundo","color":"#6B4226","force":null,"wrapper":"巴西（Cubra）","vitolas":[],"story":"被称为Cubra的巴西茄衣，Sumatra茄套，以及尼加拉瓜criollo茄芯，于2018年IPCPR展会推出，据Cigar Coop称。"}]',
        'يمتلك Emiliano Lagos مصنع Tabacalera American Caribbean في Estelí، وكان هذا المصنع يلفّ سيجارًا لأطراف أخرى قبل أن يطوّر علاماته الخاصة. وأعلنت Gurkha في مايو 2017 عزمها الاستحواذ عليه، ثم تراجعت في العام نفسه لبناء مصنعها الخاص (بحسب Tobacco Business)؛ وبقيت American Caribbean مستقلة واستمرت في اللف لصالح Gurkha. وفي عام 2018، بحسب Cigar Coop، كانت تلفّ أيضًا لصالح Toraño وLeccia Tobacco وVintage Rock-A-Feller Cigar Group.

أطلقت الشركة علامتها الخاصة الأولى، La Rosa de Sandiego، عام 2015. وتلتها The Bouncer وBella Mundo، اللتان قُدِّمتا في معرض IPCPR عام 2018: الأولى بغلاف San Andrés مكسيكي فوق حشوة نيكاراغوية من Estelí وJalapa وOmetepe، والثانية بغلاف برازيلي يُعرف باسم Cubra، ورباط من Sumatra وحشوة criollo نيكاراغوية. ووُلدت El Viejo Continente من لقاء بين Emiliano Lagos وDaniel Guerrero، خبير التبغ من برشلونة الذي كانت عائلته تدير محل تبغ؛ وتُقدَّم التشكيلة بعدة أشكال وتضم سلسلتين شقيقتين، Mare Nostrum وThe Circus.

ويلفّ Lagos أيضًا علامته الشخصية، The Traveler، التي أُطلقت عام 2017 في أوروبا ثم في الولايات المتحدة، بمقاسات سُمّيت بأسماء مطارات دولية، بنسختين طبيعية وmaduro. وتضم إصدار Maradona Tribute، خمسمائة صندوق تكريمًا لـ Diego Maradona، بحشوة نيكاراغوية وهندوراسية ورباط San Andrés وغلاف إكوادوري. وEl Copey، السلسلة الوحيدة التي تُلف خارج نيكاراغوا، تُصنع يدويًا في جمهورية الدومينيكان، في مصنع لم تُسمِّه أي من المصادر المُطالَعة. وحضور الشركة في المعارض موثَّق حتى معرض PCA لعام 2021 (بحسب halfwheel)؛ ولا تزال The Bouncer وEl Copey ضمن قائمة Cigarworld.de حتى عام 2026.',
        '[{"name":"The Bouncer","color":"#4A3728","force":null,"wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"غلاف San Andrés مكسيكي ورباط من Sumatra فوق حشوة نيكاراغوية من Estelí وJalapa وOmetepe، قُدِّمت في معرض IPCPR عام 2018، بحسب cigarworld.de وhalfwheel."},{"name":"El Viejo Continente","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"وُلدت من لقاء بين Emiliano Lagos وخبير التبغ البرشلوني Daniel Guerrero، وتُقدَّم بعدة أشكال (Classic وMaduro وEdición Estelí) دون غلاف واحد محدَّد بوضوح، وضمن سلسلتين شقيقتين، Mare Nostrum وThe Circus، بحسب Neptune Cigars."},{"name":"Maradona Tribute","color":"#A0522D","force":null,"wrapper":"الإكوادور","vitolas":[],"story":"إصدار من خمسمائة صندوق تكريمًا لـ Diego Maradona، بحشوة نيكاراغوية وهندوراسية ورباط San Andrés تحت الغلاف الإكوادوري."},{"name":"The Traveler","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"علامة شخصية لـ Emiliano Lagos، أُطلقت عام 2017 في أوروبا ثم في الولايات المتحدة، بمقاسات سُمّيت بأسماء مطارات دولية، بنسختين طبيعية وmaduro، بحسب Cigar Coop."},{"name":"El Copey","color":"#C9A96E","force":null,"wrapper":"Connecticut (الإكوادور)","vitolas":[],"story":"السلسلة الوحيدة التي تُلف خارج نيكاراغوا: تُصنع يدويًا في جمهورية الدومينيكان، في مصنع لم تُسمِّه أي من المصادر المُطالَعة (cigarworld.de، hacico.de)؛ بغلاف Connecticut إكوادوري فوق رباط وحشوة دومينيكانيين، بحسب cigarworld.de."},{"name":"Bella Mundo","color":"#6B4226","force":null,"wrapper":"البرازيل (Cubra)","vitolas":[],"story":"غلاف برازيلي يُعرف باسم Cubra، ورباط من Sumatra وحشوة criollo نيكاراغوية، قُدِّمت في معرض IPCPR عام 2018، بحسب Cigar Coop."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Darier & Cleef ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Darier & Cleef',
        'panama',
        '1881 selon des détaillants — Darier, van Cleef',
        'Usine propre — Tabacalera Darier & Cleef S.A., ville non précisée (Panama)',
        'noblego.de « Colón Zigarren » (non daté : Tabacalera Darier & Cleef fondée en 1881 par Alfons Darier et Jean van Cleef, monopole revendiqué du tabac panaméen d''origine) ; noblego.de « Cruzero de Panamá Zigarren » (non daté : une des plus anciennes marques d''Amérique centrale, origine revendiquée à 1881, relancée vers 2000, formats Sportivos ajoutés en 2010) ; cigarworld.de « Colón Vintage 2001 » (non daté : lancée le 16 novembre 2007, tabac vieilli trois à quatre ans puis six mois en cabinet après roulage) ; smokersplanet.de « Darier & Cleef: eine Empfehlung aus Mittelamerika » (en allemand, non daté : production interrompue à plusieurs reprises entre 1903 et 1999 ; monopole et statut de premier exportateur de purs du pays revendiqués) ; cigar-wiki.com « Cruzero » (non daté : roulage entièrement à la main, tripe longue, maître-assembleur Ramón) ; newsroompanama.com « Joyas de Panamá Cigars: History of Cigars in Panama » (14 septembre 2025 : la presse panaméenne dit Joyas de Panamá, fondée en février 1986, première fabrique de cigares permanente du pays)',
        NULL,
        'Des détaillants allemands (noblego.de, smokersplanet.de) disent la Tabacalera Darier & Cleef fondée en 1881 par Alfons Darier et Jean van Cleef ; smokersplanet.de ajoute que sa production s''est interrompue à plusieurs reprises entre 1903 et 1999. La presse panaméenne (Newsroom Panama, 2025) tient pour sa part Joyas de Panamá, fondée en février 1986, pour la première fabrique de cigares permanente du pays : les deux récits divergent.

Selon noblego.de, la fabrique roule entièrement à la main, en tripe longue, un tabac panaméen vieilli trois à quatre ans avant roulage. Les sources consultées nomment la province du tabac, le Chiriquí, mais aucune ne dit la ville de l''atelier.

Le catalogue compte deux lignes. Colón se décline en série Vintage 2001, lancée le 16 novembre 2007 et vieillie encore six mois en cabinet après roulage, et en série Especiales ; cape, sous-cape et tripe sont entièrement panaméennes, selon cigarworld.de. Cruzero de Panamá, dont l''origine est revendiquée à 1881, est relancée vers 2000 sous la conduite du maître-assembleur Ramón et complétée en 2010 par des formats Sportivos de gros calibre, selon noblego.de et cigar-wiki.com.',
        '[{"name":"Colón","color":"#A0522D","force":null,"wrapper":"Panama","vitolas":[],"story":"Série Vintage 2001 lancée le 16 novembre 2007, vieillie encore six mois en cabinet après roulage, aux côtés de la série Especiales, plus ancienne ; cape, sous-cape et tripe entièrement panaméennes, selon cigarworld.de et noblego.de."},{"name":"Cruzero de Panamá","color":"#8B5A2B","force":null,"wrapper":"Panama","vitolas":[],"story":"Origine revendiquée à 1881 ; relancée vers 2000 sous la conduite du maître-assembleur Ramón et complétée en 2010 par des formats Sportivos de gros calibre, selon noblego.de et cigar-wiki.com."}]',
        'German retailers (noblego.de, smokersplanet.de) say the Tabacalera Darier & Cleef was founded in 1881 by Alfons Darier and Jean van Cleef; smokersplanet.de adds that its production was interrupted several times between 1903 and 1999. The Panamanian press (Newsroom Panama, 2025), for its part, holds Joyas de Panamá, founded in February 1986, to be the country''s first permanent cigar factory: the two accounts diverge.

According to noblego.de, the factory rolls entirely by hand, in long filler, a Panamanian tobacco aged three to four years before rolling. The sources consulted name the tobacco province, Chiriquí, but none states the town where the workshop stands.

The range comprises two lines. Colón comes in a Vintage 2001 series, launched on 16 November 2007 and aged a further six months in cabinet after rolling, and an Especiales series; wrapper, binder and filler are entirely Panamanian, according to cigarworld.de. Cruzero de Panamá, whose origin is claimed to be 1881, was relaunched around 2000 under master blender Ramón and complemented in 2010 by large-ring-gauge Sportivos formats, according to noblego.de and cigar-wiki.com.',
        '[{"name":"Colón","color":"#A0522D","force":null,"wrapper":"Panama","vitolas":[],"story":"Vintage 2001 series, launched on 16 November 2007 and aged a further six months in cabinet after rolling, alongside the older Especiales series; wrapper, binder and filler entirely Panamanian, according to cigarworld.de and noblego.de."},{"name":"Cruzero de Panamá","color":"#8B5A2B","force":null,"wrapper":"Panama","vitolas":[],"story":"Origin claimed to be 1881; relaunched around 2000 under master blender Ramón and complemented in 2010 by large-ring-gauge Sportivos formats, according to noblego.de and cigar-wiki.com."}]',
        'Detallistas alemanes (noblego.de, smokersplanet.de) sitúan la fundación de la Tabacalera Darier & Cleef en 1881, por Alfons Darier y Jean van Cleef; smokersplanet.de añade que su producción se interrumpió varias veces entre 1903 y 1999. La prensa panameña (Newsroom Panama, 2025), por su parte, considera a Joyas de Panamá, fundada en febrero de 1986, la primera fábrica de puros permanente del país: los dos relatos divergen.

Según noblego.de, la fábrica elabora enteramente a mano, en tripa larga, un tabaco panameño añejado de tres a cuatro años antes del torcido. Las fuentes consultadas nombran la provincia del tabaco, Chiriquí, pero ninguna indica la ciudad del taller.

El catálogo cuenta con dos líneas. Colón se presenta en la serie Vintage 2001, lanzada el 16 de noviembre de 2007 y añejada otros seis meses en cabinet tras el torcido, y en la serie Especiales; capa, capote y tripa son enteramente panameños, según cigarworld.de. Cruzero de Panamá, cuyo origen se reivindica en 1881, se relanza hacia 2000 bajo la dirección del maestro mezclador Ramón y se completa en 2010 con formatos Sportivos de gran calibre, según noblego.de y cigar-wiki.com.',
        '[{"name":"Colón","color":"#A0522D","force":null,"wrapper":"Panamá","vitolas":[],"story":"Serie Vintage 2001, lanzada el 16 de noviembre de 2007 y añejada otros seis meses en cabinet tras el torcido, junto a la serie Especiales, más antigua; capa, capote y tripa enteramente panameños, según cigarworld.de y noblego.de."},{"name":"Cruzero de Panamá","color":"#8B5A2B","force":null,"wrapper":"Panamá","vitolas":[],"story":"Origen reivindicado en 1881; relanzada hacia 2000 bajo la dirección del maestro mezclador Ramón y completada en 2010 con formatos Sportivos de gran calibre, según noblego.de y cigar-wiki.com."}]',
        'Deutsche Händler (noblego.de, smokersplanet.de) geben an, die Tabacalera Darier & Cleef sei 1881 von Alfons Darier und Jean van Cleef gegründet worden; smokersplanet.de fügt hinzu, dass ihre Produktion zwischen 1903 und 1999 mehrfach unterbrochen war. Die panamaische Presse (Newsroom Panama, 2025) hält dagegen Joyas de Panamá, gegründet im Februar 1986, für die erste dauerhafte Zigarrenfabrik des Landes: Die beiden Darstellungen widersprechen sich.

Laut noblego.de rollt die Fabrik vollständig von Hand, als Long Filler, einen panamaischen Tabak, der vor dem Rollen drei bis vier Jahre gereift ist. Die konsultierten Quellen nennen die Tabakprovinz Chiriquí, doch keine nennt die Stadt der Werkstatt.

Das Sortiment umfasst zwei Linien. Colón gibt es in der Serie Vintage 2001, die am 16. November 2007 lanciert wurde und nach dem Rollen weitere sechs Monate im Cabinet reift, sowie in der Serie Especiales; Deckblatt, Umblatt und Einlage sind laut cigarworld.de vollständig panamaisch. Cruzero de Panamá, deren Ursprung auf 1881 zurückgeführt wird, wird um das Jahr 2000 unter der Leitung von Master Blender Ramón neu aufgelegt und 2010 um großkalibrige Sportivos-Formate ergänzt, laut noblego.de und cigar-wiki.com.',
        '[{"name":"Colón","color":"#A0522D","force":null,"wrapper":"Panama","vitolas":[],"story":"Serie Vintage 2001, lanciert am 16. November 2007 und nach dem Rollen weitere sechs Monate im Cabinet gereift, neben der älteren Serie Especiales; Deckblatt, Umblatt und Einlage vollständig panamaisch, laut cigarworld.de und noblego.de."},{"name":"Cruzero de Panamá","color":"#8B5A2B","force":null,"wrapper":"Panama","vitolas":[],"story":"Ursprung auf 1881 zurückgeführt; um das Jahr 2000 unter der Leitung von Master Blender Ramón neu aufgelegt und 2010 um großkalibrige Sportivos-Formate ergänzt, laut noblego.de und cigar-wiki.com."}]',
        '德国经销商（noblego.de、smokersplanet.de）称Tabacalera Darier & Cleef由Alfons Darier与Jean van Cleef于1881年创立；smokersplanet.de补充说，该厂的生产在1903年至1999年间数次中断。而巴拿马媒体（Newsroom Panama，2025年）则认为，1986年2月创立的Joyas de Panamá才是该国首家持续经营的雪茄工厂：两种说法互相矛盾。

据noblego.de称，该厂完全以手工卷制长茄芯雪茄，所用巴拿马烟叶在卷制前需陈化三至四年。所查阅的资料均提及产烟省份Chiriquí，但均未说明工坊所在城市。

产品目录中共有两个系列。Colón分为Vintage 2001系列——于2007年11月16日推出，卷制后再于雪茄柜中陈化六个月——以及历史更久的Especiales系列；据cigarworld.de称，茄衣、茄套与茄芯均产自巴拿马。Cruzero de Panamá据称源起于1881年，于2000年前后在首席调配师Ramón主导下重新推出，并于2010年增加了大环径的Sportivos规格，据noblego.de与cigar-wiki.com称。',
        '[{"name":"Colón","color":"#A0522D","force":null,"wrapper":"巴拿马","vitolas":[],"story":"Vintage 2001系列，于2007年11月16日推出，卷制后再陈化六个月于雪茄柜中，与历史更久的Especiales系列并列；据cigarworld.de与noblego.de称，茄衣、茄套与茄芯均产自巴拿马。"},{"name":"Cruzero de Panamá","color":"#8B5A2B","force":null,"wrapper":"巴拿马","vitolas":[],"story":"据称起源于1881年；于2000年前后在首席调配师Ramón主导下重新推出，并于2010年增加了大环径的Sportivos规格，据noblego.de与cigar-wiki.com称。"}]',
        'يقول تجار تجزئة ألمان (noblego.de وsmokersplanet.de) إن Tabacalera Darier & Cleef تأسست عام 1881 على يد Alfons Darier وJean van Cleef؛ وتضيف smokersplanet.de أن إنتاجها توقف مرات عدة بين عامي 1903 و1999. أما الصحافة البنمية (Newsroom Panama، 2025) فتعتبر أن Joyas de Panamá، المؤسَّسة في فبراير 1986، هي أول مصنع سيجار دائم في البلاد: والروايتان متباينتان.

بحسب noblego.de، يلفّ المصنع سيجاره كله يدويًا وبحشوة طويلة، من تبغ بنمي يُعتَّق ثلاث إلى أربع سنوات قبل اللف. وتذكر المصادر المُطالَعة إقليم التبغ، Chiriquí، لكن لا يذكر أي منها المدينة التي تقع فيها الورشة.

تضم التشكيلة سلسلتين. تُقدَّم Colón في سلسلة Vintage 2001، التي أُطلقت في 16 نوفمبر 2007 وتُعتَّق ستة شهور إضافية في الخزانة بعد اللف، وفي سلسلة Especiales؛ والغلاف والرباط والحشوة كلها بنمية بالكامل، بحسب cigarworld.de. أما Cruzero de Panamá، التي يُنسب أصلها إلى عام 1881، فقد أُعيد إطلاقها نحو عام 2000 بإشراف كبير خبراء المزج Ramón، وأُضيفت إليها عام 2010 مقاسات Sportivos ذات القطر الكبير، بحسب noblego.de وcigar-wiki.com.',
        '[{"name":"Colón","color":"#A0522D","force":null,"wrapper":"بنما","vitolas":[],"story":"سلسلة Vintage 2001، أُطلقت في 16 نوفمبر 2007 وتُعتَّق ستة شهور إضافية في الخزانة بعد اللف، إلى جانب سلسلة Especiales الأقدم؛ والغلاف والرباط والحشوة كلها بنمية بالكامل، بحسب cigarworld.de وnoblego.de."},{"name":"Cruzero de Panamá","color":"#8B5A2B","force":null,"wrapper":"بنما","vitolas":[],"story":"يُنسب أصلها إلى عام 1881؛ أُعيد إطلاقها نحو عام 2000 بإشراف كبير خبراء المزج Ramón، وأُضيفت إليها عام 2010 مقاسات Sportivos ذات القطر الكبير، بحسب noblego.de وcigar-wiki.com."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Daniel Marshall ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Daniel Marshall',
        'nicaragua',
        '1982 — Daniel Marshall (cigares dès 1995)',
        'Chez Plasencia, Nicaragua (DM Red Label) ; le DM2 était roulé chez Quesada (République dominicaine)',
        'coronacigar.com « Daniel Marshall Red Label » (consulté 2026-09-23 : roulé à la fabrique Plasencia, Nicaragua, 100 % tabac nicaraguayen) ; cigar-coop.com « Cigar Review: Daniel Marshall DM2 Red Label Corona » (2018-04 : DM2 White/Black produits chez Quesada Cigars, République dominicaine) ; danielmarshallshop.com/collections/cigars (consulté 2026-09-23 : catalogue actuel — DM Red Label en plusieurs vitolas, 24KT Golden Cigar, collaboration 38th Anniversary avec Carlos Fuente ; DM2 absent de cette page) ; danielmarshall.com « DM Red Label Cigars » (consulté 2026-09-24 : cape colorado dite super-premium, tabac d''Estelí et de la vallée de Jalapa vieilli cinq ans puis douze mois en boîte, force medium to full, collaboration de développement avec Manuel Quesada et Nestor Plasencia) ; danielmarshall.com « Since 1982 » et « Historical Highlights », via recherche (fondation en 1982 comme maison d''humidors, accords avec Dunhill et Cartier dès la première année, entrée dans le cigare via le Big Smoke de Cigar Aficionado en 1992, premier séjour en République dominicaine pour vieillir le tabac et conditionner le cigare en 1995 — dit la maison).',
        NULL,
        'Daniel Marshall fonde en 1982 une maison de coffrets et d''humidors de luxe — contrats avec Dunhill et Cartier dès la première année, humidors pour Neiman Marcus et le roi Hassan II du Maroc, dit le site de la maison. Il installe son nom dans le cigare à partir de 1992, année où il participe au salon Big Smoke, puis se rend en République dominicaine dès 1995 pour faire vieillir son propre tabac et développer le conditionnement de sa ligne, toujours selon la maison.

Le catalogue actuel se concentre sur le DM Red Label, tabac nicaraguayen d''Estelí et de la vallée de Jalapa vieilli cinq ans puis douze mois de plus en boîte, né d''une collaboration entre Manuel Quesada et Nestor Plasencia et aujourd''hui roulé chez Plasencia, au Nicaragua, selon Corona Cigar et le site officiel. Une ligne antérieure, le DM2, déclinée en trois habillages (White, Black, Red), a été roulée chez Quesada, en République dominicaine ; la presse en rend compte entre 2018 et 2021, et elle ne figure plus en 2026 sur la boutique de la maison.

La boutique de la maison propose aussi un 24KT Golden Cigar, habillé de feuille d''or comestible, et un coffret-humidor 38th Anniversary conçu avec Carlos Fuente.',
        '[{"name":"DM Red Label","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (teinte colorado)","vitolas":[],"story":"Tabac nicaraguayen d''Estelí et de la vallée de Jalapa, vieilli cinq ans puis douze mois de plus après la mise en boîte, né d''une collaboration avec Manuel Quesada et Nestor Plasencia et aujourd''hui roulé chez Plasencia, selon le site officiel et Corona Cigar."},{"name":"DM2","color":"#6B4226","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Trois habillages, White, Black et Red, roulés chez Quesada, en République dominicaine ; la presse en rend compte entre 2018 et 2021 ; absente de la boutique de la maison en 2026."}]',
        'Daniel Marshall founded a luxury case and humidor company in 1982 — contracts with Dunhill and Cartier from the very first year, humidors for Neiman Marcus and King Hassan II of Morocco, says the company''s website. He established his name in cigars from 1992, the year he took part in the Big Smoke trade show, then travelled to the Dominican Republic from 1995 to age his own tobacco and develop the packaging for his line, again according to the company.

The current range centres on the DM Red Label, Nicaraguan tobacco from Estelí and the Jalapa valley aged five years and then a further twelve months in the box, born of a collaboration between Manuel Quesada and Nestor Plasencia and today rolled at Plasencia, in Nicaragua, according to Corona Cigar and the official website. An earlier line, the DM2, offered in three dress styles (White, Black, Red), was rolled at Quesada, in the Dominican Republic; the press covered it between 2018 and 2021, and it no longer appears in 2026 on the company''s shop.

The company''s shop also offers a 24KT Golden Cigar, dressed in edible gold leaf, and a 38th Anniversary humidor case designed with Carlos Fuente.',
        '[{"name":"DM Red Label","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (colorado shade)","vitolas":[],"story":"Nicaraguan tobacco from Estelí and the Jalapa valley, aged five years and then a further twelve months after boxing, born of a collaboration with Manuel Quesada and Nestor Plasencia and today rolled at Plasencia, according to the official website and Corona Cigar."},{"name":"DM2","color":"#6B4226","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Three dress styles, White, Black and Red, rolled at Quesada, in the Dominican Republic; the press covered it between 2018 and 2021; absent from the company''s shop in 2026."}]',
        'Daniel Marshall funda en 1982 una casa de estuches y humidores de lujo —contratos con Dunhill y Cartier desde el primer año, humidores para Neiman Marcus y el rey Hassan II de Marruecos, dice el sitio de la casa—. Instala su nombre en el mundo del puro a partir de 1992, año en que participa en la feria Big Smoke, y viaja después a República Dominicana desde 1995 para añejar su propio tabaco y desarrollar el envasado de su línea, siempre según la casa.

El catálogo actual se centra en el DM Red Label, tabaco nicaragüense de Estelí y del valle de Jalapa añejado cinco años y doce meses más en caja, nacido de una colaboración entre Manuel Quesada y Nestor Plasencia y hoy elaborado en Plasencia, en Nicaragua, según Corona Cigar y el sitio oficial. Una línea anterior, el DM2, presentada en tres vitolados (White, Black, Red), se elaboraba en Quesada, en República Dominicana; la prensa la reseña entre 2018 y 2021, y ya no figura en 2026 en la tienda de la casa.

La tienda de la casa ofrece también un 24KT Golden Cigar, vestido con pan de oro comestible, y un estuche-humidor 38th Anniversary diseñado junto con Carlos Fuente.',
        '[{"name":"DM Red Label","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (tono colorado)","vitolas":[],"story":"Tabaco nicaragüense de Estelí y del valle de Jalapa, añejado cinco años y doce meses más tras el envasado, nacido de una colaboración con Manuel Quesada y Nestor Plasencia y hoy elaborado en Plasencia, según el sitio oficial y Corona Cigar."},{"name":"DM2","color":"#6B4226","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Tres vitolados, White, Black y Red, elaborados en Quesada, en República Dominicana; la prensa la reseña entre 2018 y 2021; ausente de la tienda de la casa en 2026."}]',
        'Daniel Marshall gründet 1982 ein Haus für Luxusetuis und Humidore — Verträge mit Dunhill und Cartier bereits im ersten Jahr, Humidore für Neiman Marcus und König Hassan II. von Marokko, so die Website des Hauses. Ab 1992 etabliert er seinen Namen in der Zigarrenwelt, dem Jahr, in dem er an der Messe Big Smoke teilnimmt, und reist danach ab 1995 in die Dominikanische Republik, um seinen eigenen Tabak reifen zu lassen und die Verpackung seiner Linie zu entwickeln, ebenfalls laut dem Haus.

Das aktuelle Sortiment konzentriert sich auf das DM Red Label, nicaraguanischen Tabak aus Estelí und dem Jalapa-Tal, der fünf Jahre und danach weitere zwölf Monate in der Kiste reift, entstanden aus einer Zusammenarbeit zwischen Manuel Quesada und Nestor Plasencia und heute bei Plasencia in Nicaragua gerollt, laut Corona Cigar und der offiziellen Website. Eine frühere Linie, das DM2, in drei Aufmachungen (White, Black, Red), wurde bei Quesada in der Dominikanischen Republik gerollt; die Presse berichtet darüber zwischen 2018 und 2021, und sie ist 2026 nicht mehr im Shop des Hauses zu finden.

Der Shop des Hauses bietet außerdem eine 24KT Golden Cigar an, mit essbarem Blattgold verziert, sowie ein Etui-Humidor 38th Anniversary, das gemeinsam mit Carlos Fuente entworfen wurde.',
        '[{"name":"DM Red Label","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (Farbton Colorado)","vitolas":[],"story":"Nicaraguanischer Tabak aus Estelí und dem Jalapa-Tal, fünf Jahre gereift und danach weitere zwölf Monate nach dem Verpacken, entstanden aus einer Zusammenarbeit mit Manuel Quesada und Nestor Plasencia und heute bei Plasencia gerollt, laut offizieller Website und Corona Cigar."},{"name":"DM2","color":"#6B4226","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Drei Aufmachungen, White, Black und Red, gerollt bei Quesada in der Dominikanischen Republik; die Presse berichtet darüber zwischen 2018 und 2021; 2026 nicht mehr im Shop des Hauses."}]',
        'Daniel Marshall于1982年创立了一家豪华雪茄盒与雪茄保湿盒公司——据公司官网称，创立首年即与Dunhill和Cartier签约，并为Neiman Marcus及摩洛哥国王Hassan II制作保湿盒。自1992年起，他开始将自己的名字带入雪茄领域，当年他参加了Big Smoke展会，随后自1995年起前往多米尼加共和国，为自己的烟叶陈化并开发其系列的包装方式，同样据该公司称。

目前的产品目录以DM Red Label为核心，采用产自Estelí与Jalapa河谷的尼加拉瓜烟叶，先陈化五年，装盒后再陈化十二个月，该系列源自Manuel Quesada与Nestor Plasencia的合作，如今在尼加拉瓜的Plasencia卷制，据Corona Cigar与官网称。此前的系列DM2分三种外观（White、Black、Red），曾在多米尼加共和国的Quesada卷制；媒体在2018年至2021年间对其有所报道，截至2026年已不再见于该公司的商店。

该公司商店还提供一款以可食用金箔装饰的24KT Golden Cigar，以及一款与Carlos Fuente共同设计的38th Anniversary雪茄盒保湿盒。',
        '[{"name":"DM Red Label","color":"#A0522D","force":"Medium-Full","wrapper":"Habano（colorado色）","vitolas":[],"story":"采用产自Estelí与Jalapa河谷的尼加拉瓜烟叶，先陈化五年，装盒后再陈化十二个月，源自与Manuel Quesada及Nestor Plasencia的合作，如今在Plasencia卷制，据官网与Corona Cigar称。"},{"name":"DM2","color":"#6B4226","force":null,"wrapper":"未公开","vitolas":[],"story":"分White、Black、Red三种外观，产自多米尼加共和国的Quesada；媒体在2018年至2021年间对其有所报道；截至2026年已不见于该公司商店。"}]',
        'أسّس Daniel Marshall عام 1982 دار علب وصناديق ترطيب (هيوميدور) فاخرة — بعقود مع Dunhill وCartier منذ العام الأول، وصناديق ترطيب لـ Neiman Marcus وللملك الحسن الثاني ملك المغرب، بحسب موقع الشركة. ومنذ عام 1992، بدأ اسمه يرتبط بعالم السيجار، وهو العام الذي شارك فيه في معرض Big Smoke، ثم توجّه بعدها ابتداءً من عام 1995 إلى جمهورية الدومينيكان لتعتيق تبغه الخاص وتطوير تغليف سلسلته، دائمًا بحسب الشركة.

تتمحور التشكيلة الحالية حول DM Red Label، وهو تبغ نيكاراغوي من Estelí ووادي Jalapa يُعتَّق خمس سنوات ثم اثني عشر شهرًا إضافيًا داخل العلبة، وُلد من تعاون بين Manuel Quesada وNestor Plasencia ويُلف اليوم لدى Plasencia في نيكاراغوا، بحسب Corona Cigar والموقع الرسمي. أما السلسلة السابقة، DM2، التي قُدِّمت بثلاثة أشكال (White وBlack وRed)، فكانت تُلف لدى Quesada في جمهورية الدومينيكان؛ وتناولتها الصحافة بين عامي 2018 و2021، ولم تعد موجودة في متجر الشركة عام 2026.

يعرض متجر الشركة أيضًا سيجار 24KT Golden Cigar المُغطى بورق ذهب صالح للأكل، وعلبة-هيوميدور 38th Anniversary المصمَّمة بالتعاون مع Carlos Fuente.',
        '[{"name":"DM Red Label","color":"#A0522D","force":"Medium-Full","wrapper":"Habano (بلون Colorado)","vitolas":[],"story":"تبغ نيكاراغوي من Estelí ووادي Jalapa، يُعتَّق خمس سنوات ثم اثني عشر شهرًا إضافيًا بعد التعبئة، وُلد من تعاون مع Manuel Quesada وNestor Plasencia ويُلف اليوم لدى Plasencia، بحسب الموقع الرسمي وCorona Cigar."},{"name":"DM2","color":"#6B4226","force":null,"wrapper":"غير معلن","vitolas":[],"story":"بثلاثة أشكال، White وBlack وRed، تُلف لدى Quesada في جمهورية الدومينيكان؛ وتناولتها الصحافة بين عامي 2018 و2021؛ وغير موجودة في متجر الشركة عام 2026."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Dos Amigos ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Dos Amigos',
        'nicaragua',
        '2025 — Jordi Llorens et Isidre Pineda, Barcelone',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'dosamigos87.com (consulté 2026-09-24 : nés à Barcelone, roulés à la main au Nicaragua sur tabacs de Jalapa, Estelí et Ometepe ; gamme Paster, Sidecar, Paladium et Zwoa Spezln avec cape, sous-cape et tripe détaillées ; aucune fabrique nommée) ; cigarjournal.com « Dos Amigos at Intertabac 2026 » (2026 : Jordi Llorens présente la gamme à Intertabac, lancement daté d''octobre 2025 ; aucune fabrique nommée)',
        NULL,
        'Dos Amigos naît à Barcelone de l''amitié de deux fondateurs réunis par le cigare, la musique et le goût de partager de grands moments, dit la maison sur son site. Jordi Llorens et Isidre Pineda lancent la marque en octobre 2025 et en présentent la gamme à Intertabac 2026.

Les cigares sont roulés à la main au Nicaragua, dit la maison, à partir de tabacs de Jalapa, d''Estelí et d''Ometepe ; ni le site de la maison ni la presse ne nomment la fabrique.

Le catalogue compte quatre lignes : Paster et Sidecar, en cape Équateur Rosado sur tripe nicaraguayenne ; Paladium, le même assemblage en double figurado vieilli douze mois ; et Zwoa Spezln, édition munichoise en cape équatorienne, présentée par la maison comme d''intensité moyenne.',
        '[{"name":"Paster","color":"#A0522D","force":null,"wrapper":"Équateur Rosado","vitolas":[],"story":"Cape Équateur Rosado, sous-cape et tripe du Nicaragua (Jalapa, Estelí, Ometepe), cepo 52 en boîtes de vingt-quatre, selon le site de la maison."},{"name":"Sidecar","color":"#A0522D","force":null,"wrapper":"Équateur Rosado","vitolas":[],"story":"Même assemblage que Paster, en cepo 54 et six pouces, selon le site de la maison."},{"name":"Paladium","color":"#A0522D","force":"Medium","wrapper":"Équateur Rosado","vitolas":[],"story":"Double figurado en cepo 58, vieilli douze mois après roulage ; la maison le présente comme medium et complexe."},{"name":"Zwoa Spezln","color":"#C9A96E","force":"Medium","wrapper":"Équateur","vitolas":[],"story":"Édition munichoise, cape équatorienne et tripe de Jalapa et Estelí en viso, présentée par la maison comme d''intensité moyenne."}]',
        'Dos Amigos was born in Barcelona from the friendship of two founders brought together by cigars, music and a shared taste for great moments, the company says on its website. Jordi Llorens and Isidre Pineda launched the brand in October 2025 and presented its range at Intertabac 2026.

The cigars are hand-rolled in Nicaragua, the company says, from tobaccos of Jalapa, Estelí and Ometepe; neither the company''s website nor the press names the factory.

The range comprises four lines: Paster and Sidecar, with an Ecuador Rosado wrapper over Nicaraguan filler; Paladium, the same blend in a double figurado aged twelve months; and Zwoa Spezln, a Munich edition with an Ecuadorian wrapper, presented by the company as medium in intensity.',
        '[{"name":"Paster","color":"#A0522D","force":null,"wrapper":"Ecuador Rosado","vitolas":[],"story":"Ecuador Rosado wrapper, Nicaraguan binder and filler (Jalapa, Estelí, Ometepe), 52 ring gauge in boxes of twenty-four, according to the company''s website."},{"name":"Sidecar","color":"#A0522D","force":null,"wrapper":"Ecuador Rosado","vitolas":[],"story":"Same blend as Paster, in a 54 ring gauge and six inches, according to the company''s website."},{"name":"Paladium","color":"#A0522D","force":"Medium","wrapper":"Ecuador Rosado","vitolas":[],"story":"Double figurado in a 58 ring gauge, aged twelve months after rolling; the company presents it as medium-bodied and complex."},{"name":"Zwoa Spezln","color":"#C9A96E","force":"Medium","wrapper":"Ecuador","vitolas":[],"story":"A Munich edition, with an Ecuadorian wrapper and Jalapa and Estelí viso filler, presented by the company as medium in intensity."}]',
        'Dos Amigos nace en Barcelona de la amistad de dos fundadores unidos por el puro, la música y el gusto por compartir grandes momentos, dice la casa en su sitio. Jordi Llorens e Isidre Pineda lanzan la marca en octubre de 2025 y presentan la gama en Intertabac 2026.

Los puros se lían a mano en Nicaragua, dice la casa, a partir de tabacos de Jalapa, Estelí y Ometepe; ni el sitio de la casa ni la prensa nombran la fábrica.

El catálogo cuenta con cuatro líneas: Paster y Sidecar, con capa Ecuador Rosado sobre tripa nicaragüense; Paladium, la misma mezcla en doble figurado añejado doce meses; y Zwoa Spezln, edición muniquesa con capa ecuatoriana, presentada por la casa como de intensidad media.',
        '[{"name":"Paster","color":"#A0522D","force":null,"wrapper":"Ecuador Rosado","vitolas":[],"story":"Capa Ecuador Rosado, capote y tripa de Nicaragua (Jalapa, Estelí, Ometepe), cepo 52 en cajas de veinticuatro, según el sitio de la casa."},{"name":"Sidecar","color":"#A0522D","force":null,"wrapper":"Ecuador Rosado","vitolas":[],"story":"Misma mezcla que Paster, en cepo 54 y seis pulgadas, según el sitio de la casa."},{"name":"Paladium","color":"#A0522D","force":"Medium","wrapper":"Ecuador Rosado","vitolas":[],"story":"Doble figurado en cepo 58, añejado doce meses tras el torcido; la casa lo presenta como de cuerpo medio y complejo."},{"name":"Zwoa Spezln","color":"#C9A96E","force":"Medium","wrapper":"Ecuador","vitolas":[],"story":"Edición muniquesa, con capa ecuatoriana y tripa de Jalapa y Estelí en viso, presentada por la casa como de intensidad media."}]',
        'Dos Amigos entsteht in Barcelona aus der Freundschaft zweier Gründer, die die Zigarre, die Musik und die Vorliebe für das gemeinsame Erleben großer Momente verbindet, so das Haus auf seiner Website. Jordi Llorens und Isidre Pineda lancieren die Marke im Oktober 2025 und stellen ihr Sortiment auf der Intertabac 2026 vor.

Die Zigarren werden laut dem Haus von Hand in Nicaragua gerollt, aus Tabaken aus Jalapa, Estelí und Ometepe; weder die Website des Hauses noch die Fachpresse nennen die Fabrik.

Das Sortiment umfasst vier Linien: Paster und Sidecar, mit Ecuador-Rosado-Deckblatt über nicaraguanischer Einlage; Paladium, dieselbe Mischung als doppeltes Figurado, zwölf Monate gereift; und Zwoa Spezln, eine Münchner Edition mit ecuadorianischem Deckblatt, die das Haus als mittlere Intensität beschreibt.',
        '[{"name":"Paster","color":"#A0522D","force":null,"wrapper":"Ecuador Rosado","vitolas":[],"story":"Ecuador-Rosado-Deckblatt, Umblatt und Einlage aus Nicaragua (Jalapa, Estelí, Ometepe), Ringmaß 52 in Kisten zu vierundzwanzig Stück, laut der Website des Hauses."},{"name":"Sidecar","color":"#A0522D","force":null,"wrapper":"Ecuador Rosado","vitolas":[],"story":"Gleiche Mischung wie Paster, mit Ringmaß 54 und sechs Zoll, laut der Website des Hauses."},{"name":"Paladium","color":"#A0522D","force":"Medium","wrapper":"Ecuador Rosado","vitolas":[],"story":"Doppeltes Figurado mit Ringmaß 58, nach dem Rollen zwölf Monate gereift; das Haus beschreibt es als mittelkräftig und komplex."},{"name":"Zwoa Spezln","color":"#C9A96E","force":"Medium","wrapper":"Ecuador","vitolas":[],"story":"Münchner Edition mit ecuadorianischem Deckblatt und Viso-Einlage aus Jalapa und Estelí, vom Haus als mittlere Intensität beschrieben."}]',
        'Dos Amigos诞生于Barcelona，源于两位创始人之间的友谊——因雪茄、音乐以及共同分享美好时光的爱好而结缘，据该品牌官网称。Jordi Llorens与Isidre Pineda于2025年10月推出该品牌，并于2026年Intertabac展会上展示了其产品系列。

据该品牌称，雪茄在尼加拉瓜手工卷制，采用产自Jalapa、Estelí与Ometepe的烟叶；无论是品牌官网还是媒体，均未指明卷制工厂。

产品目录共有四个系列：Paster与Sidecar，采用Ecuador Rosado茄衣，搭配尼加拉瓜茄芯；Paladium，采用相同配方，为双尖头（figurado）大规格，陈化十二个月；以及Zwoa Spezln，慕尼黑版本，采用厄瓜多尔茄衣，据该品牌称浓度中等。',
        '[{"name":"Paster","color":"#A0522D","force":null,"wrapper":"厄瓜多尔Rosado","vitolas":[],"story":"厄瓜多尔Rosado茄衣，尼加拉瓜茄套与茄芯（产自Jalapa、Estelí、Ometepe），52环径，二十四支装，据品牌官网称。"},{"name":"Sidecar","color":"#A0522D","force":null,"wrapper":"厄瓜多尔Rosado","vitolas":[],"story":"配方与Paster相同，54环径，长六英寸，据品牌官网称。"},{"name":"Paladium","color":"#A0522D","force":"Medium","wrapper":"厄瓜多尔Rosado","vitolas":[],"story":"双尖头（figurado）造型，58环径，卷制后陈化十二个月；该品牌将其描述为浓度中等、口感复杂。"},{"name":"Zwoa Spezln","color":"#C9A96E","force":"Medium","wrapper":"厄瓜多尔","vitolas":[],"story":"慕尼黑版本，采用厄瓜多尔茄衣，茄芯为产自Jalapa与Estelí的viso等级烟叶，据该品牌称浓度中等。"}]',
        'وُلدت Dos Amigos في برشلونة من صداقة جمعت بين مؤسسَين اجتمعا حول شغف السيجار والموسيقى وحب مشاركة اللحظات الكبيرة، بحسب موقع الشركة. وأطلق Jordi Llorens وIsidre Pineda العلامة في أكتوبر 2025، وقدّما تشكيلتها في معرض Intertabac عام 2026.

تُلف السيجارات يدويًا في نيكاراغوا، بحسب الشركة، من تبغ Jalapa وEstelí وOmetepe؛ ولا موقع الشركة ولا الصحافة يُسمّيان المصنع.

تضم التشكيلة أربع سلاسل: Paster وSidecar، بغلاف Ecuador Rosado فوق حشوة نيكاراغوية؛ وPaladium، بالمزيج نفسه في شكل double figurado يُعتَّق اثني عشر شهرًا؛ وZwoa Spezln، إصدار من ميونخ بغلاف إكوادوري، تصفه الشركة بأنه متوسط الشدة.',
        '[{"name":"Paster","color":"#A0522D","force":null,"wrapper":"الإكوادور Rosado","vitolas":[],"story":"غلاف Rosado إكوادوري، ورباط وحشوة من نيكاراغوا (Jalapa وEstelí وOmetepe)، بقياس حلقي 52 في علب من أربع وعشرين سيجارة، بحسب موقع الشركة."},{"name":"Sidecar","color":"#A0522D","force":null,"wrapper":"الإكوادور Rosado","vitolas":[],"story":"المزيج نفسه المستخدم في Paster، بقياس حلقي 54 وطول ست بوصات، بحسب موقع الشركة."},{"name":"Paladium","color":"#A0522D","force":"Medium","wrapper":"الإكوادور Rosado","vitolas":[],"story":"شكل double figurado بقياس حلقي 58، يُعتَّق اثني عشر شهرًا بعد اللف؛ وتصفه الشركة بأنه متوسط القوة ومركّب النكهة."},{"name":"Zwoa Spezln","color":"#C9A96E","force":"Medium","wrapper":"الإكوادور","vitolas":[],"story":"إصدار من ميونخ، بغلاف إكوادوري وحشوة viso من Jalapa وEstelí، تصفه الشركة بأنه متوسط الشدة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── T. Sonthi ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('T. Sonthi',
        'nicaragua',
        '2022 — Thomas Sontheimer, Laupheim (Allemagne)',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        't-sonthi.de (en allemand ; consulté via recherche : T. Sonthi Rum & Cigars, Thomas Sontheimer, Laupheim ; rhums depuis 2020, cigares faits main du Nicaragua depuis 2022 ; aucune fabrique nommée) ; cigarworld.de « T. Sonthi » et fiches produits « T. Sonthi Anne Bonny Claro », « T. Sonthi Blackbeard Maduro » (composition : cape équatorienne claro ou viso, sous-cape et tripe de Condega ; classe la marque parmi les cigares du Nicaragua sans nommer de fabrique).',
        NULL,
        'Thomas Sontheimer dirige à Laupheim, en Allemagne, la maison T. Sonthi Rum & Cigars : des rhums depuis 2020, puis des cigares faits main du Nicaragua à partir de 2022, dit le site de la maison, qui présente les deux activités comme les deux faces d''un même goût pour les spiritueux et le tabac vieillis.

Ni ce site ni le détaillant Cigarworld.de, qui classe la marque parmi les cigares du Nicaragua, ne nomment la fabrique qui les roule.

La gamme compte quatre lignes de tripe longue, toutes sur sous-cape et tripe de Condega, à quarante kilomètres au nord d''Estelí, selon Cigarworld.de : Anne Bonny, en cape équatorienne claro séchée quatre mois ; Blackbeard, en cape équatorienne viso fermentée huit mois en maduro ; Tortuga, en habillage naturel et format court ; et Luxury-Edition, en format long et bicolore. Les noms reprennent un thème pirate : Anne Bonny et Blackbeard, deux flibustiers historiques, Tortuga, l''île caribéenne repaire de pirates.',
        '[{"name":"Anne Bonny","color":"#C9A96E","force":null,"wrapper":"Équateur (claro)","vitolas":[],"story":"Cape équatorienne claro, récolte 2020 séchée quatre mois, sur sous-cape et tripe de Condega, selon Cigarworld.de."},{"name":"Blackbeard","color":"#6B4226","force":null,"wrapper":"Équateur (maduro)","vitolas":[],"story":"Cape équatorienne viso, récolte 2020 fermentée huit mois en maduro, mêmes sous-cape et tripe de Condega, selon Cigarworld.de."},{"name":"Tortuga","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Habillage naturel et format court, même tripe de Condega, selon Cigarworld.de."},{"name":"Luxury-Edition","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Format long et bicolore, sur la même tripe de Condega, selon Cigarworld.de."}]',
        'Thomas Sontheimer runs T. Sonthi Rum & Cigars in Laupheim, Germany: rums since 2020, then hand-made Nicaraguan cigars from 2022, says the company''s website, which presents the two activities as two sides of the same taste for aged spirits and tobacco.

Neither this website nor the retailer Cigarworld.de, which classes the brand among Nicaraguan cigars, names the factory that rolls them.

The range comprises four long-filler lines, all on a Condega binder and filler, forty kilometres north of Estelí, according to Cigarworld.de: Anne Bonny, with an Ecuadorian claro wrapper dried for four months; Blackbeard, with an Ecuadorian viso wrapper fermented for eight months into maduro; Tortuga, in a natural dress and short format; and Luxury-Edition, in a long, two-tone format. The names take up a pirate theme: Anne Bonny and Blackbeard, two historical buccaneers, and Tortuga, the Caribbean island that was a pirate haunt.',
        '[{"name":"Anne Bonny","color":"#C9A96E","force":null,"wrapper":"Ecuador (claro)","vitolas":[],"story":"Ecuadorian claro wrapper, 2020 harvest dried for four months, over Condega binder and filler, according to Cigarworld.de."},{"name":"Blackbeard","color":"#6B4226","force":null,"wrapper":"Ecuador (maduro)","vitolas":[],"story":"Ecuadorian viso wrapper, 2020 harvest fermented for eight months into maduro, the same Condega binder and filler, according to Cigarworld.de."},{"name":"Tortuga","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Natural dress and short format, the same Condega filler, according to Cigarworld.de."},{"name":"Luxury-Edition","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Long, two-tone format, on the same Condega filler, according to Cigarworld.de."}]',
        'Thomas Sontheimer dirige en Laupheim, Alemania, la casa T. Sonthi Rum & Cigars: rones desde 2020, y después puros hechos a mano de Nicaragua a partir de 2022, dice el sitio de la casa, que presenta ambas actividades como las dos caras de un mismo gusto por los espirituosos y el tabaco añejados.

Ni este sitio ni el detallista Cigarworld.de, que clasifica la marca entre los puros de Nicaragua, nombran la fábrica que los elabora.

La gama cuenta con cuatro líneas de tripa larga, todas con capote y tripa de Condega, a cuarenta kilómetros al norte de Estelí, según Cigarworld.de: Anne Bonny, con capa ecuatoriana claro secada cuatro meses; Blackbeard, con capa ecuatoriana viso fermentada ocho meses en maduro; Tortuga, en vitolado natural y formato corto; y Luxury-Edition, en formato largo y bicolor. Los nombres retoman un tema pirata: Anne Bonny y Blackbeard, dos filibusteros históricos, y Tortuga, la isla caribeña refugio de piratas.',
        '[{"name":"Anne Bonny","color":"#C9A96E","force":null,"wrapper":"Ecuador (claro)","vitolas":[],"story":"Capa ecuatoriana claro, cosecha de 2020 secada cuatro meses, sobre capote y tripa de Condega, según Cigarworld.de."},{"name":"Blackbeard","color":"#6B4226","force":null,"wrapper":"Ecuador (maduro)","vitolas":[],"story":"Capa ecuatoriana viso, cosecha de 2020 fermentada ocho meses en maduro, mismos capote y tripa de Condega, según Cigarworld.de."},{"name":"Tortuga","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Vitolado natural y formato corto, misma tripa de Condega, según Cigarworld.de."},{"name":"Luxury-Edition","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Formato largo y bicolor, con la misma tripa de Condega, según Cigarworld.de."}]',
        'Thomas Sontheimer leitet in Laupheim, Deutschland, das Haus T. Sonthi Rum & Cigars: Rum seit 2020, dann handgefertigte nicaraguanische Zigarren ab 2022, so die Website des Hauses, die die beiden Tätigkeiten als zwei Seiten derselben Vorliebe für gereifte Spirituosen und Tabak darstellt.

Weder diese Website noch der Händler Cigarworld.de, der die Marke unter den nicaraguanischen Zigarren einordnet, nennt die Fabrik, die sie rollt.

Das Sortiment umfasst laut Cigarworld.de vier Long-Filler-Linien, alle mit Umblatt und Einlage aus Condega, vierzig Kilometer nördlich von Estelí: Anne Bonny, mit ecuadorianischem Claro-Deckblatt, vier Monate getrocknet; Blackbeard, mit ecuadorianischem Viso-Deckblatt, acht Monate zu Maduro fermentiert; Tortuga, in natürlicher Aufmachung und kurzem Format; und Luxury-Edition, in langem, zweifarbigem Format. Die Namen greifen ein Piratenthema auf: Anne Bonny und Blackbeard, zwei historische Freibeuter, und Tortuga, die karibische Insel, die als Piratennest galt.',
        '[{"name":"Anne Bonny","color":"#C9A96E","force":null,"wrapper":"Ecuador (Claro)","vitolas":[],"story":"Ecuadorianisches Claro-Deckblatt, Ernte 2020, vier Monate getrocknet, über Umblatt und Einlage aus Condega, laut Cigarworld.de."},{"name":"Blackbeard","color":"#6B4226","force":null,"wrapper":"Ecuador (Maduro)","vitolas":[],"story":"Ecuadorianisches Viso-Deckblatt, Ernte 2020, acht Monate zu Maduro fermentiert, gleiches Umblatt und gleiche Einlage aus Condega, laut Cigarworld.de."},{"name":"Tortuga","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Natürliche Aufmachung und kurzes Format, gleiche Einlage aus Condega, laut Cigarworld.de."},{"name":"Luxury-Edition","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Langes, zweifarbiges Format, mit gleicher Einlage aus Condega, laut Cigarworld.de."}]',
        'Thomas Sontheimer在德国的Laupheim经营T. Sonthi Rum & Cigars：自2020年起经营朗姆酒，自2022年起推出尼加拉瓜手工雪茄，据该品牌官网称；网站将这两项业务描述为对陈年烈酒与烟草的同一种喜爱的两个方面。

无论是该网站，还是将该品牌归类为尼加拉瓜雪茄的经销商Cigarworld.de，均未指明卷制工厂。

据Cigarworld.de称，该系列共有四条长茄芯产品线，均采用产自Condega（位于Estelí以北四十公里处）的茄套与茄芯：Anne Bonny，采用经过四个月干燥的厄瓜多尔claro茄衣；Blackbeard，采用经过八个月发酵制成maduro的厄瓜多尔viso茄衣；Tortuga，天然外观，规格较短；以及Luxury-Edition，规格较长，双色外观。这些名称均取自海盗主题：Anne Bonny与Blackbeard是两位历史上真实存在的海盗，Tortuga则是加勒比海一座曾为海盗巢穴的岛屿。',
        '[{"name":"Anne Bonny","color":"#C9A96E","force":null,"wrapper":"厄瓜多尔（claro）","vitolas":[],"story":"厄瓜多尔claro茄衣，2020年采收，干燥四个月，搭配Condega茄套与茄芯，据Cigarworld.de称。"},{"name":"Blackbeard","color":"#6B4226","force":null,"wrapper":"厄瓜多尔（maduro）","vitolas":[],"story":"厄瓜多尔viso茄衣，2020年采收，发酵八个月制成maduro，同样搭配Condega茄套与茄芯，据Cigarworld.de称。"},{"name":"Tortuga","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"天然外观，规格较短，同样采用Condega茄芯，据Cigarworld.de称。"},{"name":"Luxury-Edition","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"规格较长，双色外观，同样采用Condega茄芯，据Cigarworld.de称。"}]',
        'يدير Thomas Sontheimer في مدينة Laupheim بألمانيا دار T. Sonthi Rum & Cigars: روم منذ عام 2020، ثم سيجار نيكاراغوي مصنوع يدويًا ابتداءً من عام 2022، بحسب موقع الشركة، الذي يقدّم النشاطين باعتبارهما وجهين لولع واحد بالمشروبات الروحية والتبغ المُعتَّقين.

لا هذا الموقع ولا تاجر التجزئة Cigarworld.de، الذي يصنّف العلامة ضمن سيجار نيكاراغوا، يُسمّي المصنع الذي يلفّه.

تضم التشكيلة أربع سلاسل بحشوة طويلة، كلها برباط وحشوة من Condega، على بعد أربعين كيلومترًا شمال Estelí، بحسب Cigarworld.de: Anne Bonny، بغلاف إكوادوري من نوع claro مُجفَّف أربعة شهور؛ وBlackbeard، بغلاف إكوادوري من نوع viso مُخمَّر ثمانية شهور ليصبح maduro؛ وTortuga، بمظهر طبيعي ومقاس قصير؛ وLuxury-Edition، بمقاس طويل وبلونين. وتستعيد الأسماء طابعًا قرصانيًا: فAnne Bonny وBlackbeard قرصانان تاريخيان، وTortuga الجزيرة الكاريبية التي كانت ملاذًا للقراصنة.',
        '[{"name":"Anne Bonny","color":"#C9A96E","force":null,"wrapper":"الإكوادور (claro)","vitolas":[],"story":"غلاف إكوادوري من نوع claro، من محصول عام 2020 ومُجفَّف أربعة شهور، فوق رباط وحشوة من Condega، بحسب Cigarworld.de."},{"name":"Blackbeard","color":"#6B4226","force":null,"wrapper":"الإكوادور (maduro)","vitolas":[],"story":"غلاف إكوادوري من نوع viso، من محصول عام 2020 ومُخمَّر ثمانية شهور ليصبح maduro، بنفس رباط وحشوة Condega، بحسب Cigarworld.de."},{"name":"Tortuga","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"بمظهر طبيعي ومقاس قصير، بنفس حشوة Condega، بحسب Cigarworld.de."},{"name":"Luxury-Edition","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"بمقاس طويل وبلونين، وبنفس حشوة Condega، بحسب Cigarworld.de."}]')
