s ; cigares dès 1995, aujourd''hui roulés chez Plasencia (Nicaragua).","iconic":false},{"name":"Dos Amigos","desc":"2025 — Barcelone ; roulée à la main au Nicaragua, fabrique non nommée.","iconic":false},{"name":"T. Sonthi","desc":"2022 — cigares faits main du Nicaragua, fabrique non nommée (Laupheim, Allemagne).","iconic":false}]' WHERE `id` = 'nicaragua';

-- ── PANAMA : `brands` relu dans la base et réécrit en littéral complet (2 entrées) ──
UPDATE `producer_countries` SET `brands` = '[{"name":"Joyas de Panamá","desc":"Fondée en février 1986 par Miriam Padilla ; roulage entièrement à la main, semence cubaine ; atelier rouvert en 2023 par son fils Braulio Zurita","iconic":true},{"name":"Darier & Cleef","desc":"Tabacalera panaméenne qui revendique 1881 ; tabac entièrement panaméen roulé à la main en tripe longue","iconic":false}]' WHERE `id` = 'panama';

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Arnold André','D''Crossier','Bugatti','Caoba','Castillo de Reyes','Dios del Sol','Flor del Sol','Kinix','Rodrigo de Jerez','Wolfertz','American Caribbean Cigars','Darier & Cleef','Daniel Marshall','Dos Amigos','T. Sonthi')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 240';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 240','systeme','recensement_8_fiches','marque',0,
   'dominican : Arnold André, D''Crossier, Bugatti, Caoba, Castillo de Reyes'),
  (NULL,'migration 240','systeme','recensement_8_fiches','marque',0,
   'honduras : Dios del Sol, Flor del Sol, Kinix, Rodrigo de Jerez, Wolfertz'),
  (NULL,'migration 240','systeme','recensement_8_fiches','marque',0,
   'nicaragua : American Caribbean Cigars, Daniel Marshall, Dos Amigos, T. Sonthi'),
  (NULL,'migration 240','systeme','recensement_8_fiches','marque',0,
   'panama : Darier & Cleef');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Arnold André','D''Crossier','Bugatti','Caoba','Castillo de Reyes','Dios del Sol','Flor del Sol','Kinix','Rodrigo de Jerez','Wolfertz','American Caribbean Cigars','Darier & Cleef','Daniel Marshall','Dos Amigos','T. Sonthi')) = 15 AS fiches,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Arnold André"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"D''Crossier"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Bugatti"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Caoba"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Castillo de Reyes"') FROM `producer_countries` WHERE `id` = 'dominican') AS dominican_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Dios del Sol"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Flor del Sol"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Kinix"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Rodrigo de Jerez"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Wolfertz"') FROM `producer_countries` WHERE `id` = 'honduras') AS honduras_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"American Caribbean Cigars"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Daniel Marshall"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Dos Amigos"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"T. Sonthi"') FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Darier & Cleef"') FROM `producer_countries` WHERE `id` = 'panama') AS panama_annonce,
  (SELECT COUNT(*) FROM `translation_status` WHERE `entite` = 'brands' AND `entite_id` IN ('Arnold André','D''Crossier','Bugatti','Caoba','Castillo de Reyes','Dios del Sol','Flor del Sol','Kinix','Rodrigo de Jerez','Wolfertz','American Caribbean Cigars','Darier & Cleef','Daniel Marshall','Dos Amigos','T. Sonthi')) = 150 AS sceaux,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 240') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
